#[test]
fn whole_function_refinement_witness_fails_closed_on_guarded_return() {
    // FAIL-CLOSED (2): a guarded control-flow return (branch / SwitchInt) is NOT
    // in the straight-line fragment the refinement theorem covers — its SemReturn
    // witness is unrecoverable (the Return block carries no `_0 := …`), so the
    // witness is None (never a false certificate). This is the HONEST SCOPE
    // boundary: branches are DEFERRED, not falsely claimed.
    let func = guarded_div_cf_func();
    assert!(
        whole_function_refinement_witness(&func).is_none(),
        "a guarded control-flow return is DEFERRED from the refinement fragment"
    );
}

