#[test]
fn wrong_return_refinement_mismatch_fails_closed() {
    // FAIL-CLOSED (3, sharpened): build a refinement instance whose STATED return
    // operand differs from the proof term's applied return — the proof
    // `refinement e STMTS nil (Var 0)` must NOT inhabit the statement claiming
    // return `Const 999`. This is the genuine wrong-return fail-closed check.
    let env = mirsem_refinement_env().expect("env");
    let bd = || BinderData::from(BinderInfo::Default);
    let stmts = vec![SemStmt {
        idx: 0,
        rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(0), SemOperand::Const(1)),
    }];
    let stmts_e = stmts_list_expr(&stmts);
    let nil = Expr::app(
        Expr::const_(Name::from_string("List.nil"), vec![Level::zero()]),
        cst(MIRSEM_STMT),
    );
    // STATED type uses ret = Const 999.
    let ret_stated = SemOperand::Const(999).to_operand_expr();
    let args_stated = |e: Expr| [e, stmts_e.clone(), nil.clone(), ret_stated.clone()];
    let lhs = Expr::apps(cst(MIRSEM_EXEC_THREADED), args_stated(Expr::bvar(0)));
    let rhs = Expr::apps(cst(MIRSEM_DENOTE_SUBST), args_stated(Expr::bvar(0)));
    let stated_ty = Expr::pi(bd(), env_ty(), eq_int_expr(lhs, rhs));
    // PROOF applies the general theorem at ret = Var 0 (the WRONG return for the
    // stated Const-999 type).
    let ret_proof = SemOperand::Var(0).to_operand_expr();
    let proof = Expr::lam(
        bd(),
        env_ty(),
        Expr::apps(
            cst(MIRSEM_REFINEMENT),
            [Expr::bvar(0), stmts_e.clone(), nil.clone(), ret_proof],
        ),
    );
    let tc = TypeChecker::new(&env);
    assert!(
        tc.check_type(&proof, &stated_ty).is_err(),
        "a refinement instance with a MISMATCHED return operand MUST be \
         kernel-rejected (wrong-return fail-closed)"
    );
}

