// ---- Step 2: Lemma 1A, each operand form proven modulo 3 ----

#[test]
fn lemma_1a_const_adequacy_proven_modulo_3() {
    // Const c: eval e (Const c) = c  (the literal grounds to int_lit c).
    assert_eq!(check_operand_adequacy(&SemOperand::Const(5)), AdequacyVerdict::ProvenModulo3);
    assert_eq!(check_operand_adequacy(&SemOperand::Const(-7)), AdequacyVerdict::ProvenModulo3);
    assert_eq!(check_operand_adequacy(&SemOperand::Const(0)), AdequacyVerdict::ProvenModulo3);
}

#[test]
fn lemma_1a_var_adequacy_proven_modulo_3() {
    // Var p: eval e (Var p) = e p  (the parameter grounds to the env binding).
    assert_eq!(check_operand_adequacy(&SemOperand::Var(0)), AdequacyVerdict::ProvenModulo3);
    assert_eq!(check_operand_adequacy(&SemOperand::Var(3)), AdequacyVerdict::ProvenModulo3);
}

#[test]
fn lemma_1a_move_adequacy_proven_modulo_3() {
    // Move src: eval e (Move src) = eval e src  (transparent move).
    assert_eq!(
        check_operand_adequacy(&SemOperand::Move(Box::new(SemOperand::Var(1)))),
        AdequacyVerdict::ProvenModulo3
    );
    assert_eq!(
        check_operand_adequacy(&SemOperand::Move(Box::new(SemOperand::Const(42)))),
        AdequacyVerdict::ProvenModulo3
    );
    // Nested move: Move (Move (Const 9)).
    assert_eq!(
        check_operand_adequacy(&SemOperand::Move(Box::new(SemOperand::Move(Box::new(
            SemOperand::Const(9)
        ))))),
        AdequacyVerdict::ProvenModulo3
    );
}

// ---- Step 2 (GROUNDER-CONNECTED): the LIVE ground_int output IS the eval shape ----

#[test]
fn lemma_1a_rhs_is_the_live_ground_int_output() {
    // GUARD (live grounder, Lemma 1A): the per-operand adequacy's RHS must be the
    // ACTUAL term `clean_ground::ground_int(O.to_formula())` emits, and `eval E O`
    // must def-eq it. We INVOKE the live grounder (not a hand-built denotation), so
    // the per-op adequacy is mechanically grounder-connected. For `Var 0`, the live
    // grounder gives the bound binder `x_0`; `eval (set base 0 x_0) (Var 0)` reduces
    // to `x_0` — def-eq.
    let env = mirsem_env().expect("env");
    let tc = TypeChecker::new(&env);
    for op in [
        SemOperand::Var(0),
        SemOperand::Const(5),
        SemOperand::Move(Box::new(SemOperand::Var(0))),
    ] {
        let mut indices = Vec::new();
        op.var_indices(&mut indices);
        let n = indices.len();
        let grounded = live_ground_int(&op.to_formula(), &indices)
            .expect("the LIVE grounder must ground this operand's reflected formula");
        let env_e = grounding_env_expr(&indices, &|i| {
            Expr::bvar(u32::try_from(n - 1 - i).unwrap_or(0))
        });
        let eval_term = Expr::apps(cst(MIRSEM_EVAL), [env_e, op.to_operand_expr()]);
        assert!(
            tc.is_def_eq(&eval_term, &grounded),
            "eval E {op:?} must be def-eq to the LIVE ground_int output {grounded:?}"
        );
    }
}

#[test]
fn lemma_1a_grounder_connected_wrong_shape_fails_closed() {
    // GUARD (fail closed): claiming a WRONG live-grounder shape (e.g. `eval E (Var 0)
    // = int_lit 7`, a constant where the grounder emits the bound binder) must NOT
    // type-check — the grounder-connected adequacy is fail-closed.
    let wrong = int_lit(7);
    assert!(
        matches!(
            check_operand_adequacy_inner(&SemOperand::Var(0), Some(&wrong)),
            AdequacyVerdict::KernelRejected(_)
        ),
        "a wrong grounder-shape claim (Var 0 = 7) MUST be kernel-rejected"
    );
}

#[test]
fn lemma_1b_rhs_is_the_live_ground_int_output() {
    // GUARD (live grounder, Lemma 1B): the rvalue adequacy's RHS must be the ACTUAL
    // `clean_ground::ground_int(R.to_formula())` term, and `eval_rvalue E R` must
    // def-eq it. Covers `x + y` (two distinct vars), `x + 1` (var + const), and
    // `x / y` (the Opaque Int.div head) — INVOKING the live grounder each time.
    let env = mirsem_env().expect("env");
    let tc = TypeChecker::new(&env);
    for rv in [
        SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(0), SemOperand::Var(1)),
        SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(0), SemOperand::Const(1)),
        SemRvalue::Bin(SemBinOp::Div, SemOperand::Var(0), SemOperand::Var(1)),
        SemRvalue::Use(SemOperand::Var(0)),
    ] {
        let indices = rv.var_indices();
        let n = indices.len();
        let grounded = live_ground_int(&rv.to_formula(), &indices)
            .expect("the LIVE grounder must ground this rvalue's reflected formula");
        let env_e = grounding_env_expr(&indices, &|i| {
            Expr::bvar(u32::try_from(n - 1 - i).unwrap_or(0))
        });
        let eval_term = Expr::apps(cst(MIRSEM_EVAL_RVALUE), [env_e, rv.to_rvalue_expr()]);
        assert!(
            tc.is_def_eq(&eval_term, &grounded),
            "eval_rvalue E {rv:?} must be def-eq to the LIVE ground_int output {grounded:?}"
        );
    }
}

