// ---- Step 2B (Div widening): Lemma 1B over `/` proven modulo 3 ----

#[test]
fn lemma_1b_div_adequacy_proven_modulo_3() {
    // Bin Div a b: eval_rvalue e (Bin Div a b) = Int.div (eval e a) (eval e b),
    // the EXACT shape ground_int emits for Formula::Div (clean_ground.rs:
    // `F::Div(a,b) => app2("Int.div", g(a), g(b))`). `Int.div` is the prelude's
    // Opaque (native-reduced, NON-axiom) constant — adequacy is Eq.refl by
    // ι-reduction WITHOUT unfolding `Int.div`: both sides name the same opaque
    // head applied to def-equal args. Division semantics are not needed.
    for (a, b) in [
        (SemOperand::Var(0), SemOperand::Var(1)),
        (SemOperand::Var(0), SemOperand::Const(2)),
        (SemOperand::Const(10), SemOperand::Var(1)),
        (SemOperand::Move(Box::new(SemOperand::Var(0))), SemOperand::Const(3)),
    ] {
        assert_eq!(
            check_rvalue_adequacy(&SemRvalue::Bin(SemBinOp::Div, a.clone(), b.clone())),
            AdequacyVerdict::ProvenModulo3,
            "Div({a:?}, {b:?}) adequacy must prove modulo 3"
        );
    }
}

#[test]
fn lemma_1b_div_adequacy_axiom_deps_foundational() {
    // The Div rvalue-adequacy lemma's transitive axiom closure must be ⊆ the 3
    // foundational axioms — `Int.div`'s Opaque (non-Axiom) status means a term
    // referencing it gains NO axiom dependency. (A `Residue` verdict — a 4th
    // axiom — would FAIL here; ProvenModulo3 IS the modulo-3 audit.)
    let verdict = check_rvalue_adequacy(&SemRvalue::Bin(
        SemBinOp::Div,
        SemOperand::Var(0),
        SemOperand::Var(1),
    ));
    assert_eq!(
        verdict,
        AdequacyVerdict::ProvenModulo3,
        "Div adequacy must rest on ONLY the 3 foundational axioms (Int.div is Opaque, \
         not an Axiom), got {verdict:?}"
    );
}

#[test]
fn div_eval_rvalue_shape_matches_ground_int_emission() {
    // SHAPE TEST: the MirSem Div denotation MUST be byte-identical to what
    // clean_ground::ground_int emits for the reflected `Formula::Div(a, b)` —
    // `app2("Int.div", g(a), g(b))`. We can't call the private ground_int from
    // here, but its arm is fixed (`Int.div` head, two args in order); confirm the
    // MirSem `denotation` builds exactly that head + arg order, so the adequacy is
    // matched to REALITY, not assumed.
    let e_ref = Expr::bvar(0);
    let denot = SemRvalue::Bin(SemBinOp::Div, SemOperand::Var(0), SemOperand::Const(2))
        .denotation(&e_ref);
    // Expected: Int.div (eval-style denot of Var 0) (denot of Const 2).
    let expected = int_binop_expr(
        &SemBinOp::Div,
        SemOperand::Var(0).denotation(&e_ref),
        SemOperand::Const(2).denotation(&e_ref),
    );
    assert_eq!(denot, expected, "MirSem Div denotation must be `Int.div a b` in order");
    // And the head is literally `Int.div` (the ground_int arm), not `Int.tdiv`/etc:
    // the term type-checks against `Int` in the MirSem env, confirming `Int.div`
    // resolves to the registered prelude constant.
    let env = mirsem_env().expect("env");
    let tc = TypeChecker::new(&env);
    let lit_div = int_binop_expr(&SemBinOp::Div, int_lit(7), int_lit(2));
    let inferred = tc.infer_type(&lit_div).expect("Int.div 7 2 has a type");
    assert!(
        tc.is_def_eq(&inferred, &int_ty()),
        "Int.div applied to two Ints must be an Int, got {inferred:?}"
    );
}

