// =======================================================================
// Trust: DEREF-MATERIALIZATION GUARD TEMP (WALL-JOINTEMP, 2026-07-16) — the
// single-range u8 ascii predicates (`u8::is_ascii_{digit,octdigit,uppercase,
// lowercase,graphic}`): a `lo <= *self && *self <= hi` range check whose body
// (a) materializes `*self` into a temp `_3 := Use(Copy(*_1))` ONCE and compares
// `_3` against BOTH bounds, and (b) writes the AND-diamond result to a join-temp
// `_2` and returns it via `_0 := Use(Copy(_2))`. (b) was already admitted (the
// join-via-temp return move); (a) is the new normalization: the deref-mat temp
// must resolve to the SAME `Var(0)` a direct `*self` read produces.
// =======================================================================

/// Build the EXACT `u8::is_ascii_digit` MIR shape (deref-materialization temp
/// `_3` + AND-diamond join-temp `_2` + `_0 := Copy(_2)` return). `mutate` gets a
/// mutable handle to bb0's `_3 := …` statement so a forgery probe can corrupt the
/// deref-materialization.
fn u8_range_predicate_join_temp_body(
    mutate: impl FnOnce(&mut trust_types::Statement),
) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
        SourceSpan, Statement, Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    let sp = SourceSpan::default;
    // `_3 := Use(Copy(*_1))` — the deref-materialization the forgery may corrupt.
    let mut s3 = Statement::Assign {
        place: Place { local: 3, projections: vec![] },
        rvalue: Rvalue::Use(Operand::Copy(Place {
            local: 1,
            projections: vec![Projection::Deref],
        })),
        span: sp(),
    };
    mutate(&mut s3);
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl {
                index: 1,
                ty: Ty::Ref { mutable: false, inner: Box::new(u8t()) },
                name: Some("self".into()),
            },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: u8t(), name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
            LocalDecl { index: 5, ty: Ty::Bool, name: None },
        ],
        blocks: vec![
            BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    s3,
                    // `_4 := Le(48, Copy(_3))` — reads the materialized temp.
                    Statement::Assign {
                        place: Place { local: 4, projections: vec![] },
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Le,
                            Operand::Constant(ConstValue::Uint(48, 8)),
                            Operand::Copy(Place::local(3)),
                        ),
                        span: sp(),
                    },
                ],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Copy(Place::local(4)),
                    targets: vec![(0, BlockId(3))],
                    otherwise: BlockId(1),
                    exhaustive_enum_unreachable: false,
                    span: sp(),
                },
            },
            BasicBlock {
                id: BlockId(1),
                stmts: vec![
                    // `_5 := Le(Copy(_3), 57)` — reads the materialized temp again.
                    Statement::Assign {
                        place: Place { local: 5, projections: vec![] },
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Le,
                            Operand::Copy(Place::local(3)),
                            Operand::Constant(ConstValue::Uint(57, 8)),
                        ),
                        span: sp(),
                    },
                ],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Copy(Place::local(5)),
                    targets: vec![(0, BlockId(3))],
                    otherwise: BlockId(2),
                    exhaustive_enum_unreachable: false,
                    span: sp(),
                },
            },
            // THEN arm (both bounds hold) — writes the join-temp `_2`.
            BasicBlock {
                id: BlockId(2),
                stmts: vec![Statement::Assign {
                    place: Place { local: 2, projections: vec![] },
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                    span: sp(),
                }],
                terminator: Terminator::Goto(BlockId(4)),
            },
            // ELSE arm — writes the join-temp `_2`.
            BasicBlock {
                id: BlockId(3),
                stmts: vec![Statement::Assign {
                    place: Place { local: 2, projections: vec![] },
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(false))),
                    span: sp(),
                }],
                terminator: Terminator::Goto(BlockId(4)),
            },
            // JOIN — `_0 := Copy(_2)` then Return (the already-admitted join move).
            BasicBlock {
                id: BlockId(4),
                stmts: vec![Statement::Assign {
                    place: Place { local: 0, projections: vec![] },
                    rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                    span: sp(),
                }],
                terminator: Terminator::Return,
            },
        ],
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    VerifiableFunction {
        name: "is_ascii_digit".to_string(),
        def_path: "u8::is_ascii_digit".to_string(),
        span: SourceSpan::default(),
        body,
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

/// The single-range join-temp shape is recognized, the deref-materialization
/// temp `_3` resolves to `Var(0)` (self's own param slot, NOT a raw local), the
/// guarded return is `48 <= x && x <= 57 ? true : false`, and the CONTROL-FLOW
/// adequacy witness is kernel-checked modulo 3 — a real kernel promotion, not a
/// shape-only accept.
#[test]
fn u8_range_predicate_join_temp_resolves_deref_mat_and_certifies_modulo_3() {
    let func = u8_range_predicate_join_temp_body(|_| {});
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };

    let cfr = sem_cf_return_of_mir(&func, &param_index).expect(
        "the single-range u8 predicate (deref-mat temp + join-temp) must be recognized",
    );
    // Every operand resolved to the self param — the deref-mat temp `_3` did NOT
    // leak as a spurious raw local index.
    assert_eq!(
        cfr.var_indices(),
        vec![0],
        "the materialized `*self` temp must resolve to Var(0), the sole variable"
    );
    // The guard is the conjunctive range `48 <= x && x <= 57`, arms true/false.
    assert_eq!(
        cfr.cond,
        SemCondTree::And(
            Box::new(SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Le,
                a: SemOperand::Const(48),
                b: SemOperand::Var(0),
            })),
            Box::new(SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Le,
                a: SemOperand::Var(0),
                b: SemOperand::Const(57),
            })),
        ),
    );
    assert_eq!(cfr.then_rv, SemRvalue::Use(SemOperand::Const(1)));
    assert_eq!(cfr.else_rv, SemRvalue::Use(SemOperand::Const(0)));

    let cert = cf_return_adequacy_witness(&cfr)
        .expect("the join-temp range predicate gets a modulo-3 CF-return certificate");
    assert!(cert.is_modulo_3());
}

/// FAIL-CLOSED forgery probes: the deref-materialization tier admits ONLY a pure
/// value-identity copy of a `&{int}` parameter's deref. A NON-IDENTITY arithmetic
/// transform, a copy of a DIFFERENT local, a copy through a `&mut` alias, and a
/// deref of a NON-parameter base each fail the recognizer (`None`) rather than
/// being silently absorbed — no false PROVE.
#[test]
fn u8_range_predicate_deref_mat_forgeries_all_decline() {
    use trust_types::{ConstValue, Operand, Place, Projection, Rvalue, Statement};
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };

    // Positive control: the faithful body IS recognized (guards the differential).
    assert!(
        sem_cf_return_of_mir(&u8_range_predicate_join_temp_body(|_| {}), &param_index)
            .is_some()
    );

    // (1) NON-IDENTITY ARITH — `_3 := Add(Copy(*_1), 1)` is a mutated value, not a
    //     copy. Must NOT be absorbed as if it were `*self`.
    let arith = u8_range_predicate_join_temp_body(|s| {
        if let Statement::Assign { rvalue, .. } = s {
            *rvalue = Rvalue::BinaryOp(
                trust_types::BinOp::Add,
                Operand::Copy(Place { local: 1, projections: vec![Projection::Deref] }),
                Operand::Constant(ConstValue::Uint(1, 8)),
            );
        }
    });
    assert!(
        sem_cf_return_of_mir(&arith, &param_index).is_none(),
        "a non-identity arithmetic transform of *self must decline"
    );

    // (2) WRONG TEMP — `_3 := Copy(_2)` copies the join-temp bool, a DIFFERENT
    //     local, not the deref.
    let wrong = u8_range_predicate_join_temp_body(|s| {
        if let Statement::Assign { rvalue, .. } = s {
            *rvalue = Rvalue::Use(Operand::Copy(Place::local(2)));
        }
    });
    assert!(
        sem_cf_return_of_mir(&wrong, &param_index).is_none(),
        "a copy of a different (non-deref) local must decline"
    );

    // (3) MUT-REF PARAM — `_1 : &mut u8`; a mutable alias could reassign the
    //     referent between the read and its use.
    let mut mutref = u8_range_predicate_join_temp_body(|_| {});
    if let trust_types::Ty::Ref { mutable, .. } = &mut mutref.body.locals[1].ty {
        *mutable = true;
    }
    assert!(
        sem_cf_return_of_mir(&mutref, &param_index).is_none(),
        "a deref through a &mut parameter must decline"
    );

    // (4) DEREF OF NON-PARAM — `_3 := Copy(*_1)` but `_1` is NOT a parameter
    //     (param_index maps nothing). The delegated GAP-DEREF-SELF arm requires a
    //     parameter base.
    let no_param = |_local: usize| -> Option<u64> { None };
    assert!(
        sem_cf_return_of_mir(&u8_range_predicate_join_temp_body(|_| {}), &no_param).is_none(),
        "a deref of a non-parameter base must decline"
    );
}

// =======================================================================
// Trust: BOOL-CONNECTIVE (BitOr-on-Bool multi-join, 2026-07-08) — the
// `is_ascii_alphanumeric`-class shape: `_a := cmp1; _b := cmp2; _0 :=
// BitOr(_a, _b)`. `SemRvalue::Or`/`And`, RECURSIVE over `Cmp` operands
// exactly like `Cmp` itself is recursive, reusing `resolve_cmp_side`'s
// EXISTING temp-inlining discipline verbatim (no new recognizer plumbing).
// =======================================================================

/// The `Or`/`And` rvalue's kernel adequacy certificate (Lemma 1B) — a flat
/// `cmp1 | cmp2`/`cmp1 & cmp2`, and a NESTED `(cmp1 & cmp2) | cmp3` (the
/// recursive constructor's whole reason to exist) — all `ProvenModulo3`.
#[test]
fn bool_connective_rvalue_is_certified_modulo_3() {
    let flat_or = SemRvalue::Or(
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Le,
            Box::new(SemRvalue::Use(SemOperand::Const(48))),
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
        )),
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Le,
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
            Box::new(SemRvalue::Use(SemOperand::Const(57))),
        )),
    );
    let cert = rvalue_adequacy_witness(&flat_or)
        .expect("a flat Or-of-comparisons gets a modulo-3 certificate");
    assert!(cert.is_modulo_3());

    let flat_and = SemRvalue::And(
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Lt,
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
            Box::new(SemRvalue::Use(SemOperand::Const(10))),
        )),
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Lt,
            Box::new(SemRvalue::Use(SemOperand::Const(0))),
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
        )),
    );
    let and_cert = rvalue_adequacy_witness(&flat_and)
        .expect("a flat And-of-comparisons gets a modulo-3 certificate");
    assert!(and_cert.is_modulo_3());

    // NESTED: `(0<=v && v<=9) || v==32` — an And nested inside an Or.
    let nested = SemRvalue::Or(
        Box::new(SemRvalue::And(
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Le,
                Box::new(SemRvalue::Use(SemOperand::Const(0))),
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
            )),
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Le,
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
                Box::new(SemRvalue::Use(SemOperand::Const(9))),
            )),
        )),
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Eq,
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
            Box::new(SemRvalue::Use(SemOperand::Const(32))),
        )),
    );
    let nested_cert = rvalue_adequacy_witness(&nested)
        .expect("a nested And-inside-Or rvalue gets a modulo-3 certificate");
    assert!(nested_cert.is_modulo_3());
    assert_eq!(nested_cert.rvalue, nested);
}

/// SOUNDNESS non-collapse: `Or`'s TRUE VALUE is not an arbitrary claim —
/// asserting the wrong 0/1 constant is `KernelRejected`, never proven.
#[test]
fn bool_connective_wrong_claimed_value_is_kernel_rejected() {
    // `(5 <= 3) || (5 <= 3)` is `false` (0), never `true` (1).
    let rv = SemRvalue::Or(
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Le,
            Box::new(SemRvalue::Use(SemOperand::Const(5))),
            Box::new(SemRvalue::Use(SemOperand::Const(3))),
        )),
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Le,
            Box::new(SemRvalue::Use(SemOperand::Const(5))),
            Box::new(SemRvalue::Use(SemOperand::Const(3))),
        )),
    );
    let wrong_rhs = int_lit(1);
    let verdict = check_rvalue_adequacy_inner(&rv, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a false Or-value claim must be kernel-rejected, got {verdict:?}"
    );
}

/// The RECOGNIZER: `_a := Le(48, self); _b := Le(self, 57); _0 :=
/// BitOr(_a, _b)` — matching `is_ascii_alphanumeric`'s OWN innermost
/// `is_ascii_digit`-range shape. `sem_rvalue_of_mir` must resolve the
/// `BitOr` rvalue to `SemRvalue::Or`, INLINING both sides via the SAME
/// `resolve_cmp_side` machinery `Cmp` uses (never left as raw
/// cross-references to `_a`/`_b`).
#[test]
fn sem_rvalue_of_mir_recognizes_bitor_on_bool() {
    use trust_types::{
        BinOp, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement, Ty, VerifiableBody,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
        ],
        blocks: vec![trust_types::BasicBlock {
            id: trust_types::BlockId(0),
            stmts: vec![
                Statement::Assign {
                    place: Place::local(2),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Le,
                        Operand::Constant(ConstValue::Uint(48, 8)),
                        Operand::Copy(Place::local(1)),
                    ),
                    span: Default::default(),
                },
                Statement::Assign {
                    place: Place::local(3),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Le,
                        Operand::Copy(Place::local(1)),
                        Operand::Constant(ConstValue::Uint(57, 8)),
                    ),
                    span: Default::default(),
                },
                Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::BitOr,
                        Operand::Move(Place::local(2)),
                        Operand::Move(Place::local(3)),
                    ),
                    span: Default::default(),
                },
            ],
            terminator: trust_types::Terminator::Return,
        }],
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let Statement::Assign { rvalue, .. } = &body.blocks[0].stmts[2] else { unreachable!() };
    let resolved = sem_rvalue_of_mir(&body, rvalue, &param_index)
        .expect("the BitOr-on-Bool shape must resolve");
    assert_eq!(
        resolved,
        SemRvalue::Or(
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Le,
                Box::new(SemRvalue::Use(SemOperand::Const(48))),
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
            )),
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Le,
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
                Box::new(SemRvalue::Use(SemOperand::Const(57))),
            )),
        ),
        "both BitOr operands must INLINE via resolve_cmp_side, not stay raw cross-references"
    );
}

/// Trust: BITWISE SHAPE LANE (2026-07-08) — UPDATED from the former
/// `sem_rvalue_of_mir_declines_bitand_on_non_bool` adversarial probe: the
/// SAME `BinOp::BitAnd` opcode ALSO means genuine INTEGER bitwise-and
/// (`x & 0xFF`) — MIR does not distinguish by opcode name, only by operand
/// TYPE. Before this increment, a non-`Bool`-typed `BitAnd` declined
/// entirely (fail-closed, no genuine-Int fragment existed); NOW it resolves
/// through the genuine-`Int` `SemRvalue::Bin(BitAnd, ..)` shape (the
/// bool-connective check still runs FIRST and still declines for a
/// non-Bool operand — see `sem_rvalue_of_mir_declines_bool_connective_bitand_on_non_bool`
/// below for that STILL-fail-closed boundary), never misdenoting an
/// integer bitwise op as a Bool connective (the two shapes ground to
/// PROVABLY different terms — pure arithmetic vs. the opaque `Int.land`).
#[test]
fn sem_rvalue_of_mir_resolves_bitand_on_non_bool_as_genuine_int() {
    use trust_types::{
        BinOp, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement, Ty, VerifiableBody,
    };
    let u32t = || Ty::Int { width: 32, signed: false };
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: u32t(), name: None },
            LocalDecl { index: 1, ty: u32t(), name: Some("x".into()) },
        ],
        blocks: vec![trust_types::BasicBlock {
            id: trust_types::BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(0),
                rvalue: Rvalue::BinaryOp(
                    BinOp::BitAnd,
                    Operand::Copy(Place::local(1)),
                    Operand::Constant(ConstValue::Uint(0xFF, 32)),
                ),
                span: Default::default(),
            }],
            terminator: trust_types::Terminator::Return,
        }],
        arg_count: 1,
        return_ty: u32t(),
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let Statement::Assign { rvalue, .. } = &body.blocks[0].stmts[0] else { unreachable!() };
    assert_eq!(
        sem_rvalue_of_mir(&body, rvalue, &param_index),
        Some(SemRvalue::Bin(SemBinOp::BitAnd, SemOperand::Var(0), SemOperand::Const(0xFF))),
        "a genuine-Int BitAnd (non-Bool operands) must now resolve via the BITWISE SHAPE LANE"
    );
}

/// FAIL-CLOSED (module doc's core discipline, unchanged by the BITWISE SHAPE
/// LANE): the BOOL-CONNECTIVE `Or`/`And` path still declines when EITHER
/// operand is not GENUINELY `Ty::Bool`-typed — it does NOT silently fall
/// through to treating a Bool-typed local as an Int (this probes the
/// OPPOSITE direction from the test above: a `Ty::Bool` target local whose
/// `BitOr` SOURCE operands are Int-typed temp reads, an ADVERSARIAL shape
/// that should decline both ways — neither the Bool-connective NOR the
/// genuine-Int arithmetic path admits it, since `sem_operand_of_mir` on a
/// non-parameter, non-constant operand returns `None` for the arithmetic
/// fallback too).
#[test]
fn sem_rvalue_of_mir_declines_bool_connective_bitand_on_non_bool() {
    use trust_types::{
        BinOp, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement, Ty, VerifiableBody,
    };
    let u32t = || Ty::Int { width: 32, signed: false };
    // `_0 : Bool := BitAnd(_1, 0xFF)` where `_1 : u32` — the TARGET is Bool
    // (so a naive "target type" check might be tempted to treat this as a
    // connective), but the OPERANDS are genuinely `Ty::Int`, so
    // `mir_operand_is_bool_typed` correctly declines the connective path;
    // `sem_binop_of_mir`'s genuine-Int path DOES still resolve it (a `Bool`
    // TARGET local receiving an `Int` bitwise VALUE is a type mismatch the
    // recognizer is not responsible for rejecting — that is a MIR
    // well-formedness invariant upstream, outside this fragment's scope).
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u32t(), name: Some("x".into()) },
        ],
        blocks: vec![trust_types::BasicBlock {
            id: trust_types::BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(0),
                rvalue: Rvalue::BinaryOp(
                    BinOp::BitAnd,
                    Operand::Copy(Place::local(1)),
                    Operand::Constant(ConstValue::Uint(0xFF, 32)),
                ),
                span: Default::default(),
            }],
            terminator: trust_types::Terminator::Return,
        }],
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let Statement::Assign { rvalue, .. } = &body.blocks[0].stmts[0] else { unreachable!() };
    // The genuine-Int arithmetic path still resolves (operand TYPES, not the
    // target local's declared type, gate the Bool-connective/Int split).
    assert_eq!(
        sem_rvalue_of_mir(&body, rvalue, &param_index),
        Some(SemRvalue::Bin(SemBinOp::BitAnd, SemOperand::Var(0), SemOperand::Const(0xFF)))
    );
}

/// POSITIVE (kernel, Lemma 1B): each genuine-`Int` `BitAnd`/`BitOr`/`BitXor`/
/// `Shl` rvalue gets a modulo-3 adequacy certificate — `eval_rvalue`'s NEW
/// `BinOp.rec` minor premises (`Int.land`/`Int.lor`/`Int.xor`/`Int.shiftLeft`)
/// are def-eq BY REFLEXIVITY to `ground_int`'s matching NEW `F::Pred` arms
/// (clean_ground.rs) — the SAME "opaque, both sides name the identical
/// constant" honesty tier `Int.div`/`Int.mod` already establish for `Div`/`Rem`.
#[test]
fn bitwise_shape_lane_rvalue_is_certified_modulo_3() {
    for op in [SemBinOp::BitAnd, SemBinOp::BitOr, SemBinOp::BitXor, SemBinOp::Shl] {
        let rv = SemRvalue::Bin(op, SemOperand::Var(0), SemOperand::Const(0xFF));
        let cert = rvalue_adequacy_witness(&rv)
            .unwrap_or_else(|| panic!("{op:?} rvalue must get a modulo-3 certificate"));
        assert!(cert.is_modulo_3(), "{op:?}'s certificate must be modulo 3");
    }
}

/// FAIL-CLOSED (kernel): claiming a `BitAnd` rvalue's value equals the
/// `Int.lor` of its operands (the WRONG opaque function — swapping AND for
/// OR) is a dishonest claim; the kernel must reject it, never prove it.
/// This is the mission's "wrong claim, kernel rejects" discipline applied
/// to the bitwise lane (mirrors `wrong_cast_identity_claim_fails_closed`'s
/// and `bool_connective_wrong_claimed_value_is_kernel_rejected`'s own
/// negative-control shape).
#[test]
fn wrong_bitwise_op_claim_fails_closed() {
    let rv = SemRvalue::Bin(SemBinOp::BitAnd, SemOperand::Var(0), SemOperand::Var(1));
    let indices = rv.var_indices();
    let n = indices.len();
    let env_e =
        grounding_env_expr(&indices, &|i| Expr::bvar(u32::try_from(n - 1 - i).unwrap_or(0)));
    // The WRONG rvalue: `Int.lor x y` instead of the claimed `Int.land x y`.
    let wrong_op_rv = SemRvalue::Bin(SemBinOp::BitOr, SemOperand::Var(0), SemOperand::Var(1));
    let wrong_rhs = Expr::apps(cst(MIRSEM_EVAL_RVALUE), [env_e, wrong_op_rv.to_rvalue_expr()]);
    let verdict = check_rvalue_adequacy_inner(&rv, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "claiming BitAnd == Int.lor (wrong bitwise op) MUST be kernel-rejected, got {verdict:?}"
    );
}

/// Trust: M6 rung 6, UNSIGNED-Shr arm — the ADMISSION split, both
/// directions probed on the SAME rvalue shape differing ONLY by declared
/// signedness:
///   * POSITIVE: `_0 := Shr(_1: u64, 44u32)` (unsigned value, `Uint`
///     literal amount — the `ExprMeta::loose_bvar_range` leaf shape)
///     resolves to `Bin(Shr, Var 0, Const 44)`;
///   * ADVERSARIAL (fail-closed, the former "Shr must DEFER" pin's
///     honest successor): the IDENTICAL rvalue with `_1: i64` (SIGNED —
///     an ARITHMETIC right shift, whose floor-on-negatives semantics the
///     `Int.shiftRight` logical denotation does NOT model) must DECLINE;
///   * ADVERSARIAL: a SIGNED literal amount (`Int` const) also declines —
///     only a provably-nonnegative amount is admitted.
#[test]
fn signed_shr_rvalue_declines_unsigned_shr_admits() {
    use trust_types::{
        BinOp, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement, Ty, VerifiableBody,
    };
    let mk_body = |value_ty: Ty| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: value_ty.clone(), name: None },
            LocalDecl { index: 1, ty: value_ty, name: Some("x".into()) },
        ],
        blocks: vec![trust_types::BasicBlock {
            id: trust_types::BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(0),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Shr,
                    Operand::Copy(Place::local(1)),
                    Operand::Constant(ConstValue::Uint(44, 32)),
                ),
                span: Default::default(),
            }],
            terminator: trust_types::Terminator::Return,
        }],
        arg_count: 1,
        return_ty: Ty::Int { width: 64, signed: false },
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    // POSITIVE: unsigned value + Uint amount admits.
    let unsigned = mk_body(Ty::Int { width: 64, signed: false });
    let Statement::Assign { rvalue, .. } = &unsigned.blocks[0].stmts[0] else { unreachable!() };
    assert_eq!(
        sem_rvalue_of_mir(&unsigned, rvalue, &param_index),
        Some(SemRvalue::Bin(SemBinOp::Shr, SemOperand::Var(0), SemOperand::Const(44))),
        "an UNSIGNED `x >> 44` must resolve via the unsigned-Shr arm"
    );
    // ADVERSARIAL: the byte-identical rvalue over a SIGNED local declines.
    let signed = mk_body(Ty::Int { width: 64, signed: true });
    let Statement::Assign { rvalue, .. } = &signed.blocks[0].stmts[0] else { unreachable!() };
    assert_eq!(
        sem_rvalue_of_mir(&signed, rvalue, &param_index),
        None,
        "a SIGNED `x >> 44` (arithmetic shift) must DECLINE fail-closed"
    );
    // ADVERSARIAL: a SIGNED literal amount declines too.
    let mut int_amount = mk_body(Ty::Int { width: 64, signed: false });
    if let Statement::Assign { rvalue, .. } = &mut int_amount.blocks[0].stmts[0] {
        *rvalue = Rvalue::BinaryOp(
            BinOp::Shr,
            Operand::Copy(Place::local(1)),
            Operand::Constant(ConstValue::Int(44)),
        );
    }
    let Statement::Assign { rvalue, .. } = &int_amount.blocks[0].stmts[0] else {
        unreachable!()
    };
    assert_eq!(
        sem_rvalue_of_mir(&int_amount, rvalue, &param_index),
        None,
        "a signed-literal shift amount must DECLINE (only `Uint` is provably nonnegative)"
    );
}

/// Trust: M6 rung 6, UNSIGNED-Shr arm — the kernel adequacy certificate for
