// =======================================================================
// Trust: GUARDED-LOCAL layer (BOOL-CONNECTIVE composition, 2026-07-08) — a bool
// local whose value is assigned by a small GUARDED sub-CFG (the conjunctive
// 2-switch range pattern `sem_conjunctive_chain` already recognizes as a
// TOP-LEVEL shape), fed as a `BitOr`/`BitAnd` operand — the REAL
// `is_ascii_alphanumeric`/`is_ascii_hexdigit`/`is_ascii_punctuation` shape,
// where each BitOr operand is ITSELF a guarded range check, not a flat `Cmp`.
// =======================================================================

/// Build the 4 blocks of a `target := (lo <= self && self <= hi)` GUARDED
/// conjunctive-range sub-CFG — the exact shape real `is_ascii_alphanumeric`-class
/// MIR emits for one range check (e.g. `is_ascii_digit`'s own `48..=57` guard),
/// wired at block ids `[head, head+1, head+2, head+3]`:
///
/// ```text
/// head:   lo_tmp := Le(lo, self);   switchInt(lo_tmp) { 0 => head+1, _ => head+3 }
/// head+1: target := false;          goto join
/// head+2: target := true;           goto join
/// head+3: hi_tmp := Le(self, hi);   switchInt(hi_tmp) { 0 => head+1, _ => head+2 }
/// ```
fn range_conjunction_blocks(
    head: usize,
    target: usize,
    lo_tmp: usize,
    hi_tmp: usize,
    self_local: usize,
    lo: u128,
    hi: u128,
    join: trust_types::BlockId,
) -> Vec<trust_types::BasicBlock> {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, Operand, Place, Rvalue, Statement, Terminator,
    };
    let b = |n: usize| BlockId(head + n);
    vec![
        BasicBlock {
            id: b(0),
            stmts: vec![Statement::Assign {
                place: Place::local(lo_tmp),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Le,
                    Operand::Constant(ConstValue::Uint(lo, 8)),
                    Operand::Copy(Place::local(self_local)),
                ),
                span: Default::default(),
            }],
            terminator: Terminator::SwitchInt {
                discr: Operand::Move(Place::local(lo_tmp)),
                targets: vec![(0, b(1))],
                otherwise: b(3),
                exhaustive_enum_unreachable: false,
                span: Default::default(),
            },
        },
        BasicBlock {
            id: b(1),
            stmts: vec![Statement::Assign {
                place: Place::local(target),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(false))),
                span: Default::default(),
            }],
            terminator: Terminator::Goto(join),
        },
        BasicBlock {
            id: b(2),
            stmts: vec![Statement::Assign {
                place: Place::local(target),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                span: Default::default(),
            }],
            terminator: Terminator::Goto(join),
        },
        BasicBlock {
            id: b(3),
            stmts: vec![Statement::Assign {
                place: Place::local(hi_tmp),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Le,
                    Operand::Copy(Place::local(self_local)),
                    Operand::Constant(ConstValue::Uint(hi, 8)),
                ),
                span: Default::default(),
            }],
            terminator: Terminator::SwitchInt {
                discr: Operand::Move(Place::local(hi_tmp)),
                targets: vec![(0, b(1))],
                otherwise: b(2),
                exhaustive_enum_unreachable: false,
                span: Default::default(),
            },
        },
    ]
}

/// The RECOGNIZER positive: `sem_guarded_local_value` recovers the `And`-tree
/// `48 <= self && self <= 57` a range-conjunction sub-CFG denotes for its target
/// local — the SAME `SemCondTree` [`sem_conjunctive_chain`] itself would build for
/// the byte-identical top-level guard shape (composition, not new theory).
#[test]
fn sem_guarded_local_value_recognizes_range_conjunction() {
    use trust_types::{LocalDecl, Ty, VerifiableBody};
    let u8t = || Ty::Int { width: 8, signed: false };
    let join = trust_types::BlockId(4);
    let mut blocks = range_conjunction_blocks(0, 3, 4, 5, 1, 48, 57, join);
    blocks.push(trust_types::BasicBlock {
        id: join,
        stmts: vec![],
        terminator: trust_types::Terminator::Return,
    });
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
            LocalDecl { index: 5, ty: Ty::Bool, name: None },
        ],
        blocks,
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let cond = sem_guarded_local_value(&body, 3, &param_index, None)
        .expect("the range-conjunction sub-CFG must be recognized");
    assert_eq!(
        cond,
        SemCondTree::And(
            Box::new(SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Le,
                a: SemOperand::Const(48),
                b: SemOperand::Var(0),
            })),
            Box::new(SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Le,
                a: SemOperand::Var(0),
                b: SemOperand::Const(57),
            })),
        ),
        "the guarded local must denote the SAME And-tree the top-level conjunctive \
         recognizer builds for the byte-identical guard"
    );
}

/// ADVERSARIAL PROBES — each fail-closed, none silently absorbed:
///   (a) the target local written a THIRD time (beyond the two arms) — the
///       uniqueness gate.
///   (b) an invisible `Terminator::Call` dest write to the target — the SAME
///       call-dest blind spot `local_soundly_resolvable`'s class-2 check closes.
///   (c) an oversized sub-CFG (a 5-switch chain, past `GUARDED_LOCAL_MAX_SWITCHES`)
///       — the bounded sub-CFG size gate.
///   (d) a non-`Bool`-typed target local — never denote an Int local as a Cond.
#[test]
fn sem_guarded_local_value_declines_adversarial_probes() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Statement, Terminator, Ty, VerifiableBody,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let base_locals = || {
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
            LocalDecl { index: 5, ty: Ty::Bool, name: None },
        ]
    };

    // (a) a THIRD write to the target local (in the join block itself).
    {
        let join = BlockId(4);
        let mut blocks = range_conjunction_blocks(0, 3, 4, 5, 1, 48, 57, join);
        blocks.push(BasicBlock {
            id: join,
            stmts: vec![Statement::Assign {
                place: trust_types::Place::local(3),
                rvalue: trust_types::Rvalue::Use(trust_types::Operand::Constant(
                    trust_types::ConstValue::Bool(false),
                )),
                span: Default::default(),
            }],
            terminator: Terminator::Return,
        });
        let body =
            VerifiableBody { locals: base_locals(), blocks, arg_count: 1, return_ty: Ty::Bool };
        assert_eq!(
            sem_guarded_local_value(&body, 3, &param_index, None),
            None,
            "a target local written a THIRD time (beyond the two arms) must decline"
        );
    }

    // (b) an invisible call-dest write to the target local.
    {
        let join = BlockId(4);
        let mut blocks = range_conjunction_blocks(0, 3, 4, 5, 1, 48, 57, join);
        blocks.push(BasicBlock { id: join, stmts: vec![], terminator: Terminator::Return });
        blocks.push(BasicBlock {
            id: BlockId(5),
            stmts: vec![],
            terminator: Terminator::Call {
                unwind: UnwindEdge::Unreachable,
                func: "unrelated".to_string(),
                args: vec![],
                dest: trust_types::Place::local(3),
                target: Some(join),
                span: Default::default(),
                atomic: None,
                is_foreign: false,
                is_unsafe_sig: false,
            },
        });
        let body =
            VerifiableBody { locals: base_locals(), blocks, arg_count: 1, return_ty: Ty::Bool };
        assert_eq!(
            sem_guarded_local_value(&body, 3, &param_index, None),
            None,
            "an invisible call-dest write to the target local must decline"
        );
    }

    // (c) an oversized sub-CFG: 5 chained range switches feeding ONE target,
    //     past `GUARDED_LOCAL_MAX_SWITCHES` (4).
    {
        use trust_types::{BinOp, ConstValue, Operand, Place, Rvalue};
        let join = BlockId(20);
        let else_arm = BlockId(21);
        let then_arm = BlockId(22);
        let n_switches = 5;
        let mut blocks: Vec<BasicBlock> = Vec::new();
        let mut locals = vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None }, // target
        ];
        for i in 0..n_switches {
            let tmp_local = 3 + i;
            locals.push(LocalDecl { index: tmp_local, ty: Ty::Bool, name: None });
            let this_id = BlockId(i);
            let next = if i + 1 == n_switches { then_arm } else { BlockId(i + 1) };
            blocks.push(BasicBlock {
                id: this_id,
                stmts: vec![Statement::Assign {
                    place: Place::local(tmp_local),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Lt,
                        Operand::Copy(Place::local(1)),
                        Operand::Constant(ConstValue::Uint(200, 8)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Move(Place::local(tmp_local)),
                    targets: vec![(0, else_arm)],
                    otherwise: next,
                    exhaustive_enum_unreachable: false,
                    span: Default::default(),
                },
            });
        }
        blocks.push(BasicBlock {
            id: else_arm,
            stmts: vec![Statement::Assign {
                place: Place::local(2),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(false))),
                span: Default::default(),
            }],
            terminator: Terminator::Goto(join),
        });
        blocks.push(BasicBlock {
            id: then_arm,
            stmts: vec![Statement::Assign {
                place: Place::local(2),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                span: Default::default(),
            }],
            terminator: Terminator::Goto(join),
        });
        blocks.push(BasicBlock { id: join, stmts: vec![], terminator: Terminator::Return });
        let body = VerifiableBody { locals, blocks, arg_count: 1, return_ty: Ty::Bool };
        assert_eq!(
            sem_guarded_local_value(&body, 2, &param_index, None),
            None,
            "a {n_switches}-switch chain (past GUARDED_LOCAL_MAX_SWITCHES) must decline"
        );
    }

    // (d) a non-Bool target local.
    {
        let join = BlockId(4);
        let mut blocks = range_conjunction_blocks(0, 3, 4, 5, 1, 48, 57, join);
        blocks.push(BasicBlock { id: join, stmts: vec![], terminator: Terminator::Return });
        let mut locals = base_locals();
        locals[3] = LocalDecl { index: 3, ty: u8t(), name: None }; // target is now Int-typed.
        let body = VerifiableBody { locals, blocks, arg_count: 1, return_ty: Ty::Bool };
        assert_eq!(
            sem_guarded_local_value(&body, 3, &param_index, None),
            None,
            "a non-Bool target local must never be denoted as a Cond value"
        );
    }
}

// =======================================================================
// Trust: COMPACT-CONJUNCTIVE DIAMOND (2026-07-18, Wave-D items 10 & 9) — the
// SINGLE-SWITCH range diamond modern rustc emits when only the FIRST comparison
// becomes a `SwitchInt` and the second is a plain rvalue in the then block:
//   * `to_ascii_lowercase`'s `_6 := if 65<=self { self<=90 } else { false }`
//     (BARE comparison then-arm), and
//   * `is_ascii_punctuation`'s `_4 := if 33<=self { (self<=47) != false } else
//     { false }` (the `Ne(<cmp>, false)` bool-normalize then-arm).
// Both denote `guard && D` — the SAME `And`-tree the LITERAL-arm two-switch
// conjunctive form produces.
// =======================================================================

/// Build the 3 blocks of a COMPACT `target := (lo <= self && self <= hi)` guarded
/// diamond, wired at `[head, head+1, head+2]`:
/// ```text
/// head:   lo_tmp := Le(lo, self);   switchInt(lo_tmp) { 0 => head+1, _ => head+2 }
/// head+1: target := false;          goto join
/// head+2: <then>                    goto join
/// ```
/// where `<then>` is the BARE comparison `target := Le(self, hi)` (`normalize=false`,
/// the `to_ascii_lowercase` diamond) or its bool-normalize `hi_tmp := Le(self, hi);
/// target := Ne(hi_tmp, false)` (`normalize=true`, the `is_ascii_punctuation` diamond).
fn compact_conjunction_blocks(
    head: usize,
    target: usize,
    lo_tmp: usize,
    hi_tmp: usize,
    self_local: usize,
    lo: u128,
    hi: u128,
    join: trust_types::BlockId,
    normalize: bool,
) -> Vec<trust_types::BasicBlock> {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, Operand, Place, Rvalue, Statement, Terminator,
    };
    let b = |n: usize| BlockId(head + n);
    let then_stmts = if normalize {
        vec![
            Statement::Assign {
                place: Place::local(hi_tmp),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Le,
                    Operand::Copy(Place::local(self_local)),
                    Operand::Constant(ConstValue::Uint(hi, 8)),
                ),
                span: Default::default(),
            },
            Statement::Assign {
                place: Place::local(target),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Ne,
                    Operand::Move(Place::local(hi_tmp)),
                    Operand::Constant(ConstValue::Bool(false)),
                ),
                span: Default::default(),
            },
        ]
    } else {
        vec![Statement::Assign {
            place: Place::local(target),
            rvalue: Rvalue::BinaryOp(
                BinOp::Le,
                Operand::Copy(Place::local(self_local)),
                Operand::Constant(ConstValue::Uint(hi, 8)),
            ),
            span: Default::default(),
        }]
    };
    vec![
        BasicBlock {
            id: b(0),
            stmts: vec![Statement::Assign {
                place: Place::local(lo_tmp),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Le,
                    Operand::Constant(ConstValue::Uint(lo, 8)),
                    Operand::Copy(Place::local(self_local)),
                ),
                span: Default::default(),
            }],
            terminator: Terminator::SwitchInt {
                discr: Operand::Move(Place::local(lo_tmp)),
                targets: vec![(0, b(1))],
                otherwise: b(2),
                exhaustive_enum_unreachable: false,
                span: Default::default(),
            },
        },
        BasicBlock {
            id: b(1),
            stmts: vec![Statement::Assign {
                place: Place::local(target),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(false))),
                span: Default::default(),
            }],
            terminator: Terminator::Goto(join),
        },
        BasicBlock { id: b(2), stmts: then_stmts, terminator: Terminator::Goto(join) },
    ]
}

/// The two-leaf And-tree `lo <= self && self <= hi` (`Var 0` == `self`).
fn range_and_tree(lo: i128, hi: i128) -> SemCondTree {
    SemCondTree::And(
        Box::new(SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Le,
            a: SemOperand::Const(lo),
            b: SemOperand::Var(0),
        })),
        Box::new(SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Le,
            a: SemOperand::Var(0),
            b: SemOperand::Const(hi),
        })),
    )
}

/// `range_and_tree` as a `SemRvalue` (`cond_tree_to_rvalue` of the And-tree).
fn range_and_tree_rv(lo: i128, hi: i128) -> SemRvalue {
    SemRvalue::And(
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Le,
            Box::new(SemRvalue::Use(SemOperand::Const(lo))),
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
        )),
        Box::new(SemRvalue::Cmp(
            SemCmpOp::Le,
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
            Box::new(SemRvalue::Use(SemOperand::Const(hi))),
        )),
    )
}

fn compact_diamond_body(lo: u128, hi: u128, normalize: bool) -> trust_types::VerifiableBody {
    use trust_types::{BasicBlock, BlockId, LocalDecl, Terminator, Ty, VerifiableBody};
    let u8t = || Ty::Int { width: 8, signed: false };
    let join = BlockId(3);
    let mut blocks = compact_conjunction_blocks(0, 2, 3, 4, 1, lo, hi, join, normalize);
    blocks.push(BasicBlock { id: join, stmts: vec![], terminator: Terminator::Return });
    VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None }, // target
            LocalDecl { index: 3, ty: Ty::Bool, name: None }, // lo_tmp
            LocalDecl { index: 4, ty: Ty::Bool, name: None }, // hi_tmp
        ],
        blocks,
        arg_count: 1,
        return_ty: Ty::Bool,
    }
}

/// Item 9's diamond: a BARE-comparison then arm (`to_ascii_lowercase`'s `_6`).
#[test]
fn sem_guarded_local_value_recognizes_compact_diamond_bare_then() {
    let body = compact_diamond_body(65, 90, false);
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    assert_eq!(
        sem_guarded_local_value(&body, 2, &param_index, None),
        Some(range_and_tree(65, 90)),
        "the compact single-switch diamond with a BARE `self <= hi` then arm must \
         denote `65 <= self && self <= 90`"
    );
}

/// Item 10's diamond: a `Ne(<cmp>, false)` bool-normalize then arm
/// (`is_ascii_punctuation`'s `_4`).
#[test]
fn sem_guarded_local_value_recognizes_compact_diamond_normalized_then() {
    let body = compact_diamond_body(33, 47, true);
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    assert_eq!(
        sem_guarded_local_value(&body, 2, &param_index, None),
        Some(range_and_tree(33, 47)),
        "the compact single-switch diamond with a `(self <= hi) != false` then arm \
         must denote `33 <= self && self <= 47` (bool-normalize collapsed)"
    );
}

/// Item 9 VALUE MODEL: the branchless case-mask `self | ((range as u8) * 32)`
/// models value-faithfully as `BitBin(BitOr, self, ArithBin(Mul, range, 32))`,
/// where `range` is the `{0,1}`-embed `And(Cmp, Cmp)` of the guard. VALUE-FAITHFUL
/// tier: every leaf grounds to the exact `Int.lor`/`Int.mul`/`bool_as_int` term.
/// (The whole-function STRICT gate now MINTS for `to_ascii_lowercase`: the
/// orthogonal unsigned-u8 `Mul`-overflow VC KIND is modeled by
/// `umul_overflow_vc_modeled` and the formula-aware bridge certifies its
/// `Gt(Mul(a,b),MAX)` core def-eq to `umul_overflows_u8` modulo 3 — see the census-m5
/// `u8_ascii_to_ascii_lowercase_uppercase_recognized_via_call_chain_pureop` pin.)
#[test]
fn sem_rvalue_of_mir_models_branchless_case_mask_value_faithfully() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    let join = BlockId(3);
    let mut blocks = compact_conjunction_blocks(0, 2, 3, 4, 1, 65, 90, join, false);
    blocks.push(BasicBlock {
        id: join,
        stmts: vec![
            // _5 := _2 as u8   (the bool→int embed)
            Statement::Assign {
                place: Place::local(5),
                rvalue: Rvalue::Cast(Operand::Move(Place::local(2)), u8t()),
                span: Default::default(),
            },
            // _6 := _5 * 32
            Statement::Assign {
                place: Place::local(6),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Mul,
                    Operand::Move(Place::local(5)),
                    Operand::Constant(ConstValue::Uint(32, 8)),
                ),
                span: Default::default(),
            },
            // _0 := self | _6
            Statement::Assign {
                place: Place::local(0),
                rvalue: Rvalue::BinaryOp(
                    BinOp::BitOr,
                    Operand::Copy(Place::local(1)),
                    Operand::Move(Place::local(6)),
                ),
                span: Default::default(),
            },
        ],
        terminator: Terminator::Return,
    });
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: u8t(), name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
            LocalDecl { index: 5, ty: u8t(), name: None },
            LocalDecl { index: 6, ty: u8t(), name: None },
        ],
        blocks,
        arg_count: 1,
        return_ty: u8t(),
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let Statement::Assign { rvalue, .. } = &body.blocks[3].stmts[2] else { unreachable!() };
    assert_eq!(
        sem_rvalue_of_mir(&body, rvalue, &param_index),
        Some(SemRvalue::BitBin(
            SemBinOp::BitOr,
            Box::new(SemRvalue::Use(SemOperand::Var(0))),
            Box::new(SemRvalue::ArithBin(
                SemBinOp::Mul,
                Box::new(range_and_tree_rv(65, 90)),
                Box::new(SemRvalue::Use(SemOperand::Const(32))),
            )),
        )),
        "the branchless case-mask `self | ((65<=self && self<=90) as u8 * 32)` must \
         model value-faithfully: BitOr over self and the {{0,1}}-embed range times 32"
    );
}

/// FORGERY PROBES — each fail-closed / value-faithful, none silently absorbed.
#[test]
fn wave_d_compact_diamond_and_case_mask_forgery_probes() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };

    // (a) MASK MULTIPLIER FAITHFULNESS — the model reflects the ACTUAL MIR
    //     multiplier constant, never a hardcoded 32. A dump multiplying by 64
    //     models `ArithBin(Mul, range, 64)`; a forged `*32` claim would kernel-
    //     mismatch.
    {
        let join = BlockId(3);
        let mut blocks = compact_conjunction_blocks(0, 2, 3, 4, 1, 65, 90, join, false);
        blocks.push(BasicBlock {
            id: join,
            stmts: vec![
                Statement::Assign {
                    place: Place::local(5),
                    rvalue: Rvalue::Cast(Operand::Move(Place::local(2)), u8t()),
                    span: Default::default(),
                },
                Statement::Assign {
                    place: Place::local(6),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Mul,
                        Operand::Move(Place::local(5)),
                        Operand::Constant(ConstValue::Uint(64, 8)), // 64, not 32
                    ),
                    span: Default::default(),
                },
                Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::BitOr,
                        Operand::Copy(Place::local(1)),
                        Operand::Move(Place::local(6)),
                    ),
                    span: Default::default(),
                },
            ],
            terminator: Terminator::Return,
        });
        let body = VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u8t(), name: None },
                LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::Bool, name: None },
                LocalDecl { index: 3, ty: Ty::Bool, name: None },
                LocalDecl { index: 4, ty: Ty::Bool, name: None },
                LocalDecl { index: 5, ty: u8t(), name: None },
                LocalDecl { index: 6, ty: u8t(), name: None },
            ],
            blocks,
            arg_count: 1,
            return_ty: u8t(),
        };
        let Statement::Assign { rvalue, .. } = &body.blocks[3].stmts[2] else { unreachable!() };
        let modeled = sem_rvalue_of_mir(&body, rvalue, &param_index).expect("models");
        let SemRvalue::BitBin(SemBinOp::BitOr, _, mul) = modeled else {
            panic!("must be BitOr(self, mul)")
        };
        assert_eq!(
            *mul,
            SemRvalue::ArithBin(
                SemBinOp::Mul,
                Box::new(range_and_tree_rv(65, 90)),
                Box::new(SemRvalue::Use(SemOperand::Const(64))),
            ),
            "the model must carry the ACTUAL multiplier 64, never a hardcoded 32"
        );
    }

    // (b) BitAnd SWAPPED FOR BitOr in the merge — the recognizer models the
    //     ACTUAL opcode: `BitAnd` on two Bool diamonds is `And`, NEVER `Or`, so a
    //     `punctuation`-as-disjunction forgery cannot arise from a BitAnd merge.
    {
        // Diamond A: target _2, temps _4/_5. Diamond B: target _3, temps _6/_7
        // (DISTINCT temps — no cross-diamond local collision).
        let join_a = BlockId(3);
        let join_b = BlockId(7);
        let mut blocks = compact_conjunction_blocks(0, 2, 4, 5, 1, 33, 47, join_a, true);
        blocks.push(BasicBlock {
            id: join_a,
            stmts: vec![],
            terminator: Terminator::Goto(BlockId(4)),
        });
        blocks.extend(compact_conjunction_blocks(4, 3, 6, 7, 1, 58, 64, join_b, true));
        blocks.push(BasicBlock {
            id: join_b,
            stmts: vec![Statement::Assign {
                place: Place::local(0),
                rvalue: Rvalue::BinaryOp(
                    BinOp::BitAnd, // AND, not OR
                    Operand::Move(Place::local(2)),
                    Operand::Move(Place::local(3)),
                ),
                span: Default::default(),
            }],
            terminator: Terminator::Return,
        });
        let body = VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::Bool, name: None },
                LocalDecl { index: 3, ty: Ty::Bool, name: None },
                LocalDecl { index: 4, ty: Ty::Bool, name: None },
                LocalDecl { index: 5, ty: Ty::Bool, name: None },
                LocalDecl { index: 6, ty: Ty::Bool, name: None },
                LocalDecl { index: 7, ty: Ty::Bool, name: None },
            ],
            blocks,
            arg_count: 1,
            return_ty: Ty::Bool,
        };
        let Statement::Assign { rvalue, .. } = &body.blocks[7].stmts[0] else { unreachable!() };
        let modeled = sem_rvalue_of_mir(&body, rvalue, &param_index).expect("models");
        assert!(
            matches!(modeled, SemRvalue::And(..)),
            "a BitAnd merge of two range diamonds must model as `And`, never `Or`"
        );
    }

    // (c) NON-RANGE guard in the then arm — the compact diamond's then value is a
    //     `Ne(_t, false)` where `_t` is an ARITHMETIC temp (`_t := self + 1`), not a
    //     comparison. `sem_rvalue_to_cond_tree` declines the arithmetic inner value,
    //     so the whole diamond declines fail-closed (never denotes an int as a Cond).
    {
        let join = BlockId(3);
        let mut blocks = compact_conjunction_blocks(0, 2, 3, 4, 1, 65, 90, join, false);
        blocks[2] = BasicBlock {
            id: BlockId(2),
            stmts: vec![
                Statement::Assign {
                    place: Place::local(4),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Add,
                        Operand::Copy(Place::local(1)),
                        Operand::Constant(ConstValue::Uint(1, 8)),
                    ),
                    span: Default::default(),
                },
                Statement::Assign {
                    place: Place::local(2),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Ne,
                        Operand::Move(Place::local(4)),
                        Operand::Constant(ConstValue::Bool(false)),
                    ),
                    span: Default::default(),
                },
            ],
            terminator: Terminator::Goto(join),
        };
        blocks.push(BasicBlock { id: join, stmts: vec![], terminator: Terminator::Return });
        let body = VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::Bool, name: None },
                LocalDecl { index: 3, ty: Ty::Bool, name: None },
                LocalDecl { index: 4, ty: u8t(), name: None }, // now an INT temp
            ],
            blocks,
            arg_count: 1,
            return_ty: Ty::Bool,
        };
        assert_eq!(
            sem_guarded_local_value(&body, 2, &param_index, None),
            None,
            "a then arm carrying `Ne(<arithmetic>, false)` (a non-comparison) must decline"
        );
    }

    // (d) REASSIGNED GUARD TEMP — the switch discriminant `lo_tmp` is written a
    //     SECOND time (a decoy). `switch_leaf`'s single-assignment gate declines it,
    //     so the diamond declines fail-closed.
    {
        let join = BlockId(3);
        let mut blocks = compact_conjunction_blocks(0, 2, 3, 4, 1, 65, 90, join, false);
        blocks[1].stmts.insert(
            0,
            Statement::Assign {
                place: Place::local(3),
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                span: Default::default(),
            },
        );
        blocks.push(BasicBlock { id: join, stmts: vec![], terminator: Terminator::Return });
        let body = VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::Bool, name: None },
                LocalDecl { index: 3, ty: Ty::Bool, name: None },
                LocalDecl { index: 4, ty: Ty::Bool, name: None },
            ],
            blocks,
            arg_count: 1,
            return_ty: Ty::Bool,
        };
        assert_eq!(
            sem_guarded_local_value(&body, 2, &param_index, None),
            None,
            "a multiply-assigned (reassigned) guard discriminant temp must decline"
        );
    }
}

/// The COMPOSITION: `_a := <guarded 48..=57 range>; _b := <guarded 65..=90
/// range>; _0 := BitOr(_a, _b)` — the mission's headline shape. `sem_rvalue_of_mir`
/// must resolve the `BitOr` to a FULLY INLINED `Or(And(Cmp,Cmp), And(Cmp,Cmp))`,
/// never left dangling on the guarded-local cross-references `_a`/`_b`.
#[test]
fn sem_rvalue_of_mir_recognizes_bitor_on_guarded_locals() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
        Ty, VerifiableBody,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    // Two non-overlapping range-conjunction groups: the first at block ids
    // [0..4) with its join relay at 4 (a plain `Goto` into the second group at
    // [5..9)), the second group's join at 9 (where the `BitOr` combines both
    // guarded locals into `_0` and returns).
    // Contiguous local numbering (no gaps: `body.locals` is indexed BY POSITION,
    // so `.get(local)` requires `locals[i].index == i`): `_0` (result), `_1`
    // (self), `_2`/`_3` (the two guarded-local targets), `_4`/`_5` (group A's
    // lo/hi comparison temps), `_6`/`_7` (group B's).
    let join_a = BlockId(4);
    let join_b = BlockId(9);
    let mut blocks = range_conjunction_blocks(0, 2, 4, 5, 1, 48, 57, join_a);
    blocks.push(BasicBlock {
        id: join_a,
        stmts: vec![],
        terminator: Terminator::Goto(BlockId(5)),
    });
    blocks.extend(range_conjunction_blocks(5, 3, 6, 7, 1, 65, 90, join_b));
    blocks.push(BasicBlock {
        id: join_b,
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::BinaryOp(
                BinOp::BitOr,
                Operand::Move(Place::local(2)),
                Operand::Move(Place::local(3)),
            ),
            span: Default::default(),
        }],
        terminator: Terminator::Return,
    });
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
            LocalDecl { index: 5, ty: Ty::Bool, name: None },
            LocalDecl { index: 6, ty: Ty::Bool, name: None },
            LocalDecl { index: 7, ty: Ty::Bool, name: None },
        ],
        blocks,
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let Statement::Assign { rvalue, .. } =
        body.blocks.iter().find(|b| b.id == join_b).unwrap().stmts.last().unwrap()
    else {
        unreachable!()
    };
    let resolved = sem_rvalue_of_mir(&body, rvalue, &param_index)
        .expect("the guarded-local BitOr composition must resolve");
    let expect_group = |lo: i128, hi: i128| {
        SemRvalue::And(
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Le,
                Box::new(SemRvalue::Use(SemOperand::Const(lo))),
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
            )),
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Le,
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
                Box::new(SemRvalue::Use(SemOperand::Const(hi))),
            )),
        )
    };
    assert_eq!(
        resolved,
        SemRvalue::Or(Box::new(expect_group(48, 57)), Box::new(expect_group(65, 90))),
        "both BitOr operands (each a guarded-local range check) must INLINE fully, \
         never stay raw cross-references to `_2`/`_3`"
    );
    let cert = rvalue_adequacy_witness(&resolved)
        .expect("the guarded-local BitOr composition gets a modulo-3 rvalue certificate");
    assert!(cert.is_modulo_3());
}

/// END-TO-END, SYNTHETIC: the same composition as above, but as a WHOLE function
/// return, recognized by `sem_return_of_mir` and fully certified (Lemma 1C) —
/// pinning that the GUARDED-LOCAL layer composes all the way to a real
/// `function_fully_faithful_witness`, not just the rvalue fragment.
#[test]
fn guarded_local_bitor_shape_certifies_end_to_end() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
        Ty, VerifiableBody, VerifiableFunction,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    // Contiguous local numbering (no gaps: `body.locals` is indexed BY POSITION,
    // so `.get(local)` requires `locals[i].index == i`): `_0` (result), `_1`
    // (self), `_2`/`_3` (the two guarded-local targets), `_4`/`_5` (group A's
    // lo/hi comparison temps), `_6`/`_7` (group B's).
    let join_a = BlockId(4);
    let join_b = BlockId(9);
    let mut blocks = range_conjunction_blocks(0, 2, 4, 5, 1, 48, 57, join_a);
    blocks.push(BasicBlock {
        id: join_a,
        stmts: vec![],
        terminator: Terminator::Goto(BlockId(5)),
    });
    blocks.extend(range_conjunction_blocks(5, 3, 6, 7, 1, 65, 90, join_b));
    blocks.push(BasicBlock {
        id: join_b,
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::BinaryOp(
                BinOp::BitOr,
                Operand::Move(Place::local(2)),
                Operand::Move(Place::local(3)),
            ),
            span: Default::default(),
        }],
        terminator: Terminator::Return,
    });
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("self".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
            LocalDecl { index: 5, ty: Ty::Bool, name: None },
            LocalDecl { index: 6, ty: Ty::Bool, name: None },
            LocalDecl { index: 7, ty: Ty::Bool, name: None },
        ],
        blocks,
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    let func = VerifiableFunction {
        name: "is_upper_or_digit".to_string(),
        def_path: "is_upper_or_digit".to_string(),
        span: Default::default(),
        body,
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };

    let cert = function_fully_faithful_witness(&func)
        .expect("the guarded-local BitOr function must be fully faithful");
    assert!(cert.is_modulo_3());
    assert!(
        matches!(cert.contract.ret, ReturnCertificate::StraightLine(_)),
        "a straight-line guarded-local BitOr return must certify via the StraightLine \
         (MirSem fallback) return certificate"
    );
}

