/// Trust: W-CMP-DISCR (2026-07-16) — THE REAL `signum` FIXTURES:
/// `num::<impl {i8,i16,i32,i64}>::signum`
/// (`fixtures/stdlib-leaf-num-2026-07-16/dumps/`), loaded byte-for-byte from
/// the checked-in `-Ztrust-dump=mir:<dir>` dumps. Each is the three-way sign chain
/// `Cmp(self, 0) -> Discriminant(Ordering) -> [Cast to iN]`; the recognizer
/// normalizes it to the sign rvalue `(self > 0) - (self < 0)` and the
/// straight-line return certifies modulo 3 (kernel-checked against the
/// vendored `Ordering` semantics — NOT a shape-only promotion). Both the
/// no-cast `i8` shape (`_0 := Discriminant(..)` directly) and the
/// widening-cast `i16`/`i32`/`i64` shape are exercised.
#[test]
fn real_signum_fixtures_certify_via_three_way_sign() {
    // Trust (2026-07-29): silent-skip guard removed (see NO-VACUOUS-CORPUS-TEST).
    // The trailing `checked == 4` assertion below was the only thing standing
    // between this test and a vacuous pass; the loop now fails at the miss
    // itself, naming the path, which is a diagnosis rather than a count mismatch.
    let dir = required_corpus_dir("fixtures/stdlib-leaf-num-2026-07-16/dumps");
    let mut checked = 0usize;
    for w in ["i8", "i16", "i32", "i64"] {
        let name = format!("num__<impl {w}>__signum.json");
        let func = read_required_fixture(&dir, &name);
        let cert = function_fully_faithful_witness(&func).unwrap_or_else(|| {
            panic!("{name} must be fully faithful via the W-CMP-DISCR three-way-sign lane")
        });
        assert!(cert.is_modulo_3(), "{name}'s certificate must be modulo 3");
        assert!(
            matches!(cert.contract.ret, ReturnCertificate::StraightLine(_)),
            "{name} must certify via the StraightLine (MirSem fallback) return certificate"
        );
        // The recovered return witness must be the SSA-temp sign rvalue
        // `_0 := ArithBin(Sub, Cmp(Gt, self, 0), Cmp(Lt, self, 0))`.
        let param_index = |local: usize| -> Option<u64> {
            if (1..=func.body.arg_count).contains(&local) {
                u64::try_from(local - 1).ok()
            } else {
                None
            }
        };
        let ret = sem_return_of_mir(&func, &param_index)
            .unwrap_or_else(|| panic!("{name} must recover a straight-line sign witness"));
        let sign = SemRvalue::ArithBin(
            SemBinOp::Sub,
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Gt,
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
                Box::new(SemRvalue::Use(SemOperand::Const(0))),
            )),
            Box::new(SemRvalue::Cmp(
                SemCmpOp::Lt,
                Box::new(SemRvalue::Use(SemOperand::Var(0))),
                Box::new(SemRvalue::Use(SemOperand::Const(0))),
            )),
        );
        assert_eq!(ret.ret, SemOperand::Var(0), "{name}: the return traces `_0`");
        assert!(
            ret.stmts.iter().any(|s| s.idx == 0 && s.rvalue == sign),
            "{name}: `_0` must be assigned the three-way sign `(self>0) - (self<0)`"
        );
        checked += 1;
    }
    assert!(checked > 0, "at least one signum fixture must be present");
}

/// Trust: W-CMP-DISCR — FAIL-CLOSED: the adversarial `signum` forgery panel
/// (`fixtures/stdlib-leaf-num-2026-07-16/forgeries/`). Each `G1..G5` mutates
/// the genuine three-way-sign chain so it is NO LONGER the faithful sign, and
/// MUST DECLINE (no `FullFaithfulnessCertificate`), never a false PROVE and
/// never a kernel rejection:
///   * G1 — `Cmp(self, 5)` (non-zero rhs);
///   * G2 — an `Ordering` whose discriminants are NOT the `-1`/`0`/`1` sign
///     encoding;
///   * G3 — a non-`Ordering` enum (right variants/discs, wrong type name);
///   * G4 — a flipped `Cmp(0, self)` (= `-signum`);
///   * G5 — an UNSIGNED cast destination (the `-1` `Less` tag not
///     recoverable).
/// G6 is the positive control (a genuine `i32` signum) that MUST certify.
#[test]
fn signum_forgeries_are_fail_closed() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("fixtures/stdlib-leaf-num-2026-07-16/forgeries");
    let load = |name: &str| -> Option<trust_types::VerifiableFunction> {
        let bytes = std::fs::read(dir.join(name)).ok()?;
        Some(serde_json::from_slice(&bytes).unwrap_or_else(|e| panic!("parse {name}: {e}")))
    };
    for name in [
        "forgery__G1_signum_cmp_rhs_nonzero.json",
        "forgery__G2_signum_wrong_disc_mapping.json",
        "forgery__G3_signum_non_ordering_enum.json",
        "forgery__G4_signum_flipped_operands.json",
        "forgery__G5_signum_unsigned_cast_dest.json",
    ] {
        let Some(func) = load(name) else { continue };
        assert!(
            function_fully_faithful_witness(&func).is_none(),
            "{name} is a signum forgery — it MUST decline, never mint a certificate"
        );
    }
    if let Some(ctrl) = load("forgery__G6_signum_valid_control.json") {
        let cert = function_fully_faithful_witness(&ctrl)
            .expect("G6 is a genuine i32 signum — the positive control MUST certify");
        assert!(cert.is_modulo_3(), "G6's certificate must be modulo 3");
    }
}

// =======================================================================
// Trust: RANGE+DISJUNCTION guard (2026-07-08) — the `is_ascii_control`-class
// control-flow `||`: `Cond.Or` (kernel), `ground_bool`'s `Formula::Or` arm
// (live grounder), and the DECISION-DAG recognizer
// (`sem_decision_dag_chain`) with its raw-value equality leaf.
// =======================================================================

/// The `is_ascii_control`-shaped guarded return as a hand-built witness:
/// `if (0 <= x && x <= 31) || x == 127 { 1 } else { 0 }`.
fn cf_or_return() -> SemCfReturn {
    let leaf =
        |op: SemCmpOp, a: SemOperand, b: SemOperand| SemCondTree::Leaf(SemCond { op, a, b });
    SemCfReturn {
        cond: SemCondTree::Or(
            Box::new(SemCondTree::And(
                Box::new(leaf(SemCmpOp::Le, SemOperand::Const(0), SemOperand::Var(0))),
                Box::new(leaf(SemCmpOp::Le, SemOperand::Var(0), SemOperand::Const(31))),
            )),
            Box::new(leaf(SemCmpOp::Eq, SemOperand::Var(0), SemOperand::Const(127))),
        ),
        then_rv: SemRvalue::Use(SemOperand::Const(1)),
        else_rv: SemRvalue::Use(SemOperand::Const(0)),
    }
}

/// POSITIVE (kernel): a DISJUNCTIVE guard's branch refinement proves modulo 3 —
/// `eval_cond`'s new `Or` arm (`Bool.or` of the IHs) is def-eq to the LIVE
/// grounder's new `Formula::Or` arm (a left-nested `Bool.or`), so
/// `denote_substitutedB` over the `Or` cond ≡ the live-grounded `Ite`.
#[test]
fn or_guard_branch_refinement_proven_modulo_3() {
    assert_eq!(
        check_branch_refinement(&cf_or_return()),
        RefinementVerdict::ProvenModulo3,
        "the disjunctive (Or) guarded return's branch refinement must prove modulo 3"
    );
}

/// FAIL-CLOSED (kernel): claiming the Or-guarded return is the UNCONDITIONAL
/// then-arm (dropping the disjunctive guard) is kernel-rejected, never proven.
#[test]
fn wrong_or_guard_rhs_fails_closed() {
    let r = cf_or_return();
    let indices = r.var_indices();
    let n = indices.len();
    let env_e =
        grounding_env_expr(&indices, &|i| Expr::bvar(u32::try_from(n - 1 - i).unwrap_or(0)));
    let wrong_rhs = Expr::apps(cst(MIRSEM_EVAL_RVALUE), [env_e, r.then_rv.to_rvalue_expr()]);
    let verdict = check_branch_refinement_inner(&r, Some(&wrong_rhs));
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a WRONG Or-guard RHS (unconditional then-arm, guard dropped) MUST be \
         kernel-rejected, got {verdict:?}"
    );
}

/// THE REAL CENSUS FIXTURES: `core::num::<impl u8>::is_ascii_control`
/// (`(*self <= 31 || *self == 127)`, with the compiler-retained vacuous
/// `0 <= *self` conjunct) and `ascii_utils`' `<u8 as Check>::{is_space,
/// is_control}` — loaded byte-for-byte from the checked-in `-Ztrust-dump=mir:<dir>`
/// dumps. Each must be recognized by the decision-DAG recognizer (an `Or`
/// cond) and certify FULLY FAITHFUL.
#[test]
fn real_range_disjunction_fixtures_are_fully_faithful() {
    // Trust (2026-07-29 re-freeze): the two `ascii_utils` rows are re-keyed to
    // the crate-root-qualified `def_path` spelling (`<u8 as Check>::is_space` →
    // `<u8 as lib::Check>::is_space`) and the silent-skip guard is gone. This
    // test was PARTIALLY vacuous — the `census-core-m5` row still ran, so it
    // stayed green while 2 of its 3 rows quietly stopped being checked.
    for (dir_rel, name) in [
        ("fixtures/census-core-m5-2026-07-07/u8-ascii", "num__<impl u8>__is_ascii_control.json"),
        ("fixtures/census-rung2-2026-07-07/ascii_utils", "<u8 as lib__Check>__is_space.json"),
        ("fixtures/census-rung2-2026-07-07/ascii_utils", "<u8 as lib__Check>__is_control.json"),
    ] {
        let rel = format!("{dir_rel}/{name}");
        let func = read_required_fixture(&required_corpus_dir(dir_rel), name);
        // The recognizer recovers an Or cond from the real control-flow `||`.
        let r = sem_cf_return_shape_of(&func).unwrap_or_else(|| {
            panic!("{rel} must be recognized by the decision-DAG recognizer")
        });
        fn has_or(t: &SemCondTree) -> bool {
            match t {
                SemCondTree::Leaf(_) => false,
                SemCondTree::Or(..) => true,
                SemCondTree::And(a, b) => has_or(a) || has_or(b),
                SemCondTree::IterHasNext(_) => false,
            }
        }
        assert!(has_or(&r.cond), "{rel}'s recognized cond must carry the disjunction");
        // And the whole function certifies fully faithful.
        let cert = function_fully_faithful_witness(&func)
            .unwrap_or_else(|| panic!("{rel} must be fully faithful via the Or guard"));
        assert!(cert.is_modulo_3(), "{rel}'s certificate must be modulo 3");
    }
}

/// ADVERSARIAL PROBES for the decision-DAG recognizer, each fail-closed:
///   (a) a CROSS shape needing negation (`if c { if d {A} else {B} } else
///       { if e {B} else {A} }`) declines under BOTH arm assignments;
///   (b) an OVERSIZED DAG (9 raw-value clauses, past `DISJ_DAG_MAX_SWITCHES`)
///       declines at the size gate.
#[test]
fn decision_dag_declines_adversarial_probes() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    let mk_func = |locals: Vec<LocalDecl>, blocks: Vec<BasicBlock>| VerifiableFunction {
        name: "probe".to_string(),
        def_path: "probe".to_string(),
        span: Default::default(),
        body: VerifiableBody { locals, blocks, arg_count: 1, return_ty: Ty::Bool },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    let cmp_assign = |tmp: usize, k: u128| Statement::Assign {
        place: Place::local(tmp),
        rvalue: Rvalue::BinaryOp(
            BinOp::Lt,
            Operand::Copy(Place::local(1)),
            Operand::Constant(ConstValue::Uint(k, 8)),
        ),
        span: Default::default(),
    };
    let bool_arm = |id: usize, v: bool, join: BlockId| BasicBlock {
        id: BlockId(id),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(v))),
            span: Default::default(),
        }],
        terminator: Terminator::Goto(join),
    };
    let switch = |id: usize, tmp: usize, zero_to: usize, otherwise: usize| BasicBlock {
        id: BlockId(id),
        stmts: vec![],
        terminator: Terminator::SwitchInt {
            discr: Operand::Move(Place::local(tmp)),
            targets: vec![(0, BlockId(zero_to))],
            otherwise: BlockId(otherwise),
            exhaustive_enum_unreachable: false,
            span: Default::default(),
        },
    };

    // (a) the CROSS shape: c(bb0): 0→sw_e(bb2), _→sw_d(bb1);
    //     d(bb1): 0→armB(bb4), _→armA(bb3); e(bb2): 0→armA(bb3), _→armB(bb4).
    //     Denoting needs `¬c`-style composition — no rule matches under either
    //     arm assignment.
    {
        let mut blocks = vec![
            BasicBlock {
                id: BlockId(0),
                stmts: vec![cmp_assign(2, 10), cmp_assign(3, 20), cmp_assign(4, 30)],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Move(Place::local(2)),
                    targets: vec![(0, BlockId(2))],
                    otherwise: BlockId(1),
                    exhaustive_enum_unreachable: false,
                    span: Default::default(),
                },
            },
            switch(1, 3, 4, 3),
            switch(2, 4, 3, 4),
        ];
        blocks.push(bool_arm(3, true, BlockId(5)));
        blocks.push(bool_arm(4, false, BlockId(5)));
        blocks.push(BasicBlock {
            id: BlockId(5),
            stmts: vec![],
            terminator: Terminator::Return,
        });
        let locals = vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("x".into()) },
            LocalDecl { index: 2, ty: Ty::Bool, name: None },
            LocalDecl { index: 3, ty: Ty::Bool, name: None },
            LocalDecl { index: 4, ty: Ty::Bool, name: None },
        ];
        let func = mk_func(locals, blocks);
        assert!(
            sem_cf_return_shape_of(&func).is_none(),
            "the negation-needing CROSS shape must decline under both arm assignments"
        );
    }

    // (b) OVERSIZED: 9 chained raw-value equality clauses (x == 0 || x == 1 ||
    //     … || x == 8) — one past `DISJ_DAG_MAX_SWITCHES` (8).
    {
        let n = DISJ_DAG_MAX_SWITCHES + 1;
        let then_arm = n; // block ids: switches 0..n, arms n / n+1, join n+2.
        let else_arm = n + 1;
        let join = n + 2;
        let mut blocks: Vec<BasicBlock> = (0..n)
            .map(|i| BasicBlock {
                id: BlockId(i),
                stmts: vec![],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Copy(Place::local(1)),
                    targets: vec![(u128::try_from(i).unwrap(), BlockId(then_arm))],
                    otherwise: BlockId(if i + 1 == n { else_arm } else { i + 1 }),
                    exhaustive_enum_unreachable: false,
                    span: Default::default(),
                },
            })
            .collect();
        blocks.push(bool_arm(then_arm, true, BlockId(join)));
        blocks.push(bool_arm(else_arm, false, BlockId(join)));
        blocks.push(BasicBlock {
            id: BlockId(join),
            stmts: vec![],
            terminator: Terminator::Return,
        });
        let locals = vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u8t(), name: Some("x".into()) },
        ];
        let func = mk_func(locals, blocks);
        assert!(
            sem_cf_return_shape_of(&func).is_none(),
            "a {n}-switch DAG (past DISJ_DAG_MAX_SWITCHES) must decline at the size gate"
        );
    }
}

// =======================================================================
// Trust: field-read leaf — "field-read of `&self` + integer width-cast,
// scalar return". Unit tests for the three new pieces: `SemOperand::Field`
// (reuses `Index`/`idx_elem`), `sem_field_read_operand` (the shape
// recognizer), `resolve_widening_cast_rvalue` (the sound-cast recognizer).
// The whole-function positive (the REAL `ArrayVec::len` shape) and the
// call-composition positive live in `fixtures/leaf-call-corpus` (see
// `prove.rs`'s corpus test); these are the fail-closed/soundness controls.
// =======================================================================

#[test]
fn field_operand_desugars_to_index_and_certifies_modulo_3() {
    let field = SemOperand::Field(Box::new(SemOperand::Var(0)), 0);
    let index = SemOperand::Index(Box::new(SemOperand::Var(0)), Box::new(SemOperand::Const(0)));
    // INTENTIONAL REUSE: the closed syntax term is BYTE-IDENTICAL to `Index
    // base (Const fld)` — no new Clean declaration for `Field`.
    assert_eq!(field.to_operand_expr(), index.to_operand_expr());
    let cert = operand_adequacy_witness(&field)
        .expect("the field-read operand gets a modulo-3 certificate (via idx_elem)");
    assert!(cert.is_modulo_3());
}

/// SOUNDNESS: a field-read's CONTENT can never be claimed — `idx_elem` is
/// OPAQUE (never unfolds), so a claim that the field equals some concrete
/// literal is NOT def-eq to `idx_elem (e p) fld` and the kernel REJECTS it.
/// This is the honest bound the mission calls out: "the leaf's postcondition
/// axis stays vacuous-true-only" — a wrong postcondition (a content claim)
/// is KernelRejected, never proven.
#[test]
fn wrong_field_content_claim_fails_closed() {
    let field = SemOperand::Field(Box::new(SemOperand::Var(0)), 0);
    let wrong_rhs = int_lit(5); // CLAIM: the field always equals 5. FALSE (opaque).
    let verdict = check_operand_adequacy_inner(&field, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a claimed field VALUE must be kernel-rejected (idx_elem is opaque), got {verdict:?}"
    );
}

/// `sem_field_read_operand` positive + every documented negative control.
#[test]
fn sem_field_read_operand_recognizes_shared_ref_field_and_declines_others() {
    use trust_types::{LocalDecl, Operand, Place, Projection, Ty, VerifiableBody};
    let u32t = || Ty::Int { width: 32, signed: false };
    let record = || Ty::adt("S", vec![("0".into(), u32t())]);
    let shared_ref = || Ty::Ref { mutable: false, inner: Box::new(record()) };
    let mut_ref = || Ty::Ref { mutable: true, inner: Box::new(record()) };
    let body_with = |self_ty: Ty| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: u32t(), name: None },
            LocalDecl { index: 1, ty: self_ty, name: Some("self".into()) },
            LocalDecl { index: 2, ty: u32t(), name: None },
        ],
        blocks: vec![],
        arg_count: 1,
        return_ty: u32t(),
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };

    // POSITIVE: `Copy (*self).0` on an IMMUTABLE reference parameter.
    let body = body_with(shared_ref());
    let op = Operand::Copy(Place {
        local: 1,
        projections: vec![Projection::Deref, Projection::Field(0)],
    });
    assert_eq!(
        sem_field_read_operand(&body, &op, &param_index),
        Some(SemOperand::Field(Box::new(SemOperand::Var(0)), 0))
    );
    // `Move` is admitted identically.
    let op_move = Operand::Move(Place {
        local: 1,
        projections: vec![Projection::Deref, Projection::Field(0)],
    });
    assert_eq!(
        sem_field_read_operand(&body, &op_move, &param_index),
        Some(SemOperand::Field(Box::new(SemOperand::Var(0)), 0))
    );

    // NEGATIVE (a): `&mut self` — a MUTABLE reference declines.
    let mut_body = body_with(mut_ref());
    assert_eq!(
        sem_field_read_operand(&mut_body, &op, &param_index),
        None,
        "&mut self field reads must decline"
    );

    // NEGATIVE (b): bare `Field(0)` with NO `Deref` (a by-value struct field,
    // not a reference field-read) declines — outside THIS leaf's shape.
    let bare_field = Operand::Copy(Place { local: 1, projections: vec![Projection::Field(0)] });
    assert_eq!(sem_field_read_operand(&body, &bare_field, &param_index), None);

    // NEGATIVE (c): bare `Deref` with NO `Field` (a plain `*self` read)
    // declines — not a field projection.
    let bare_deref = Operand::Copy(Place { local: 1, projections: vec![Projection::Deref] });
    assert_eq!(sem_field_read_operand(&body, &bare_deref, &param_index), None);

    // NEGATIVE (d): a NESTED / deeper projection `(*self).0.1` declines.
    let nested = Operand::Copy(Place {
        local: 1,
        projections: vec![Projection::Deref, Projection::Field(0), Projection::Field(1)],
    });
    assert_eq!(sem_field_read_operand(&body, &nested, &param_index), None);

    // NEGATIVE (e): the base is NOT a parameter (e.g. local 2) — declines.
    let non_param = Operand::Copy(Place {
        local: 2,
        projections: vec![Projection::Deref, Projection::Field(0)],
    });
    assert_eq!(sem_field_read_operand(&body, &non_param, &param_index), None);
}

/// Trust: W6 increment-3 (CAPTURING closures, 2026-07-18) — the by-value
/// Closure-typed ENV upvar read `_1.i` positive + every capture-specific
/// forgery control. The env is a closure body's first parameter (`param_index`
/// gives `Some`, only the env has `Ty::Closure`); upvar `i` models as the
/// MODEL-ONLY `Field(Var env_idx, i)` opaque total selector.
#[test]
fn capturing_closure_upvar_read_admits_and_declines_forgeries() {
    use trust_types::{
        ClosureCallKind, ClosureCallSig, LocalDecl, Operand, Place, Projection, Rvalue,
        SourceSpan, Statement, Ty, VerifiableBody,
    };
    let i32t = || Ty::Int { width: 32, signed: true };
    // A closure ENV type: one i32 upvar, given call kind.
    let env_ty = |kind: ClosureCallKind| Ty::Closure {
        name: "cap::{closure#0}".into(),
        upvars: vec![i32t()],
        call: Some(Box::new(ClosureCallSig { kind, params: vec![i32t()], ret: Some(i32t()) })),
    };
    // Standard closure-body locals: _0 ret, _1 env (Closure), _2 x. arg_count=2 ⇒
    // the env is param index 0.
    let body_with = |self_ty: Ty, blocks: Vec<trust_types::BasicBlock>| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: i32t(), name: None },
            LocalDecl { index: 1, ty: self_ty, name: None },
            LocalDecl { index: 2, ty: i32t(), name: Some("x".into()) },
        ],
        blocks,
        arg_count: 2,
        return_ty: i32t(),
    };
    let param_index = |local: usize| -> Option<u64> { (1..=2).contains(&local).then(|| (local - 1) as u64) };
    let field0 = || Operand::Copy(Place { local: 1, projections: vec![Projection::Field(0)] });

    // POSITIVE: `_1.0` on a by-value FnOnce Closure env ⇒ `Field(Var 0, 0)`.
    let fnonce = body_with(env_ty(ClosureCallKind::FnOnce), vec![]);
    assert_eq!(
        sem_field_read_operand(&fnonce, &field0(), &param_index),
        Some(SemOperand::Field(Box::new(SemOperand::Var(0)), 0)),
        "the FnOnce capturing-env upvar read must model as Field(Var 0, 0)"
    );
    // POSITIVE: a `Fn` (shared-borrow env) closure is ALSO admitted (stable env).
    let fnkind = body_with(env_ty(ClosureCallKind::Fn), vec![]);
    assert_eq!(
        sem_field_read_operand(&fnkind, &field0(), &param_index),
        Some(SemOperand::Field(Box::new(SemOperand::Var(0)), 0)),
        "a Fn (shared-borrow) capturing-env upvar read is admitted"
    );

    // FORGERY (a): an `FnMut` (mutable-borrow env) closure DECLINES — a mutable
    // env can rebind captures between calls, so the entry-time value is unstable.
    let fnmut = body_with(env_ty(ClosureCallKind::FnMut), vec![]);
    assert_eq!(
        sem_field_read_operand(&fnmut, &field0(), &param_index),
        None,
        "an FnMut capturing-env upvar read must decline (unstable env)"
    );
    // FORGERY (a'): a closure whose call signature is UNKNOWN (`call: None`)
    // declines — the kind is unverifiable, so fail closed.
    let no_sig = body_with(
        Ty::Closure { name: "cap::{closure#0}".into(), upvars: vec![i32t()], call: None },
        vec![],
    );
    assert_eq!(sem_field_read_operand(&no_sig, &field0(), &param_index), None);

    // FORGERY (b): an out-of-range upvar index `_1.5` on a 1-upvar env declines.
    let oob = Operand::Copy(Place { local: 1, projections: vec![Projection::Field(5)] });
    assert_eq!(
        sem_field_read_operand(&fnonce, &oob, &param_index),
        None,
        "an out-of-range upvar index must decline"
    );

    // FORGERY (c): a MULTI-LEVEL projection `_1.0.1` (upvar-of-upvar) declines —
    // the single-level `[Field]` shape never matches it.
    let multilevel = Operand::Copy(Place {
        local: 1,
        projections: vec![Projection::Field(0), Projection::Field(1)],
    });
    assert_eq!(sem_field_read_operand(&fnonce, &multilevel, &param_index), None);

    // FORGERY (d): the env is REASSIGNED before the read (`_1 := <use>`) — the
    // entry-time-value gate (`param_reassigned_by_stmt`) declines.
    let reassign_block = trust_types::BasicBlock {
        id: trust_types::BlockId(0),
        stmts: vec![Statement::Assign {
            place: Place { local: 1, projections: vec![] },
            rvalue: Rvalue::Use(Operand::Copy(Place { local: 2, projections: vec![] })),
            span: SourceSpan::default(),
        }],
        terminator: trust_types::Terminator::Return,
    };
    let reassigned = body_with(env_ty(ClosureCallKind::FnOnce), vec![reassign_block]);
    assert_eq!(
        sem_field_read_operand(&reassigned, &field0(), &param_index),
        None,
        "a reassigned env must decline (stale entry-time value)"
    );

    // FORGERY (a, in-practice): the env upvar is MUTATED via a projected write
    // `_1.0 := <use>` (how a real capture-mutating closure appears even when its
    // recorded kind is FnOnce, e.g. `cap_fnmut`) — the projected-write gate declines.
    let mutate_block = trust_types::BasicBlock {
        id: trust_types::BlockId(0),
        stmts: vec![Statement::Assign {
            place: Place { local: 1, projections: vec![Projection::Field(0)] },
            rvalue: Rvalue::Use(Operand::Copy(Place { local: 2, projections: vec![] })),
            span: SourceSpan::default(),
        }],
        terminator: trust_types::Terminator::Return,
    };
    let mutated = body_with(env_ty(ClosureCallKind::FnOnce), vec![mutate_block]);
    assert_eq!(
        sem_field_read_operand(&mutated, &field0(), &param_index),
        None,
        "a projected upvar WRITE (env mutation) must decline the read"
    );

    // FORGERY (f): a wrong-FIELD content claim — read `.0` but claim `.1`'s
    // denotation. `idx_elem` is opaque, so `Field(base,0)` is NOT def-eq to
    // `Field(base,1)`; the kernel REJECTS the claim (never a false certificate).
    let read0 = SemOperand::Field(Box::new(SemOperand::Var(0)), 0);
    let claim1 = SemOperand::Field(Box::new(SemOperand::Var(0)), 1).to_operand_expr();
    let verdict = check_operand_adequacy_inner(&read0, Some(&claim1));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "claiming field .1's denotation for a .0 read must be kernel-rejected, got {verdict:?}"
    );
}

/// Trust: W-REF-FWD — `sem_call_arg_ref_operand` resolves the immutable
/// address-of forwarder receiver (`_t := &place`) REF-TRANSPARENTLY, and
/// declines EVERY forgery: a `&mut` ref, a reassigned referent, an
/// unresolvable referent, a multiply-assigned ref temp, and a non-`Ref`
/// rvalue. Mirrors the ref-fwd-cascade corpus (direct_fwd / wrap_set /
/// cfg_has_name) at the operand-resolver granularity.
#[test]
fn sem_call_arg_ref_operand_resolves_immutable_referent_and_declines_forgeries() {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
        Statement, Terminator, Ty, VerifiableBody,
    };
    let opt = optres_option_i32_enum;
    let shared = |inner: Ty| Ty::Ref { mutable: false, inner: Box::new(inner) };
    let mutref = |inner: Ty| Ty::Ref { mutable: true, inner: Box::new(inner) };
    // local 1 is the sole parameter (0-based binding index 0).
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let mk = |locals: Vec<LocalDecl>, stmts: Vec<Statement>| VerifiableBody {
        locals,
        blocks: vec![BasicBlock { id: BlockId(0), stmts, terminator: Terminator::Return }],
        arg_count: 1,
        return_ty: Ty::Bool,
    };
    let assign = |dst: usize, rv: Rvalue| Statement::Assign {
        place: Place::local(dst),
        rvalue: rv,
        span: Default::default(),
    };
    let arg_move = Operand::Move(Place::local(2));

    // POSITIVE (direct_fwd): `_2 := &_1` (immutable, `_1` a bare by-value
    // param) — resolves ref-transparently to `Var(0)`.
    let direct = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: opt(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: shared(opt()), name: None },
        ],
        vec![assign(2, Rvalue::Ref { mutable: false, place: Place::local(1) })],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&direct, &arg_move, BlockId(0), &param_index),
        Some(SemOperand::Var(0)),
        "&param forwarder receiver resolves to the referent Var"
    );
    // A `Copy` arg is admitted identically to `Move`.
    assert_eq!(
        sem_call_arg_ref_operand(
            &direct,
            &Operand::Copy(Place::local(2)),
            BlockId(0),
            &param_index,
        ),
        Some(SemOperand::Var(0)),
    );
    // ...and the full call-arg entry point routes it here too.
    assert_eq!(
        sem_call_arg_operand(&direct, &arg_move, BlockId(0), &param_index),
        Some(SemOperand::Var(0)),
    );

    // POSITIVE (wrap_set / cfg_has_name): `_2 := &((*_1).0)`, `_1 : &Adt`
    // immutable — resolves to `Field(Var(0), 0)`.
    let field = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl {
                index: 1,
                ty: shared(Ty::adt("Wrapper", vec![("0".to_string(), opt())])),
                name: Some("w".into()),
            },
            LocalDecl { index: 2, ty: shared(opt()), name: None },
        ],
        vec![assign(
            2,
            Rvalue::Ref {
                mutable: false,
                place: Place {
                    local: 1,
                    projections: vec![Projection::Deref, Projection::Field(0)],
                },
            },
        )],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&field, &arg_move, BlockId(0), &param_index),
        Some(SemOperand::Field(Box::new(SemOperand::Var(0)), 0)),
        "&(*w).0 forwarder receiver resolves to the referent Field"
    );

    // A legacy/flattened ADT spelling without exact variant metadata is not
    // an authenticated enum value and must not enter the opaque enum lane.
    let legacy = Ty::adt("std::option::Option", vec![]);
    let untyped_enum = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: legacy.clone(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: shared(legacy), name: None },
        ],
        vec![assign(2, Rvalue::Ref { mutable: false, place: Place::local(1) })],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&untyped_enum, &arg_move, BlockId(0), &param_index),
        None,
        "an ADT name without exact enum metadata must decline"
    );

    // NEGATIVE (a) — THE `&mut` FORGERY PROBE: `_2 := &mut _1`. A mutable
    // receiver may mutate the referent; the entry-time referent-value model is
    // INVALID.
    let mutbl = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: opt(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: mutref(opt()), name: None },
        ],
        vec![assign(2, Rvalue::Ref { mutable: true, place: Place::local(1) })],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&mutbl, &arg_move, BlockId(0), &param_index),
        None,
        "a &mut (mutable) ref receiver MUST decline"
    );

    // NEGATIVE (b) — reassigned referent: `_1 := <const>; _2 := &_1`. The
    // referent base parameter is reassigned before the borrow — the entry-time
    // value is stale, so decline.
    let reassigned = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: opt(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: shared(opt()), name: None },
        ],
        vec![
            assign(1, Rvalue::Use(Operand::Constant(ConstValue::Bool(false)))),
            assign(2, Rvalue::Ref { mutable: false, place: Place::local(1) }),
        ],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&reassigned, &arg_move, BlockId(0), &param_index),
        None,
        "a ref of a REASSIGNED referent param MUST decline"
    );

    // NEGATIVE (c) — unresolvable referent: `_2 := &_3` where `_3` is a
    // non-parameter temp the concrete resolvers decline (a ref-of-ref / exotic
    // referent). NEVER invents an operand.
    let unresolvable = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: opt(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: shared(opt()), name: None },
            LocalDecl { index: 3, ty: opt(), name: None },
        ],
        vec![assign(2, Rvalue::Ref { mutable: false, place: Place::local(3) })],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&unresolvable, &arg_move, BlockId(0), &param_index),
        None,
        "a ref of an unresolvable (non-parameter) referent MUST decline"
    );

    // NEGATIVE (d) — multiply-assigned ref temp: two writes to `_2` — not
    // sole-writer, so `local_soundly_resolvable` declines.
    let multi = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: opt(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: shared(opt()), name: None },
        ],
        vec![
            assign(2, Rvalue::Ref { mutable: false, place: Place::local(1) }),
            assign(2, Rvalue::Ref { mutable: false, place: Place::local(1) }),
        ],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&multi, &arg_move, BlockId(0), &param_index),
        None,
        "a MULTIPLY-assigned ref temp MUST decline"
    );

    // NEGATIVE (e) — the sole assignment is NOT a `Ref` (a plain `Use`): THIS
    // recognizer declines (a different chase handles a `Use` arg) — it never
    // absorbs a non-address-of temp.
    let non_ref = mk(
        vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: None },
            LocalDecl { index: 1, ty: opt(), name: Some("o".into()) },
            LocalDecl { index: 2, ty: opt(), name: None },
        ],
        vec![assign(2, Rvalue::Use(Operand::Copy(Place::local(1))))],
    );
    assert_eq!(
        sem_call_arg_ref_operand(&non_ref, &arg_move, BlockId(0), &param_index),
        None,
        "a non-Ref sole assignment MUST decline in THIS recognizer"
    );

    // NEGATIVE (f) — the unique immutable-ref definition is confined to a
    // sibling branch and therefore does not dominate the call use. A global
    // sole-writer scan alone would select it even though that value does not
    // exist along the use path.
    let mut non_dominating = direct.clone();
    non_dominating.blocks = vec![
        BasicBlock {
            id: BlockId(0),
            stmts: vec![],
            terminator: Terminator::SwitchInt {
                discr: Operand::Constant(ConstValue::Bool(true)),
                targets: vec![(0, BlockId(1))],
                otherwise: BlockId(2),
                exhaustive_enum_unreachable: false,
                span: Default::default(),
            },
        },
        BasicBlock {
            id: BlockId(1),
            stmts: vec![assign(2, Rvalue::Ref { mutable: false, place: Place::local(1) })],
            terminator: Terminator::Goto(BlockId(3)),
        },
        BasicBlock { id: BlockId(2), stmts: vec![], terminator: Terminator::Return },
        BasicBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
    ];
    assert_eq!(
        sem_call_arg_ref_operand(&non_dominating, &arg_move, BlockId(2), &param_index,),
        None,
        "a sibling-branch ref definition MUST NOT resolve at the call use"
    );
}

/// `resolve_widening_cast_rvalue` positive + every documented negative
/// control: a TRUNCATING cast, a signedness REINTERPRET, and a non-integer
/// cast all fail closed (never modeled as identity).
#[test]
fn resolve_widening_cast_rvalue_admits_widening_declines_truncating_and_reinterpret() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Terminator, Ty, VerifiableBody,
    };
    let u32t = || Ty::Int { width: 32, signed: false };
    let u64t = || Ty::Int { width: 64, signed: false };
    let i64t = || Ty::Int { width: 64, signed: true };
    let mk_body = |src_ty: Ty| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: u64t(), name: None },
            LocalDecl { index: 1, ty: src_ty, name: Some("x".into()) },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![],
            terminator: Terminator::Return,
        }],
        arg_count: 1,
        return_ty: u64t(),
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let op = Operand::Copy(Place::local(1));

    // POSITIVE: u32 -> u64, widening, same signedness.
    let body = mk_body(u32t());
    assert_eq!(
        resolve_widening_cast_rvalue(&body, &op, &u64t(), &param_index, None),
        Some(SemRvalue::Use(SemOperand::Var(0)))
    );

    // NEGATIVE: u64 -> u32, TRUNCATING — declines (never identity).
    let trunc_body = mk_body(u64t());
    assert_eq!(
        resolve_widening_cast_rvalue(&trunc_body, &op, &u32t(), &param_index, None),
        None
    );

    // POSITIVE (GAP-CROSS-SIGN-WIDEN, 2026-07-16): u32 -> i64 is a
    // SIGN-CROSSING *widening* (`W=64 > w=32`), hence VALUE-PRESERVING —
    // now admitted as the identity `Use` of the resolved source. (This row
    // measured SHAPE_GAP before the sign-cross clause landed; it is one of
    // the 14 cast-corpus rows the clause flips.)
    assert_eq!(
        resolve_widening_cast_rvalue(&body, &op, &i64t(), &param_index, None),
        Some(SemRvalue::Use(SemOperand::Var(0))),
        "u32 -> i64 (sign-crossing WIDENING, W>w) is value-preserving — must admit"
    );

    // NEGATIVE: u32 -> i32, a SAME-WIDTH signedness REINTERPRET (`dw == sw`,
    // NOT a strict widening) — value-CHANGING on the top half
    // (`u32 3e9 -> i32 < 0`) — declines. The sign-cross clause is gated to
    // STRICT `dw > sw`, so this near-miss still fails closed.
    let i32t = || Ty::Int { width: 32, signed: true };
    assert_eq!(resolve_widening_cast_rvalue(&body, &op, &i32t(), &param_index, None), None);
}

/// Trust: GAP-CROSS-SIGN-WIDEN (2026-07-16) — the sign-crossing WIDENING
/// cast `u_w -> i_W` (`W > w`) is admitted as the value-identity, while
/// every near-miss (same-width sign cross, narrowing sign cross, `i -> u`
/// wrong-way cross) and every adversarial forgery (an accepting-but-WRONG
/// width/signedness relation) DECLINES named — fail-closed by construction.
#[test]
fn resolve_widening_cast_rvalue_signcross_widen_admits_and_fail_closed() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Terminator, Ty, VerifiableBody,
    };
    let int = |w: u32, s: bool| Ty::Int { width: w, signed: s };
    let mk = |src: Ty, ret: Ty| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: ret.clone(), name: None },
            LocalDecl { index: 1, ty: src, name: Some("src".into()) },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![],
            terminator: Terminator::Return,
        }],
        arg_count: 1,
        return_ty: ret,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let op = Operand::Copy(Place::local(1));

    // POSITIVE: every real sign-crossing widening the cast 0.3.0 corpus ships
    // (u8->i16/i32/i64/i128, u16->i32/i64/i128, u32->i64/i128, u64->i128) —
    // the source resolves to the parameter `Var 0`; the cast is the identity.
    for (sw, dw) in [
        (8u32, 16u32),
        (8, 32),
        (8, 64),
        (8, 128),
        (16, 32),
        (16, 64),
        (16, 128),
        (32, 64),
        (32, 128),
        (64, 128),
    ] {
        let body = mk(int(sw, false), int(dw, true));
        assert_eq!(
            resolve_widening_cast_rvalue(&body, &op, &int(dw, true), &param_index, None),
            Some(SemRvalue::Use(SemOperand::Var(0))),
            "u{sw} -> i{dw} (W>w) must admit as value-identity"
        );
    }

    // NAMED DECLINE (a) — SAME-WIDTH sign cross `u_w -> i_w`: a value-CHANGING
    // reinterpret (`u8 255 -> i8 == -1`). MUST decline (gate is strict `dw > sw`).
    for w in [8u32, 16, 32, 64, 128] {
        let body = mk(int(w, false), int(w, true));
        assert_eq!(
            resolve_widening_cast_rvalue(&body, &op, &int(w, true), &param_index, None),
            None,
            "u{w} -> i{w} same-width sign cross is a reinterpret — MUST decline"
        );
    }

    // NAMED DECLINE (b) — NARROWING sign cross `u_W -> i_w` (`W > w`): truncates
    // (`u16 40000 -> i8`). MUST decline.
    for (sw, dw) in [(16u32, 8u32), (32, 16), (64, 32), (128, 64), (64, 8)] {
        let body = mk(int(sw, false), int(dw, true));
        assert_eq!(
            resolve_widening_cast_rvalue(&body, &op, &int(dw, true), &param_index, None),
            None,
            "u{sw} -> i{dw} narrowing sign cross — MUST decline"
        );
    }

    // ADVERSARIAL FORGERY (c) — `i -> u` crossing the WRONG way (signed source,
    // unsigned dest), even WIDENING: NOT value-preserving on negatives
    // (`i8 -1 -> u16 == 65535`). The clause is guarded by `*ds` (dest signed),
    // so a signed source never reaches the admit — MUST decline.
    for (sw, dw) in [(8u32, 16u32), (16, 32), (8, 64), (8, 128), (8, 8)] {
        let body = mk(int(sw, true), int(dw, false));
        assert_eq!(
            resolve_widening_cast_rvalue(&body, &op, &int(dw, false), &param_index, None),
            None,
            "i{sw} -> u{dw} (sign cross wrong way) — MUST decline"
        );
    }

    // ADVERSARIAL FORGERY (d) — a SIGNED-source widening `i_w -> i_W` that the
    // sign-cross clause must NOT claim (it is same-sign, handled — if at all —
    // by the same-sign path; the sign-cross clause requires `!ss`), and a
    // signed NARROWING `i_W -> i_w` which MUST decline everywhere.
    assert_eq!(
        resolve_widening_cast_rvalue(
            &mk(int(64, true), int(16, true)),
            &op,
            &int(16, true),
            &param_index,
            None,
        ),
        None,
        "i64 -> i16 signed narrowing — MUST decline"
    );
}

#[test]
fn cast_assignment_destination_type_mismatch_fails_closed() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator, Ty,
        VerifiableBody, VerifiableFunction,
    };
    let i32_ty = Ty::Int { width: 32, signed: true };
    let i16_ty = Ty::Int { width: 16, signed: true };
    let u8_ty = Ty::Int { width: 8, signed: false };
    let func = VerifiableFunction {
        name: "forged_cast_dest".into(),
        def_path: "crate::forged_cast_dest".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i32_ty.clone(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: u8_ty, name: Some("x".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    // The rvalue claims i16 while its destination `_0` is i32.
                    // Valid rustc MIR cannot do this, but serialized input is
                    // adversarial and must not gain a certificate.
                    rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), i16_ty),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: i32_ty,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    let param_index = |local: usize| (local == 1).then_some(0);
    assert!(sem_return_of_mir(&func, &param_index).is_none());
    let empty = std::collections::BTreeMap::new();
    assert!(!crate::prove::diagnose_fully_faithful_gate(&func, &empty).fully_faithful);

    // A second forgery makes the assignment internally type-consistent but
    // lies in `body.return_ty`. The shared structural validator is the
    // admission boundary for both certificate lanes and the production
    // diagnosis; UnsupportedMir must not be filtered into vacuous safety.
    let mut forged_return_ty = func;
    forged_return_ty.body.locals[0].ty = Ty::Int { width: 16, signed: true };
    assert!(trust_vcgen::validate_function(&forged_return_ty).is_err());
    assert!(function_adequacy_witness_with_callees(&forged_return_ty, &empty).is_none());
    assert!(
        !crate::prove::diagnose_fully_faithful_gate(&forged_return_ty, &empty).fully_faithful
    );
}

/// Trust: M6 rung 6 — the SHIFT-NARROWED EXACT cast width fact, both
/// directions on the REAL leaf shape (`_3 := Shr(x: u64, k); _0 := _3 as
/// u32`, the `ExprMeta::loose_bvar_range` body minus its Assert):
///   * POSITIVE: `k = 44` — `64 − 44 = 20 ≤ 32`, value-preserving —
///     resolves to the Shr rvalue itself;
///   * ADVERSARIAL: `k = 16` — `64 − 16 = 48 > 32`, the shifted value can
///     exceed `u32::MAX`, so the narrowing genuinely truncates — declines;
///   * ADVERSARIAL: a SIGNED destination (`i32`) declines (signedness
///     reinterpret, no width fact).
#[test]
fn shift_narrowed_cast_width_fact_admits_and_declines() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let u64t = || Ty::Int { width: 64, signed: false };
    let u32t = || Ty::Int { width: 32, signed: false };
    let i32t = || Ty::Int { width: 32, signed: true };
    let mk_body = |k: u128| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: u32t(), name: None },
            LocalDecl { index: 1, ty: u64t(), name: Some("x".into()) },
            LocalDecl { index: 2, ty: u64t(), name: None },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(2),
                rvalue: Rvalue::BinaryOp(
                    BinOp::Shr,
                    Operand::Copy(Place::local(1)),
                    Operand::Constant(ConstValue::Uint(k, 32)),
                ),
                span: Default::default(),
            }],
            terminator: Terminator::Return,
        }],
        arg_count: 1,
        return_ty: u32t(),
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let op = Operand::Move(Place::local(2));

    // POSITIVE: (x >> 44) as u32 — 64−44 = 20 ≤ 32 — models as the Shr itself.
    let body = mk_body(44);
    assert_eq!(
        resolve_widening_cast_rvalue(&body, &op, &u32t(), &param_index, None),
        Some(SemRvalue::Bin(SemBinOp::Shr, SemOperand::Var(0), SemOperand::Const(44))),
        "(x:u64 >> 44) as u32 is value-preserving — must model as the Shr rvalue"
    );
    // ADVERSARIAL: (x >> 16) as u32 — 64−16 = 48 > 32 — a GENUINE truncation.
    let wide = mk_body(16);
    assert_eq!(
        resolve_widening_cast_rvalue(&wide, &op, &u32t(), &param_index, None),
        None,
        "(x:u64 >> 16) as u32 can truncate (48-bit value) — MUST decline"
    );
    // ADVERSARIAL: (x >> 44) as i32 — signedness reinterpret — declines.
    assert_eq!(
        resolve_widening_cast_rvalue(&body, &op, &i32t(), &param_index, None),
        None,
        "a signed narrowing destination has no width fact — MUST decline"
    );
}

/// Trust: M6 rung 6 — BY-VALUE param field read (`self.0` on a by-value ADT
/// param), positive + the entry-time-value adversarial gates:
///   * POSITIVE: a read-only by-value ADT param's field resolves to
///     `Field(Var 0, 0)`;
///   * ADVERSARIAL: the SAME body with a direct FIELD WRITE (`_1.0 = ..`)
///     before the read — declines (the entry-time read would be stale);
///   * ADVERSARIAL: a NON-ADT by-value param (bare u64) declines (no field
///     to read — malformed projection).
#[test]
fn by_value_param_field_read_admits_and_declines_when_field_written() {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
        Statement, Terminator, Ty, VerifiableBody,
    };
    let u64t = || Ty::Int { width: 64, signed: false };
    let meta_ty = || Ty::adt("expr::meta::ExprMeta", vec![("0".into(), u64t())]);
    let mk_body = |self_ty: Ty, field_write: bool| {
        let mut stmts = Vec::new();
        if field_write {
            stmts.push(Statement::Assign {
                place: Place { local: 1, projections: vec![Projection::Field(0)] },
                rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(7, 64))),
                span: Default::default(),
            });
        }
        VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u64t(), name: None },
                LocalDecl { index: 1, ty: self_ty, name: Some("self".into()) },
            ],
            blocks: vec![BasicBlock { id: BlockId(0), stmts, terminator: Terminator::Return }],
            arg_count: 1,
            return_ty: u64t(),
        }
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let op = Operand::Copy(Place { local: 1, projections: vec![Projection::Field(0)] });

    // POSITIVE: read-only by-value ADT param field read.
    let body = mk_body(meta_ty(), false);
    assert_eq!(
        sem_field_read_operand(&body, &op, &param_index),
        Some(SemOperand::Field(Box::new(SemOperand::Var(0)), 0)),
        "a read-only by-value ADT param's field read must resolve"
    );
    // ADVERSARIAL: a direct field WRITE to the param — entry-time read is
    // stale — declines.
    let written = mk_body(meta_ty(), true);
    assert_eq!(
        sem_field_read_operand(&written, &op, &param_index),
        None,
        "a field-written by-value param MUST decline (entry-time-value soundness)"
    );
    // ADVERSARIAL: a non-ADT by-value param declines.
    let non_adt = mk_body(u64t(), false);
    assert_eq!(
        sem_field_read_operand(&non_adt, &op, &param_index),
        None,
        "a Field projection on a non-ADT param MUST decline"
    );
}

/// Trust: M6 rung 6 — the LITERAL-amount shift VC boundary, BOTH sides:
///   * IN-RANGE (`x >> 44`, u64): the ShiftOverflow VC's literal core
///     `Ge(44, 64)` is kernel-certified ADEQUATE (Lemma 7's closed-literal
///     arm) AND discharges (44 < 64 refutes modulo 3), so the whole
///     function — the real `ExprMeta::loose_bvar_range` shape, rebuilt
///     synthetically — is FULLY FAITHFUL on the MirSem lane;
///   * OUT-OF-RANGE ADVERSARIAL (`x >> 70`, u64): the SAME machinery mints
///     the SAME adequacy certificate (the model faithfully reflects the
///     violation `Ge(70, 64)` — adequacy is about FIDELITY, not safety),
///     but the VC is now GENUINELY TRUE (70 ≥ 64: the shift IS UB), so the
///     discharge gate fails and the function MUST NOT be fully faithful.
///     This pins the fail-closed boundary of the new literal arm: modeling
///     a literal shift can never certify an actually-out-of-range one.
#[test]
fn literal_shift_in_range_fully_faithful_and_oob_literal_stays_open() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
        Statement, Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u64t = || Ty::Int { width: 64, signed: false };
    let u32t = || Ty::Int { width: 32, signed: false };
    let meta_ty = || Ty::adt("probe::Meta", vec![("0".into(), u64t())]);
    let mk = |k: u128| VerifiableFunction {
        name: "range".into(),
        def_path: "probe::Meta::range".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u32t(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: meta_ty(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: u64t(), name: None },
                LocalDecl { index: 3, ty: u64t(), name: None },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Use(Operand::Copy(Place {
                            local: 1,
                            projections: vec![Projection::Field(0)],
                        })),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Shr,
                            Operand::Move(Place::local(3)),
                            Operand::Constant(ConstValue::Uint(k, 32)),
                        ),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Cast(Operand::Move(Place::local(2)), u32t()),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: u32t(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    // IN-RANGE: the composed witness mints AND the discharge closes ⇒ the
    // production FF gate (witness && discharge) holds.
    let ok = mk(44);
    assert!(
        function_fully_faithful_witness(&ok).is_some_and(|c| c.is_modulo_3()),
        "the in-range literal-shift leaf must mint the composed witness modulo 3"
    );
    assert!(
        crate::prove::function_safety_vcs_all_discharged(&ok),
        "the in-range literal shift VC (44 < 64) must DISCHARGE modulo 3"
    );
    // OUT-OF-RANGE: `x >> 70` on u64 — the shift is genuinely UB-capable.
    // The discharge gate MUST stay open (70 ≥ 64 is TRUE — no refutation),
    // so the production gate fails regardless of adequacy.
    let oob = mk(70);
    assert!(
        !crate::prove::function_safety_vcs_all_discharged(&oob),
        "an OUT-OF-RANGE literal shift (70 ≥ 64) must NOT discharge — the \
         literal arm can never certify an actually-UB shift"
    );
}

// =======================================================================
// Trust: CAST-TEMP GUARD READ (2026-07-08) — `_2 = _1 as u8; <guard reads
// _2>` (the `<char as Check>::{is_control,is_extended,is_printable,
// is_us_ascii}` shape). `sem_guard_cast_temp_operand` / `SemOperand::Cast`.
// =======================================================================

/// Build a body with ONE non-`Bool` param `_1 : src_ty` and a cast temp
/// `_2 := Cast(_1, dest_ty)` (the exact `<char as Check>` shape, minus the
/// guard comparisons themselves — those are exercised by the real-fixture
/// test below).
fn mk_cast_temp_body(
    src_ty: trust_types::Ty,
    dest_ty: trust_types::Ty,
) -> trust_types::VerifiableBody {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
    };
    trust_types::VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: trust_types::Ty::Bool, name: None },
            LocalDecl { index: 1, ty: src_ty, name: Some("self".into()) },
            LocalDecl { index: 2, ty: dest_ty.clone(), name: None },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(2),
                rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), dest_ty),
                span: Default::default(),
            }],
            terminator: Terminator::Return,
        }],
        arg_count: 1,
        return_ty: trust_types::Ty::Bool,
    }
}

/// POSITIVE: a TRUNCATING cast temp (`char` `u32` → `u8`, the
/// `<char as Check>::is_us_ascii`-class shape) resolves through
/// `sem_guard_cast_temp_operand` to the honest opaque `SemOperand::Cast`
/// carrier — NOT an exact-identity claim.
#[test]
fn sem_guard_cast_temp_operand_recognizes_truncating_cast() {
    let u32t = trust_types::Ty::Int { width: 32, signed: false };
    let u8t = trust_types::Ty::Int { width: 8, signed: false };
    let body = mk_cast_temp_body(u32t, u8t);
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    assert_eq!(
        sem_guard_cast_temp_operand(&body, 2, &param_index, None),
        Some(SemOperand::Cast(Box::new(SemOperand::Var(0)), 8, false))
    );
    // The PUBLIC entry point (`sem_guard_operand_of_mir`) resolves the SAME
    // way for a `Copy`/`Move` of the cast temp — this is the shape
    // `sem_conjunctive_chain`/`sem_decision_dag_chain`'s `switch_leaf`
    // actually calls.
    let cast_temp_op = trust_types::Operand::Copy(trust_types::Place::local(2));
    assert_eq!(
        sem_guard_operand_of_mir(&body, &cast_temp_op, &param_index, None),
        Some(SemOperand::Cast(Box::new(SemOperand::Var(0)), 8, false))
    );
}

/// POSITIVE: a WIDENING cast temp (equal/same-signedness, larger dest
/// width) resolves to the EXACT identity (unwrapped `resolve_widening_cast_rvalue`),
/// never the opaque carrier — the two-tier composition picks the STRONGER
/// claim whenever it is honest to do so.
#[test]
fn sem_guard_cast_temp_operand_widening_is_exact_identity() {
    let u8t = trust_types::Ty::Int { width: 8, signed: false };
    let u32t = trust_types::Ty::Int { width: 32, signed: false };
    let body = mk_cast_temp_body(u8t, u32t);
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    assert_eq!(
        sem_guard_cast_temp_operand(&body, 2, &param_index, None),
        Some(SemOperand::Var(0))
    );
}

/// NEGATIVE (uniqueness gate): a MULTIPLY-assigned cast temp declines
/// through the PUBLIC entry point — `local_soundly_resolvable` rejects it
/// before `sem_guard_cast_temp_operand` is ever tried, so a decoy earlier
/// (or later) write can never be mistaken for the temp's sole definition.
#[test]
fn sem_guard_cast_temp_operand_declines_multiply_assigned() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
    };
    let u32t = trust_types::Ty::Int { width: 32, signed: false };
    let u8t = trust_types::Ty::Int { width: 8, signed: false };
    let body = trust_types::VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: trust_types::Ty::Bool, name: None },
            LocalDecl { index: 1, ty: u32t, name: Some("self".into()) },
            LocalDecl { index: 2, ty: u8t.clone(), name: None },
        ],
        blocks: vec![
            BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(2),
                    rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), u8t.clone()),
                    span: Default::default(),
                }],
                terminator: Terminator::Goto(BlockId(1)),
            },
            BasicBlock {
                id: BlockId(1),
                // A SECOND assignment to the SAME temp — adversarial: the
                // decoy write must not let this temp resolve.
                stmts: vec![Statement::Assign {
                    place: Place::local(2),
                    rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), u8t),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            },
        ],
        arg_count: 1,
        return_ty: trust_types::Ty::Bool,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let cast_temp_op = trust_types::Operand::Copy(trust_types::Place::local(2));
    assert_eq!(
        sem_guard_operand_of_mir(&body, &cast_temp_op, &param_index, None),
        None,
        "a multiply-assigned cast temp must decline fail-closed, never resolve to a decoy write"
    );
}

/// NEGATIVE (fragment gate): a cast whose SOURCE is not `Ty::Int` (a float
/// source) declines — "cast kinds limited to int↔int/char↔int" per the
/// mission scope; a float/pointer cast is outside this fragment.
#[test]
fn sem_guard_cast_temp_operand_declines_non_int_source() {
    let f32t = trust_types::Ty::Float { width: 32 };
    let u8t = trust_types::Ty::Int { width: 8, signed: false };
    let body = mk_cast_temp_body(f32t, u8t);
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    assert_eq!(sem_guard_cast_temp_operand(&body, 2, &param_index, None), None);
}

#[test]
fn nested_cast_source_defined_after_use_declines_at_production_site() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u8_ty = Ty::Int { width: 8, signed: false };
    let u64_ty = Ty::Int { width: 64, signed: false };
    let func = VerifiableFunction {
        name: "after_use_cast_source".into(),
        def_path: "probe::after_use_cast_source".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: Some("_0".into()) },
                LocalDecl { index: 1, ty: u8_ty.clone(), name: Some("x".into()) },
                LocalDecl { index: 2, ty: u64_ty.clone(), name: None },
                LocalDecl { index: 3, ty: u8_ty, name: None },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Cast(Operand::Copy(Place::local(3)), u64_ty),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Eq,
                            Operand::Copy(Place::local(2)),
                            Operand::Constant(ConstValue::Uint(0, 64)),
                        ),
                        span: Default::default(),
                    },
                    // The unique source definition is in the same block but
                    // AFTER both the Cast and the comparison that consumes it.
                    Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::Bool,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    let param_index = |local: usize| (local == 1).then_some(0);
    assert!(sem_return_of_mir(&func, &param_index).is_none());
}

#[test]
fn adt_guard_constant_cast_declines_value_changing_narrowing_and_sign_change() {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let cast_body = |constant: ConstValue, destination: Ty| VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: Ty::Bool, name: Some("_0".into()) },
            LocalDecl { index: 1, ty: destination.clone(), name: None },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(1),
                rvalue: Rvalue::Cast(Operand::Constant(constant), destination),
                span: Default::default(),
            }],
            terminator: Terminator::Return,
        }],
        arg_count: 0,
        return_ty: Ty::Bool,
    };
    let param_index = |_local: usize| None;
    let operand = Operand::Copy(Place::local(1));
    let at_return = Some((BlockId(0), None));

    let widening = cast_body(ConstValue::Uint(255, 8), Ty::Int { width: 16, signed: false });
    assert_eq!(
        sem_adt_guard_operand_of_mir(&widening, &operand, &param_index, at_return),
        Some(SemOperand::Const(255))
    );

    let narrowing = cast_body(ConstValue::Uint(256, 16), Ty::Int { width: 8, signed: false });
    assert_eq!(
        sem_adt_guard_operand_of_mir(&narrowing, &operand, &param_index, at_return),
        None,
        "256u16 as u8 is 0, never the source constant 256"
    );

    let sign_change = cast_body(ConstValue::Uint(255, 8), Ty::Int { width: 8, signed: true });
    assert_eq!(
        sem_adt_guard_operand_of_mir(&sign_change, &operand, &param_index, at_return),
        None,
        "255u8 as i8 is -1, never the source constant 255"
    );

    let negative_to_unsigned =
        cast_body(ConstValue::Int(-1), Ty::Int { width: 8, signed: false });
    assert_eq!(
        sem_adt_guard_operand_of_mir(&negative_to_unsigned, &operand, &param_index, at_return,),
        None,
        "-1i64 as u8 is 255, never the source constant -1"
    );
}

// -------------------------------------------------------------------
// Trust: W11-FLOAT-EXACT-WIDENING (BLOCKED, 2026-07-16) — MirSem-lane
// fail-closed probes (the twin of `prove.rs`'s trust-ir-lane probes). Pin
// that the MirSem return-shape recognizer (`sem_return_of_mir`) and the
// value-identity cast leaf (`resolve_widening_cast_rvalue`) BOTH decline
// every float cast — the exact-widening subset, the rounding near-miss, and
// the narrowing forgery — so no future change shape-only-promotes a float
// cast on the MirSem fallback lane. See `resolve_widening_cast_rvalue`'s
// W11 gate doc for why the exact subset is blocked (exactness-blind vendored
// `semCast`; no real-valued float denotation).
// -------------------------------------------------------------------

/// Build a single-block `_0 := Cast(Copy(_1), dst); Return` float-cast
/// return function (the exact census-fixture shape).
fn w11_float_cast_return_func(
    src: trust_types::Ty,
    dst: trust_types::Ty,
) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, FunctionSpec, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, VerifiableBody, VerifiableFunction,
    };
    let body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: dst.clone(), name: None },
            LocalDecl { index: 1, ty: src, name: Some("src".into()) },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![Statement::Assign {
                place: Place::local(0),
                rvalue: Rvalue::Cast(Operand::Copy(Place::local(1)), dst.clone()),
                span: Default::default(),
            }],
            terminator: Terminator::Return,
        }],
        arg_count: 1,
        return_ty: dst,
    };
    VerifiableFunction {
        name: "cast".into(),
        def_path: "cast::_64::<impl From<Src> for Dst>::cast".into(),
        span: Default::default(),
        body,
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: FunctionSpec::default(),
    }
}

/// These representative float casts — the 11 exact destination candidates,
/// selected rounding near-misses, one narrowing, and one float-source row —
/// MUST decline on the MirSem lane, through BOTH the value-identity
/// cast leaf (`resolve_widening_cast_rvalue`) and the return-shape recognizer
/// (`sem_return_of_mir`). BLOCKED (exactness-blind vendored semantics), not
/// promoted; fail-closed on every case.
#[test]
fn w11_float_casts_decline_fail_closed_via_mirsem() {
    use trust_types::Ty;
    let iy = |w: u32, s: bool| Ty::Int { width: w, signed: s };
    let fy = |w: u32| Ty::Float { width: w };
    // Representative rows only; this is not the complete 50-row corpus.
    let cases: &[(Ty, Ty)] = &[
        // EXACT-widening subset (would-flip candidates — MUST still decline):
        (iy(8, false), fy(32)),
        (iy(16, false), fy(32)),
        (iy(8, true), fy(32)),
        (iy(16, true), fy(32)),
        (iy(8, false), fy(64)),
        (iy(16, false), fy(64)),
        (iy(32, false), fy(64)),
        (iy(8, true), fy(64)),
        (iy(16, true), fy(64)),
        (iy(32, true), fy(64)),
        (fy(32), fy(64)), // f32 -> f64 widening
        // ROUNDING near-miss forgeries:
        (iy(32, false), fy(32)),
        (iy(64, false), fy(64)),
        (iy(64, true), fy(64)),
        (iy(128, false), fy(32)),
        // NARROWING forgery:
        (fy(64), fy(32)),
        // Float SOURCE -> int (GAP-FLOAT-SRC family leaf shape):
        (fy(64), iy(32, true)),
    ];
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    for (src, dst) in cases {
        let f = w11_float_cast_return_func(src.clone(), dst.clone());
        // Value-identity cast leaf must NOT model any float cast.
        let op = trust_types::Operand::Copy(trust_types::Place::local(1));
        assert!(
            resolve_widening_cast_rvalue(&f.body, &op, dst, &param_index, None).is_none(),
            "resolve_widening_cast_rvalue must decline float cast {src:?}->{dst:?} \
             (exactness-blind vendored semantics; promotion would be shape-only)"
        );
        // Whole return-shape recognizer must decline too (fail-closed).
        assert!(
            sem_return_of_mir(&f, &param_index).is_none(),
            "sem_return_of_mir must decline float cast {src:?}->{dst:?}"
        );
    }
}

/// POSITIVE (kernel): the opaque `SemOperand::Cast` carrier's Lemma-1A
/// adequacy proves modulo 3 — the SAME `Index`/`idx_elem` reflexivity
/// machinery `Field`/`Discriminant` already exercise, now covering `Cast`
/// with ZERO new `ground_int`/kernel-decl code (reuses `F::Select`).
#[test]
fn operand_adequacy_witness_cast_carrier_proves_modulo_3() {
    let op = SemOperand::Cast(Box::new(SemOperand::Var(0)), 8, false);
    assert_eq!(check_operand_adequacy(&op), AdequacyVerdict::ProvenModulo3);
    assert!(operand_adequacy_witness(&op).is_some());
}

/// FAIL-CLOSED (kernel): claiming the cast temp's value is the EXACT
/// identity of its source (`cast_value == x`, i.e. pretending truncation
/// never happened) is a WRONG, dishonest claim — the kernel must reject
/// it, never prove it. This is the "wrong-width cast claim KernelRejected"
/// probe: the honest opaque carrier proves `cast_value = idx_elem(x, key)`
/// ONLY, never a stronger claim it does not itself assert.
#[test]
fn wrong_cast_identity_claim_fails_closed() {
    let op = SemOperand::Cast(Box::new(SemOperand::Var(0)), 8, false);
    // Single referenced index (0) ⇒ one outer `Int` binder; `bvar(0)` is
    // that SAME binder (mirrors `adequacy_statement`'s own convention).
    let wrong_rhs = Expr::bvar(0);
    let verdict = check_operand_adequacy_inner(&op, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "claiming cast_value == x (dropping the truncation) MUST be kernel-rejected, got {verdict:?}"
    );
}

