    assert!(!cert.rvalues.is_empty(), "the x+1 rvalue is certified (1B)");
    assert!(cert.operands.iter().all(AdequacyCertificate::is_modulo_3));
    assert!(cert.rvalues.iter().all(RvalueAdequacyCertificate::is_modulo_3));
