// =======================================================================
// Trust: field-read leaf — the WHOLE-FUNCTION shape (the REAL
// `arrayvec::ArrayVec::len` body): `_2 = (*self).0; _0 = _2 as u64; return`.
// Builder + the positive certification and its fail-closed negative
// variants (truncating cast, `&mut self`).
// =======================================================================

/// Build the field-read + widening-cast leaf: `fn len(self: &S) -> u64 { (*self).0
/// as u64 }`, MIRRORING `arrayvec::ArrayVec::len`'s real MIR exactly:
/// `_2 = Copy (*_1).0; _0 = Move _2 as u64; return`. `self_ty` lets the
/// negative controls swap in a mutable reference or a non-widening cast.
fn field_read_cast_leaf_func(
    self_mutable: bool,
    cast_dest: trust_types::Ty,
) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Projection, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u32t = || Ty::Int { width: 32, signed: false };
    let self_ty = Ty::Ref {
        mutable: self_mutable,
        inner: Box::new(Ty::Adt { adt_kind: None, layout: None,
            name: "test::S".into(),
            fields: vec![("0".into(), u32t())],
            variants: vec![],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, }),
    };
    VerifiableFunction {
        name: "len".into(),
        def_path: "test::len".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: cast_dest.clone(), name: None },
                LocalDecl { index: 1, ty: self_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: u32t(), name: None },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Use(Operand::Copy(Place {
                            local: 1,
                            projections: vec![Projection::Deref, Projection::Field(0)],
                        })),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Cast(Operand::Move(Place::local(2)), cast_dest.clone()),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: cast_dest,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn field_read_cast_leaf_is_fully_faithful_on_the_mirsem_witness() {
    let u64t = trust_types::Ty::Int { width: 64, signed: false };
    let func = field_read_cast_leaf_func(false, u64t);
    let cert = function_adequacy_witness(&func)
        .expect("the field-read + widening-cast leaf gets a composed witness");
    assert!(cert.is_modulo_3(), "the composed witness must be modulo-3");
    assert!(!cert.operands.is_empty(), "the field-read operand is certified (1A)");
    assert!(cert.ret.is_modulo_3(), "the SSA-temp return witness is certified");
    // The full per-function verdict (contract + vacuous safety) also mints.
    // (The leaf is ALSO trust-ir-primary now — see the corpus test; this test
    // pins the MirSem-witness half specifically.)
    let full = crate::mirsem::function_fully_faithful_witness(&func)
        .expect("the leaf is fully faithful (no safety VC — a widening cast raises none)");
    assert!(full.is_modulo_3());
}

#[test]
fn field_read_cast_leaf_truncating_cast_declines() {
    // `_0 = _2 as u32` where `_2 : u32` and the dest is ALSO u32 is a no-op —
    // use a genuinely NARROWING dest (u16) to exercise the truncating decline.
    let u16t = trust_types::Ty::Int { width: 16, signed: false };
    let func = field_read_cast_leaf_func(false, u16t);
    assert!(
        function_adequacy_witness(&func).is_none(),
        "a TRUNCATING cast (u32 -> u16) must NOT be modeled as identity — the \
         leaf must fail closed, never a false certificate"
    );
    assert!(crate::mirsem::function_fully_faithful_witness(&func).is_none());
}

#[test]
fn field_read_cast_leaf_mut_self_declines() {
    let u64t = trust_types::Ty::Int { width: 64, signed: false };
    let func = field_read_cast_leaf_func(true, u64t);
    assert!(
        function_adequacy_witness(&func).is_none(),
        "a field read through `&mut self` must NOT certify this increment \
         (the recognizer is scoped to shared references)"
    );
    assert!(crate::mirsem::function_fully_faithful_witness(&func).is_none());
}

