/// The comparison-guarded arithmetic return `if b != 0 { a / b } else { 0 }` —
/// `guarded_div`'s shape: guard `Ne(b,0)`, then `Div(a,b)`, else `Const 0`.
fn cf_div_return() -> SemCfReturn {
    SemCfReturn {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Ne,
            a: SemOperand::Var(1),
            b: SemOperand::Const(0),
        }),
        then_rv: SemRvalue::Bin(SemBinOp::Div, SemOperand::Var(0), SemOperand::Var(1)),
        else_rv: SemRvalue::Use(SemOperand::Const(0)),
    }
}

/// The comparison-guarded subtraction return `if a >= b { a - b } else { 0 }` —
/// `guarded_sub`'s shape: guard `Ge(a,b)`, then `Sub(a,b)`, else `Const 0`.
fn cf_sub_return() -> SemCfReturn {
    SemCfReturn {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Ge,
            a: SemOperand::Var(0),
            b: SemOperand::Var(1),
        }),
        then_rv: SemRvalue::Bin(SemBinOp::Sub, SemOperand::Var(0), SemOperand::Var(1)),
        else_rv: SemRvalue::Use(SemOperand::Const(0)),
    }
}

#[test]
fn lemma_1c_cf_bounds_guarded_index_return_proven_modulo_3() {
    // The bounds-guarded index return shape `if i < len { s[i] } else { 0 }`,
    // modeled at the SCALAR conditional level: guard `Lt(i, len)`, then a modeled
    // scalar (here a param standing for the in-bounds element), else `Const 0`.
    // The conditional eval IS the if-then-else over the comparison — proven by
    // reflexivity (eval_ite ι-reduces to the Bool.rec dispatch).
    let r = SemCfReturn {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(1),
            b: SemOperand::Var(2),
        }),
        then_rv: SemRvalue::Use(SemOperand::Var(0)),
        else_rv: SemRvalue::Use(SemOperand::Const(0)),
    };
    assert_eq!(check_cf_return_adequacy(&r), AdequacyVerdict::ProvenModulo3);
}

/// The REAL array-index guarded return `if i < s.len() { s[i] } else { 0 }`, modeled
/// at the FULL element level via the additive `Operand.Index` / `Operand.Len`:
/// guard `Lt(Var i, Len(Var s))`, then `Use(Index (Var s) (Var i))`, else `Const 0`.
/// `s` is param 0, `i` param 1.
fn cf_index_return() -> SemCfReturn {
    SemCfReturn {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(1),
            b: SemOperand::Len(Box::new(SemOperand::Var(0))),
        }),
        then_rv: SemRvalue::Use(SemOperand::Index(
            Box::new(SemOperand::Var(0)),
            Box::new(SemOperand::Var(1)),
        )),
        else_rv: SemRvalue::Use(SemOperand::Const(0)),
    }
}

/// ADDITIVE INDEX EXTENSION (positive): the operand/rvalue/branch adequacy of the
/// array-index guarded return `if i < s.len() { s[i] } else { 0 }` all prove modulo
/// 3 over the additive `Operand.Index`/`Operand.Len` constructors + the uninterpreted
/// `idx_elem`/`slice_len` opaques. `eval (Index s i)` ι-reduces to `idx_elem (eval e
/// s) (eval e i)`, byte-identical to the LIVE `ground_int(Select(s,i))`.
#[test]
fn index_arm_operand_rvalue_branch_adequacy_proven_modulo_3() {
    // 1A: the `Index` operand and the `Len` operand each prove modulo 3.
    let index_op =
        SemOperand::Index(Box::new(SemOperand::Var(0)), Box::new(SemOperand::Var(1)));
    assert_eq!(
        check_operand_adequacy(&index_op),
        AdequacyVerdict::ProvenModulo3,
        "the Index operand `s[i]` must prove modulo 3 (eval ≡ idx_elem)"
    );
    let len_op = SemOperand::Len(Box::new(SemOperand::Var(0)));
    assert_eq!(
        check_operand_adequacy(&len_op),
        AdequacyVerdict::ProvenModulo3,
        "the Len operand `s.len()` must prove modulo 3 (eval ≡ slice_len)"
    );
    // 1B: the `Use(Index …)` rvalue proves modulo 3.
    assert_eq!(
        check_rvalue_adequacy(&SemRvalue::Use(index_op)),
        AdequacyVerdict::ProvenModulo3,
        "the Use(Index …) rvalue must prove modulo 3"
    );
    // 6B: the whole index-arm guarded return's BRANCH REFINEMENT proves modulo 3.
    assert_eq!(
        check_branch_refinement(&cf_index_return()),
        RefinementVerdict::ProvenModulo3,
        "the array-index guarded return's branch refinement must prove modulo 3"
    );
}

/// FAIL-CLOSED (a WRONG index branch claim): claiming the index guarded return's RHS
/// is the UNCONDITIONAL element `eval_rvalue E (Use(Index s i))` (dropping the guard,
/// as if `s[i]` were always returned even when `i ≥ s.len()`) MUST be kernel-rejected
/// — `denote_substitutedB E c t f` is the if-then-else, NOT the bare then-arm element.
/// This is the index analogue of the wrong-branch / wrong-neg-arm fail-closed tests.
#[test]
fn wrong_index_branch_rhs_fails_closed() {
    let r = cf_index_return();
    let indices = r.var_indices();
    let n = indices.len();
    let env_e =
        grounding_env_expr(&indices, &|i| Expr::bvar(u32::try_from(n - 1 - i).unwrap_or(0)));
    // The WRONG RHS: the unconditional THEN element `eval_rvalue E (Use(Index s i))`,
    // i.e. `idx_elem …` with NO `Bool.rec` guard dispatch — a claim that the function
    // always returns `s[i]` even on the ¬(i < len) path.
    let wrong_rhs = Expr::apps(cst(MIRSEM_EVAL_RVALUE), [env_e, r.then_rv.to_rvalue_expr()]);
    let verdict = check_branch_refinement_inner(&r, Some(&wrong_rhs));
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a WRONG index branch RHS (= unconditional s[i], dropping the guard) MUST be \
         kernel-rejected, got {verdict:?}"
    );
}

// ---- NESTED / multi-way guarded return (refinementBNested) ----------------

/// The `sign` nested return `if x>0 {1} else if x<0 {-1} else {0}` as a recursive
/// `SemBranchTree`: an OUTER `Node(x>0, Leaf(1), <inner>)` whose else is the inner
/// `Node(x<0, Leaf(-1), Leaf(0))`. `x` is param 0.
fn sign_branch_tree() -> SemBranchTree {
    let leaf = |k: i128| SemBranchTree::Leaf(SemRvalue::Use(SemOperand::Const(k)));
    SemBranchTree::Node(
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Gt,
            a: SemOperand::Var(0),
            b: SemOperand::Const(0),
        }),
        Box::new(leaf(1)),
        Box::new(SemBranchTree::Node(
            SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Lt,
                a: SemOperand::Var(0),
                b: SemOperand::Const(0),
            }),
            Box::new(leaf(-1)),
            Box::new(leaf(0)),
        )),
    )
}

/// POSITIVE: the `sign` nested return's NESTED-BRANCH REFINEMENT proves modulo 3 —
/// the nested `iteI`-tree denotation IS the term the LIVE `ground_int` grounds the
/// NESTED `Ite(x>0, 1, Ite(x<0, -1, 0))` to. This is the multi-way generalization of
/// `refinementB`, kernel-verified.
#[test]
fn nested_sign_branch_refinement_proven_modulo_3() {
    let t = sign_branch_tree();
    assert!(t.is_nested(), "the sign tree must be genuinely nested");
    assert_eq!(
        check_nested_branch_refinement(&t),
        RefinementVerdict::ProvenModulo3,
        "the nested `sign` return's branch refinement must prove modulo 3"
    );
    // The nested-branch anchor (`iteI` + `denote_substitutedBNested`) rests on ⊆ 3.
    assert_eq!(
        pin_nested_branch_refinement_anchor(),
        AnchorVerdict::Modulo3,
        "the nested-branch anchor must rest on ⊆ the 3 foundational axioms (no 4th)"
    );
}

/// FAIL-CLOSED (a WRONG nested-arm claim): claiming the `sign` return's RHS is the
/// nested Ite with the INNER else arm SWAPPED to `1` (i.e. `Ite(x>0,1,Ite(x<0,-1,1))`
/// — wrongly returning `1` on the `x==0` path) MUST be kernel-rejected: that term is
/// NOT the live-grounded denotation of the real `sign` tree.
#[test]
fn wrong_nested_arm_rhs_fails_closed() {
    let t = sign_branch_tree();
    let indices = t.var_indices();
    // The WRONG grounded RHS: the SAME nested tree but with the innermost ELSE leaf
    // (the `x==0` value `0`) replaced by `1` — i.e. wrongly returning `1` on the
    // `x==0` path. Grounding it through the SAME live grounder gives a well-formed
    // Int term that is NOT the real `sign` denotation.
    let leaf = |k: i128| SemBranchTree::Leaf(SemRvalue::Use(SemOperand::Const(k)));
    let wrong_tree = SemBranchTree::Node(
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Gt,
            a: SemOperand::Var(0),
            b: SemOperand::Const(0),
        }),
        Box::new(leaf(1)),
        Box::new(SemBranchTree::Node(
            SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Lt,
                a: SemOperand::Var(0),
                b: SemOperand::Const(0),
            }),
            Box::new(leaf(-1)),
            Box::new(leaf(1)), // WRONG: should be 0
        )),
    );
    let wrong_rhs = live_ground_int(&wrong_tree.to_formula(), &indices)
        .expect("the wrong nested Ite grounds (it is a well-formed Int term)");
    let verdict = check_nested_branch_refinement_inner(&t, Some(&wrong_rhs));
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a WRONG nested-arm RHS (x==0 ↦ 1, not 0) MUST be kernel-rejected, got {verdict:?}"
    );
}

/// The REAL `sign` MIR dump (`fixtures/real-spec-corpus/sign.json`) extracts to the
/// nested `SemBranchTree`, its nested-branch refinement proves modulo 3, AND the
/// whole function is FULLY FAITHFUL (the nested `Ite` return is kernel-adequate to
/// MirSem; `sign` emits no safety VC, so it is vacuously safe).
#[test]
fn real_sign_dump_is_nested_and_fully_faithful_modulo_3() {
    let dir =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/real-spec-corpus");
    let bytes = match std::fs::read(dir.join("sign.json")) {
        Ok(b) => b,
        Err(_) => return, // fixture not present
    };
    let func: trust_types::VerifiableFunction =
        serde_json::from_slice(&bytes).expect("parse sign.json");
    // The extractor recovers the GENUINELY-nested tree from the real MIR.
    let nb = nested_branch_refinement_witness(&func)
        .expect("the real sign MIR must extract a nested-branch witness");
    assert!(nb.tree.is_nested(), "the extracted sign tree must be nested");
    assert!(nb.is_modulo_3(), "the nested-branch refinement must be modulo 3");
    // The reflected formula is the NESTED Ite (outer x>0, inner x<0).
    assert!(
        matches!(&nb.tree.to_formula(), trust_types::Formula::Ite(_, _, e)
            if matches!(**e, trust_types::Formula::Ite(..))),
        "sign must reflect to a NESTED Ite (else arm is itself an Ite)"
    );
    // WHOLE-FUNCTION: fully faithful via the nested-branch return certificate.
    let cert = function_fully_faithful_witness(&func)
        .expect("the real sign function must be fully faithful via the nested branch");
    assert!(cert.is_modulo_3(), "the full-faithfulness certificate must be modulo 3");
    assert!(
        matches!(cert.contract.ret, ReturnCertificate::NestedControlFlow(_)),
        "sign's return certificate must be the NestedControlFlow variant"
    );
}

fn load_clamp_func() -> Option<trust_types::VerifiableFunction> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("fixtures/stdlib-leaf-cmp-2026-07-16/controls/ctl_clamp_i32.json");
    serde_json::from_slice(&std::fs::read(path).ok()?).ok()
}

fn clamp_branch_tree() -> SemBranchTree {
    let value = |index| SemBranchTree::Leaf(SemRvalue::Use(SemOperand::Var(index)));
    SemBranchTree::Node(
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(0),
            b: SemOperand::Var(1),
        }),
        Box::new(value(1)),
        Box::new(SemBranchTree::Node(
            SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Gt,
                a: SemOperand::Var(0),
                b: SemOperand::Var(2),
            }),
            Box::new(value(2)),
            Box::new(value(0)),
        )),
    )
}

#[test]
fn real_clamp_nested_convergence_is_fully_faithful_modulo_3() {
    let Some(function) = load_clamp_func() else { return };
    let witness = nested_branch_refinement_witness(&function)
        .expect("the committed clamp must expose its nested select");
    assert_eq!(witness.tree, clamp_branch_tree());
    assert!(witness.is_modulo_3());
    let certificate = function_fully_faithful_witness(&function)
        .expect("the nested clamp must carry a whole-function witness");
    assert!(certificate.is_modulo_3());
    assert!(matches!(certificate.contract.ret, ReturnCertificate::NestedControlFlow(_)));
}

#[test]
fn nested_clamp_branch_refinement_proves_modulo_3() {
    assert_eq!(
        check_nested_branch_refinement(&clamp_branch_tree()),
        RefinementVerdict::ProvenModulo3
    );
}

