#[test]
fn nested_clamp_declines_unmodeled_leaf_and_noncompare_guard() {
    use trust_types::{BinOp, Operand, Place, Rvalue, Statement};

    let Some(mut bad_leaf) = load_clamp_func() else { return };
    for statement in bad_leaf.body.blocks.iter_mut().flat_map(|block| &mut block.stmts) {
        if let Statement::Assign { place, rvalue, .. } = statement
            && place.local == 4
            && matches!(rvalue, Rvalue::Use(Operand::Copy(source)) if source.local == 1)
        {
            *rvalue = Rvalue::Use(Operand::Copy(Place::local(99)));
        }
    }
    assert!(sem_nested_branch_shape_of(&bad_leaf).is_none());
    assert!(nested_branch_refinement_witness(&bad_leaf).is_none());

    let Some(mut bad_guard) = load_clamp_func() else { return };
    for statement in bad_guard.body.blocks.iter_mut().flat_map(|block| &mut block.stmts) {
        if let Statement::Assign { place, rvalue, .. } = statement
            && place.local == 7
            && let Rvalue::BinaryOp(_, left, right) = rvalue
        {
            *rvalue = Rvalue::BinaryOp(BinOp::Add, left.clone(), right.clone());
        }
    }
    assert!(sem_nested_branch_shape_of(&bad_guard).is_none());
    assert!(nested_branch_refinement_witness(&bad_guard).is_none());
}

#[test]
fn nested_clamp_declines_leaf_to_leaf_overwrite() {
    use trust_types::{BlockId, Terminator};

    let Some(mut function) = load_clamp_func() else { return };
    let first_leaf = function
        .body
        .blocks
        .iter_mut()
        .find(|block| block.id == BlockId(2))
        .expect("clamp bb2");
    // The original bb2 writes the high-bound leaf and goes directly to
    // the inner convergence merge. Route it through bb3, a distinct real
    // leaf that overwrites the same convergence local with `x`.
    first_leaf.terminator = Terminator::Goto(BlockId(3));
    assert!(sem_nested_branch_shape_of(&function).is_none());
    assert!(nested_branch_refinement_witness(&function).is_none());
    assert!(function_fully_faithful_witness(&function).is_none());
}

#[test]
fn nested_clamp_declines_pass_through_before_leaf_write() {
    use trust_types::{BlockId, Terminator};

    let Some(mut function) = load_clamp_func() else { return };
    let mut early_pass = function
        .body
        .blocks
        .iter()
        .find(|block| block.id == BlockId(5))
        .expect("clamp convergence pass")
        .clone();
    early_pass.id = BlockId(8);
    early_pass.terminator = Terminator::Goto(BlockId(2));
    function.body.blocks.push(early_pass);

    let inner_decision = function
        .body
        .blocks
        .iter_mut()
        .find(|block| block.id == BlockId(1))
        .expect("clamp inner decision");
    let Terminator::SwitchInt { otherwise, .. } = &mut inner_decision.terminator else {
        panic!("clamp bb1 must switch")
    };
    *otherwise = BlockId(8);

    let high_leaf = function
        .body
        .blocks
        .iter_mut()
        .find(|block| block.id == BlockId(2))
        .expect("clamp high leaf");
    high_leaf.terminator = Terminator::Goto(BlockId(6));

    // Runtime copies `_4` into `_5` before bb2 initializes `_4`, then
    // returns the stale `_5`. A traversal that ignores pre-leaf statements
    // would incorrectly model the later bb2 value.
    assert!(sem_nested_branch_shape_of(&function).is_none());
    assert!(nested_branch_refinement_witness(&function).is_none());
    assert!(function_fully_faithful_witness(&function).is_none());
}

// ---- Trust: BRANCHY call-arm sub-axis (SemBranchTree::CallLeaf) -----------

/// Hand-built `fn pick(c: i32, a: i32, b: i32) -> i32 { if c > 0 { helper1(a) }
/// else { helper2(b) } }` — the ALL-CALL fixture shape (mirrors
/// `fixtures/branch-call-corpus/pick.json`, hand-built here for a fast,
/// dependency-free unit test — the DUAL representation cross-checks the
/// JSON fixture's structure).
fn pick_call_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let i32ty = || Ty::Int { width: 32, signed: false };
    let p = |l: usize| Place::local(l);
    VerifiableFunction {
        name: "pick".into(),
        def_path: "crate::pick".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i32ty(), name: None },
                LocalDecl { index: 1, ty: i32ty(), name: Some("c".into()) },
                LocalDecl { index: 2, ty: i32ty(), name: Some("a".into()) },
                LocalDecl { index: 3, ty: i32ty(), name: Some("b".into()) },
                LocalDecl { index: 4, ty: Ty::Bool, name: None },
            ],
            blocks: vec![
                // bb0: _4 := Gt(c, 0); SwitchInt(_4) { 0 → bb2(else), otherwise → bb1(then) }
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: p(4),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Gt,
                            Operand::Copy(p(1)),
                            Operand::Constant(ConstValue::Uint(0, 32)),
                        ),
                        span: Default::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Move(p(4)),
                        targets: vec![(0, BlockId(2))],
                        otherwise: BlockId(1),
                        exhaustive_enum_unreachable: false,
                        span: Default::default(),
                    },
                },
                // bb1 (then): _0 := helper1(a) -> bb3
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        func: "helper1".into(),
                        args: vec![Operand::Copy(p(2))],
                        dest: p(0),
                        target: Some(BlockId(3)),
                        span: Default::default(),
                        atomic: None,
                        is_unsafe_sig: false,
                        is_foreign: false,
                    },
                },
                // bb2 (else): _0 := helper2(b) -> bb3
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        func: "helper2".into(),
                        args: vec![Operand::Copy(p(3))],
                        dest: p(0),
                        target: Some(BlockId(3)),
                        span: Default::default(),
                        atomic: None,
                        is_unsafe_sig: false,
                        is_foreign: false,
                    },
                },
                BasicBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 3,
            return_ty: i32ty(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

/// A trivial arg_count=1, no-requires `CalleeFact` — the `identity`-shaped
/// certified callee `helper1`/`helper2` model without needing a full
/// separately-certified `VerifiableFunction` (its fields are all `pub`, so
/// hand-constructing it directly is sound: it carries EXACTLY what a real
/// `CalleeFact::of_certified` would for `fn helper(x: i32) -> i32 { x }`).
fn identity_callee_fact() -> CalleeFact {
    CalleeFact { arg_count: 1, requires: Some(vec![]), param_names: vec![Some("x".into())] }
}

#[test]
fn sem_branch_call_shape_of_recognizes_the_all_call_pick_shape() {
    let func = pick_call_func();
    let mut registry = std::collections::BTreeMap::new();
    registry.insert("helper1".to_string(), identity_callee_fact());
    registry.insert("helper2".to_string(), identity_callee_fact());
    let tree = sem_branch_call_shape_of(&func, &registry)
        .expect("the all-call pick shape must be recognized");
    assert!(tree.contains_call_leaf());
    let SemBranchTree::Node(cond, then_, else_) = &tree else { panic!("must be a Node") };
    let SemCondTree::Leaf(c) = cond else { panic!("bare comparison guard") };
    assert_eq!(c.op, SemCmpOp::Gt);
    let SemBranchTree::CallLeaf(then_call) = then_.as_ref() else {
        panic!("then arm must be a CallLeaf")
    };
    assert_eq!(then_call.callee, "helper1");
    assert_eq!(then_call.args, vec![SemOperand::Var(1)]); // `a` is param index 1.
    let SemBranchTree::CallLeaf(else_call) = else_.as_ref() else {
        panic!("else arm must be a CallLeaf")
    };
    assert_eq!(else_call.callee, "helper2");
    assert_eq!(else_call.args, vec![SemOperand::Var(2)]); // `b` is param index 2.

    // The MirSem-certifying / plain-shape-only paths NEVER see a call-arm —
    // `callees: None` reproduces the pre-increment behavior byte-for-byte (0
    // assign-arms ⇒ decline, exactly as before this increment existed).
    assert!(sem_cf_return_shape_of(&func).is_none());
    assert!(sem_nested_branch_shape_of(&func).is_none());
}

#[test]
fn sem_branch_call_shape_of_declines_an_uncertified_callee_arm() {
    // NEGATIVE CONTROL: one arm's callee (`helper1`) is missing from the
    // registry — the WHOLE branch must decline (never silently drop the
    // uncertified arm and certify on the remaining one alone).
    let func = pick_call_func();
    let mut registry = std::collections::BTreeMap::new();
    registry.insert("helper2".to_string(), identity_callee_fact());
    assert!(
        sem_branch_call_shape_of(&func, &registry).is_none(),
        "an uncertified callee in one arm must decline the WHOLE branch"
    );
}

#[test]
fn sem_branch_call_shape_declines_assign_arm_overwritten_by_another_arm() {
    use trust_types::{BasicBlock, BlockId, Operand, Place, Rvalue, Statement, Terminator};

    let mut function = pick_call_func();
    let value_arm = function
        .body
        .blocks
        .iter_mut()
        .find(|block| block.id == BlockId(2))
        .expect("pick else block");
    value_arm.stmts = vec![Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Use(Operand::Copy(Place::local(3))),
        span: Default::default(),
    }];
    value_arm.terminator = Terminator::Goto(BlockId(3));

    function.body.blocks.push(BasicBlock {
        id: BlockId(4),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
            span: Default::default(),
        }],
        // Adversarial overwrite: the tree walker sees bb4 as the value
        // leaf, but execution continues through bb2 and replaces `_0`.
        terminator: Terminator::Goto(BlockId(2)),
    });
    let entry = function
        .body
        .blocks
        .iter_mut()
        .find(|block| block.id == BlockId(0))
        .expect("pick entry");
    let Terminator::SwitchInt { targets, .. } = &mut entry.terminator else {
        panic!("pick entry must switch")
    };
    targets[0].1 = BlockId(4);

    let mut registry = std::collections::BTreeMap::new();
    registry.insert("helper1".to_string(), identity_callee_fact());
    assert!(
        sem_branch_call_shape_of(&function, &registry).is_none(),
        "an assign leaf that flows through another assign leaf must decline"
    );
}

#[test]
fn sem_branch_call_shape_of_declines_an_unsafe_callee_arm() {
    use trust_types::Terminator;

    let mut func = pick_call_func();
    let Terminator::Call { is_unsafe_sig, .. } = &mut func.body.blocks[1].terminator else {
        panic!("bb1 must be a Call terminator")
    };
    *is_unsafe_sig = true;
    let mut registry = std::collections::BTreeMap::new();
    registry.insert("helper1".to_string(), identity_callee_fact());
    registry.insert("helper2".to_string(), identity_callee_fact());
    assert!(
        sem_branch_call_shape_of(&func, &registry).is_none(),
        "an unsafe-signature Call must never enter the certified branch-call lane"
    );
}

#[test]
fn sem_branch_call_shape_of_declines_a_non_scalar_arm_arg() {
    // NEGATIVE CONTROL: one arm's actual arg is an INDIRECT local (`_5 :=
    // Use(Copy(_2)); helper1(Move(_5))`), outside the modeled Var|Const
    // operand fragment (the "arg-scalar check" the mission asks to reuse) —
    // must decline the WHOLE branch.
    use trust_types::{LocalDecl, Operand, Place, Rvalue, Statement, Terminator, Ty};
    let mut func = pick_call_func();
    func.body.locals.push(LocalDecl {
        index: 5,
        ty: Ty::Int { width: 32, signed: false },
        name: None,
    });
    func.body.blocks[1].stmts.push(Statement::Assign {
        place: Place::local(5),
        rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
        span: Default::default(),
    });
    let Terminator::Call { args, .. } = &mut func.body.blocks[1].terminator else {
        panic!("bb1 must still be the Call terminator");
    };
    args[0] = Operand::Move(Place::local(5));
    let mut registry = std::collections::BTreeMap::new();
    registry.insert("helper1".to_string(), identity_callee_fact());
    registry.insert("helper2".to_string(), identity_callee_fact());
    assert!(
        sem_branch_call_shape_of(&func, &registry).is_none(),
        "an out-of-fragment (indirect-local) arm arg must decline the WHOLE branch"
    );
}

/// The ADDITIVE index extension rests on ⊆ the 3 foundational axioms — the `idx_elem`
/// and `slice_len` OPAQUE constants are NOT axioms, so the index operand/rvalue/branch
/// adequacy carry NO 4th axiom. Confirms the soundness budget is unchanged.
#[test]
fn index_extension_rests_on_three_axioms_no_fourth() {
    // The branch refinement theorem over the index return — register and audit.
    assert_eq!(
        check_branch_refinement(&cf_index_return()),
        RefinementVerdict::ProvenModulo3,
        "index branch refinement modulo 3 (axiom_deps ⊆ the 3)"
    );
    // The anchor (which now registers idx_elem + slice_len opaques + the extended
    // Operand inductive/eval) still pins modulo 3 — no 4th axiom from the opaques.
    assert_eq!(
        pin_mirsem_anchor(),
        AnchorVerdict::Modulo3,
        "the index-extended MirSem anchor (idx_elem/slice_len opaques) rests on ⊆ the 3 axioms"
    );
}

/// SOUNDNESS / FAIL-CLOSED (the BOUNDS VC is NOT covered by the guard): an UNGUARDED
/// index `fn f(s: &[u32], i: usize) -> u32 { s[i] }` (no `i < s.len()` guard) emits a
/// BOUNDS VC that is genuinely satisfiable (`i` may be ≥ `s.len()`), so it MUST NOT be
/// counted fully faithful — the index extension never falsely discharges an unguarded
/// bounds obligation. (The closure rests on the bounds VC discharged FROM the guard,
/// not on the `idx_elem` element model.)
#[test]
fn unguarded_index_bounds_vc_not_discharged_fails_closed() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Projection, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u32t = || Ty::Int { width: 32, signed: false };
    let usz = || Ty::Int { width: 64, signed: false };
    let slice =
        || Ty::Ref { mutable: false, inner: Box::new(Ty::Slice { elem: Box::new(u32t()) }) };
    // `fn f(s, i) -> u32 { s[i] }` — NO guard, the bounds VC `i < s.len()` is NOT
    // implied by anything, so it stays satisfiable (a real OOB).
    let func = VerifiableFunction {
        name: "unguarded_idx".into(),
        def_path: "crate::unguarded_idx".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u32t(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: slice(), name: Some("s".into()) },
                LocalDecl { index: 2, ty: usz(), name: Some("i".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Copy(Place {
                        local: 1,
                        projections: vec![Projection::Deref, Projection::Index(2)],
                    })),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: u32t(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    assert!(
        function_fully_faithful_witness(&func).is_none(),
        "an UNGUARDED index (bounds VC NOT covered by a guard) MUST fail-closed — never \
         counted fully faithful"
    );
}

