#[test]
fn wrong_branch_cf_return_claim_fails_closed() {
    // CLAIM: the guarded return `if b!=0 { a/b } else { 0 }` denotes simply
    // `eval_rvalue e else` (the ELSE branch, IGNORING the condition). FALSE — the
    // true value branches on `eval_cond e c`; the reflexivity proof of the
    // wrong (unconditional else) claim does not type-check on a symbolic env.
    let r = cf_div_return();
    let e_ref = Expr::bvar(0);
    let wrong_rhs =
        Expr::apps(cst(MIRSEM_EVAL_RVALUE), [e_ref.clone(), r.else_rv.to_rvalue_expr()]);
    let verdict = check_cf_return_adequacy_inner(&r, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong-branch cf claim (= unconditional else) MUST be kernel-rejected, got {verdict:?}"
    );
}

