    let wrong_rhs =
        Expr::apps(cst(MIRSEM_EVAL_RVALUE), [e_ref.clone(), r.then_rv.to_rvalue_expr()]);
    let verdict = check_cf_return_adequacy_inner(&r, Some(&wrong_rhs));
