/// The `abs` guarded return `if x < 0 { -x } else { x }`, with the NEG arm modeled
/// as `Bin Sub (Const 0) (Var 0)` (the `-x ≡ 0 - x` identity). This is the witness
/// `arm_value_rvalue_for` now produces for a `UnaryOp(Neg)` arm.
fn cf_abs_return() -> SemCfReturn {
    SemCfReturn {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(0),
            b: SemOperand::Const(0),
        }),
        then_rv: SemRvalue::Bin(SemBinOp::Sub, SemOperand::Const(0), SemOperand::Var(0)),
        else_rv: SemRvalue::Use(SemOperand::Var(0)),
    }
}

#[test]
fn refinement_b_neg_arm_proven_modulo_3() {
    // POSITIVE (the new NEG-arm shape): `abs`'s `if x<0 { -x } else { x }`, whose
    // `then` arm is the unary negation `-x` modeled as `0 - x`. Its branch refinement
    // (`denote_substitutedB E c t f = ground_int(Ite)`) proves modulo 3 — the modeled
    // `Bin Sub (Const 0) x` denotes EXACTLY `Int.sub (Int.ofNat 0) x`, the term the
    // live grounder grounds a `Formula::Neg(x)` return arm to.
    let r = cf_abs_return();
    assert_eq!(
        check_branch_refinement(&r),
        RefinementVerdict::ProvenModulo3,
        "the NEG-arm (abs) branch refinement must prove modulo 3"
    );
    // …and it rests on ⊆ the 3 foundational axioms (no 4th axiom from the Neg model).
    let mut env = mirsem_branch_refinement_env().expect("env");
    let indices = r.var_indices();
    let stmt = branch_refinement_statement(&r, None).expect("statement grounds");
    let proof = branch_refinement_proof(&r).expect("proof grounds");
    let _ = indices;
    env.add_decl(Declaration::Theorem {
        name: Name::from_string("Trust.MirSem.refinementB.abs_test"),
        level_params: vec![],
        type_: stmt,
        value: proof,
    })
    .expect("abs branch refinement adds");
    let deps = env
        .axiom_deps(&Name::from_string("Trust.MirSem.refinementB.abs_test"))
        .expect("decl present");
    assert!(deps.is_empty(), "the NEG-arm refinement must rest on ⊆ 3 axioms, got {deps:?}");
}

#[test]
fn refinement_b_neg_arm_wrong_shape_fails_closed() {
    // FAIL-CLOSED (the new NEG-arm shape): claiming a WRONG branch RHS for the abs
    // return — `denote_substitutedB E c t f = eval_rvalue E then` (the UNCONDITIONAL
    // negation `-x`, ignoring the guard, so it is wrong on the `x ≥ 0` else arm) —
    // must NOT type-check. The NEG-arm branch refinement is fail-closed too: a wrong
    // claim is kernel-rejected, never a false connection.
    let r = cf_abs_return();
    let indices = r.var_indices();
    let n = indices.len();
    let env_e =
        grounding_env_expr(&indices, &|i| Expr::bvar(u32::try_from(n - 1 - i).unwrap_or(0)));
    let wrong_rhs = Expr::apps(cst(MIRSEM_EVAL_RVALUE), [env_e, r.then_rv.to_rvalue_expr()]);
    let verdict = check_branch_refinement_inner(&r, Some(&wrong_rhs));
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a wrong NEG-arm branch RHS (= unconditional -x) MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn arm_value_rvalue_for_models_neg_arm_and_index_arm() {
    // `arm_value_rvalue_for` models a `UnaryOp(Neg, x)` arm as `Bin Sub (Const 0) x`
    // (the `-x ≡ 0 - x` identity), and now ALSO models an array-index arm `s[i]` as
    // `Use(Index (Var slice) (Var idx))` via the additive `Operand.Index` constructor.
    use trust_types::{
        BasicBlock, BlockId, Operand, Place, Projection, Rvalue, Statement, Terminator, UnOp,
    };
    let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    // NEG arm: `_0 := -x` (x is local 1).
    let neg_arm = BasicBlock {
        id: BlockId(0),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::UnaryOp(UnOp::Neg, Operand::Copy(Place::local(1))),
            span: Default::default(),
        }],
        terminator: Terminator::Goto(BlockId(9)),
    };
    let body = trust_types::VerifiableBody {
        locals: vec![
            trust_types::LocalDecl {
                index: 0,
                ty: trust_types::Ty::Int { width: 32, signed: true },
                name: None,
            },
            trust_types::LocalDecl {
                index: 1,
                ty: trust_types::Ty::Int { width: 32, signed: true },
                name: Some("x".into()),
            },
        ],
        blocks: vec![neg_arm.clone()],
        arg_count: 1,
        return_ty: trust_types::Ty::Int { width: 32, signed: true },
    };
    let modeled = arm_value_rvalue_for(&body, &neg_arm, 0, &param_index)
        .expect("a Neg arm is now modeled");
    assert_eq!(
        modeled,
        SemRvalue::Bin(SemBinOp::Sub, SemOperand::Const(0), SemOperand::Var(0)),
        "the Neg arm must model as 0 - x"
    );
    // INDEX arm: `_0 := s[i]` where `s` (local 1) is param 0 and `i` (local 2) is
    // param 1 — now MODELED as `Use(Index (Var 0) (Var 1))`.
    let idx_param_index = |local: usize| -> Option<u64> {
        match local {
            1 => Some(0),
            2 => Some(1),
            _ => None,
        }
    };
    let idx_arm = BasicBlock {
        id: BlockId(1),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Copy(Place {
                local: 1,
                projections: vec![Projection::Deref, Projection::Index(2)],
            })),
            span: Default::default(),
        }],
        terminator: Terminator::Goto(BlockId(9)),
    };
    let body2 = trust_types::VerifiableBody {
        locals: vec![
            trust_types::LocalDecl {
                index: 0,
                ty: trust_types::Ty::Int { width: 32, signed: false },
                name: None,
            },
            trust_types::LocalDecl {
                index: 1,
                ty: trust_types::Ty::Ref {
                    mutable: false,
                    inner: Box::new(trust_types::Ty::Slice {
                        elem: Box::new(trust_types::Ty::Int { width: 32, signed: false }),
                    }),
                },
                name: Some("s".into()),
            },
            trust_types::LocalDecl {
                index: 2,
                ty: trust_types::Ty::Int { width: 64, signed: false },
                name: Some("i".into()),
            },
        ],
        blocks: vec![idx_arm.clone()],
        arg_count: 2,
        return_ty: trust_types::Ty::Int { width: 32, signed: false },
    };
    assert_eq!(
        arm_value_rvalue_for(&body2, &idx_arm, 0, &idx_param_index),
        Some(SemRvalue::Use(SemOperand::Index(
            Box::new(SemOperand::Var(0)),
            Box::new(SemOperand::Var(1)),
        ))),
        "an array-INDEX arm `s[i]` over parameter slice + index is now modeled as Index"
    );
    // SOUNDNESS (fail-closed): an index arm whose SLICE is NOT a parameter (a temp
    // with no traceable definition) stays unmodeled — no false Index certificate.
    assert!(
        arm_value_rvalue_for(&body2, &idx_arm, 0, &param_index).is_none(),
        "an array-INDEX arm whose index local is not a parameter/const must fail-closed"
    );

    // SOUNDNESS: a literal index temp is usable only when its sole definition
    // executes before the projection. A block-table/same-block dominance check
    // without statement ordering would accept the first body below even though
    // `_2` is defined only after `_0 := s[_2]`.
    let slice_only_param = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let index_use = Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Use(Operand::Copy(Place {
            local: 1,
            projections: vec![Projection::Deref, Projection::Index(2)],
        })),
        span: Default::default(),
    };
    let index_definition = Statement::Assign {
        place: Place::local(2),
        rvalue: Rvalue::Use(Operand::Constant(trust_types::ConstValue::Uint(3, 64))),
        span: Default::default(),
    };
    let mut ordered_body = body2.clone();
    ordered_body.arg_count = 1;
    ordered_body.blocks = vec![BasicBlock {
        id: BlockId(0),
        stmts: vec![index_use.clone(), index_definition.clone()],
        terminator: Terminator::Return,
    }];
    assert!(
        arm_value_rvalue_for(&ordered_body, &ordered_body.blocks[0], 0, &slice_only_param,)
            .is_none(),
        "an index definition after its same-block use must fail closed"
    );
    ordered_body.blocks[0].stmts = vec![index_definition, index_use];
    assert_eq!(
        arm_value_rvalue_for(&ordered_body, &ordered_body.blocks[0], 0, &slice_only_param,),
        Some(SemRvalue::Use(SemOperand::Index(
            Box::new(SemOperand::Var(0)),
            Box::new(SemOperand::Const(3)),
        ))),
        "a sole literal index definition before the projection remains modeled"
    );
}

#[test]
fn checked_field_resolution_requires_definition_before_use() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Projection, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let int = || Ty::Int { width: 32, signed: false };
    let result_use = Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Use(Operand::Copy(Place {
            local: 3,
            projections: vec![Projection::Field(0)],
        })),
        span: Default::default(),
    };
    let checked_definition = Statement::Assign {
        place: Place::local(3),
        rvalue: Rvalue::CheckedBinaryOp(
            BinOp::Add,
            Operand::Copy(Place::local(1)),
            Operand::Copy(Place::local(2)),
        ),
        span: Default::default(),
    };
    let mut body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: int(), name: Some("_0".into()) },
            LocalDecl { index: 1, ty: int(), name: Some("a".into()) },
            LocalDecl { index: 2, ty: int(), name: Some("b".into()) },
            LocalDecl { index: 3, ty: Ty::Tuple(vec![int(), Ty::Bool]), name: None },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![result_use.clone(), checked_definition.clone()],
            terminator: Terminator::Return,
        }],
        arg_count: 2,
        return_ty: int(),
    };
    let param_index = |local: usize| -> Option<u64> {
        match local {
            1 => Some(0),
            2 => Some(1),
            _ => None,
        }
    };
    assert!(
        resolve_checked_field_rvalue(&body, 3, 0, Some((BlockId(0), Some(0))), &param_index,)
            .is_none(),
        "a checked tuple defined after its field use must fail closed"
    );
    body.blocks[0].stmts = vec![checked_definition, result_use];
    assert_eq!(
        resolve_checked_field_rvalue(&body, 3, 0, Some((BlockId(0), Some(1))), &param_index,),
        Some(SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(0), SemOperand::Var(1),)),
        "a sole checked tuple definition before its field use remains modeled"
    );
}

#[test]
fn straight_line_return_definition_rejects_hidden_root_effects() {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Projection, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let int = || Ty::Int { width: 32, signed: true };
    let assignment = Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
        span: Default::default(),
    };
    let mut body = VerifiableBody {
        locals: vec![
            LocalDecl { index: 0, ty: int(), name: Some("_0".into()) },
            LocalDecl { index: 1, ty: int(), name: Some("x".into()) },
            LocalDecl {
                index: 2,
                ty: Ty::Ref { mutable: true, inner: Box::new(int()) },
                name: None,
            },
        ],
        blocks: vec![BasicBlock {
            id: BlockId(0),
            stmts: vec![assignment.clone()],
            terminator: Terminator::Return,
        }],
        arg_count: 1,
        return_ty: int(),
    };
    let spine = straight_line_return_spine(&body).expect("control spine");
    assert!(matches!(
        straight_line_return_definition(&body, &spine),
        Some(StraightLineReturnDefinition::Assignment { .. })
    ));

    body.blocks[0].stmts.push(Statement::Deinit { place: Place::local(0) });
    let spine = straight_line_return_spine(&body).expect("control spine remains structural");
    assert!(
        straight_line_return_definition(&body, &spine).is_none(),
        "a Deinit after the apparent return assignment invalidates that definition"
    );

    body.blocks[0].stmts = vec![
        assignment.clone(),
        Statement::Assign {
            place: Place { local: 0, projections: vec![Projection::Field(0)] },
            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
            span: Default::default(),
        },
    ];
    let spine = straight_line_return_spine(&body).expect("control spine");
    assert!(
        straight_line_return_definition(&body, &spine).is_none(),
        "a projected return-place write must not be omitted from the value history"
    );

    body.blocks[0].stmts = vec![
        assignment,
        Statement::Assign {
            place: Place::local(2),
            rvalue: Rvalue::Ref { mutable: true, place: Place::local(0) },
            span: Default::default(),
        },
    ];
    let spine = straight_line_return_spine(&body).expect("control spine");
    assert!(
        straight_line_return_definition(&body, &spine).is_none(),
        "a mutable alias of the return place invalidates direct-write completeness"
    );
}

#[test]
fn straight_line_return_spine_allows_only_one_returning_switch_successor() {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody,
    };
    let int = || Ty::Int { width: 32, signed: true };
    let assign = |value| Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(value))),
        span: Default::default(),
    };
    let mut body = VerifiableBody {
        locals: vec![LocalDecl { index: 0, ty: int(), name: Some("_0".into()) }],
        blocks: vec![
            BasicBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::SwitchInt {
                    discr: Operand::Constant(ConstValue::Bool(true)),
                    targets: vec![(0, BlockId(1))],
                    otherwise: BlockId(2),
                    exhaustive_enum_unreachable: false,
                    span: Default::default(),
                },
            },
            BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Unreachable },
            BasicBlock {
                id: BlockId(2),
                stmts: vec![assign(7)],
                terminator: Terminator::Goto(BlockId(3)),
            },
            BasicBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
        ],
        arg_count: 0,
        return_ty: int(),
    };
    assert!(
        straight_line_return_spine(&body).is_some(),
        "one returning success arm plus a non-returning panic arm is a unique return spine"
    );

    let mut disconnected = body.clone();
    disconnected.blocks.push(BasicBlock {
        id: BlockId(4),
        stmts: vec![],
        terminator: Terminator::Unreachable,
    });
    assert!(
        straight_line_return_spine(&disconnected).is_none(),
        "a disconnected island must invalidate the selected return spine"
    );

    body.blocks[1].stmts.push(assign(9));
    body.blocks[1].terminator = Terminator::Goto(BlockId(3));
    assert!(
        straight_line_return_spine(&body).is_none(),
        "two distinct returning successors are a guarded branch, not a straight-line spine"
    );
}

#[test]
fn sem_cf_return_of_mir_recognizes_conjunctive_guard() {
    // ADDITIVE: a CONJUNCTIVE guard (`a < 100 && b < 100`, lowered as TWO chained
    // SwitchInts) is now RECOGNIZED via the `And` Cond constructor — the recognizer
    // reflects it to a `SemCondTree::And(Leaf(Lt(a,100)), Leaf(Lt(b,100)))` and its
    // branch refinement proves modulo 3 (`denote_substitutedB E (And c1 c2) t f`
    // ι/δ-reduces to the live-grounded `Ite(And(...))` by reflexivity). This was the
    // deferred multi-condition frontier; it is now in the modeled fragment.
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u = || Ty::Int { width: 32, signed: false };
    let p = |l: usize| Place::local(l);
    let func = VerifiableFunction {
        name: "guarded_and".into(),
        def_path: "crate::guarded_and".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: u(), name: Some("a".into()) },
                LocalDecl { index: 2, ty: u(), name: Some("b".into()) },
                LocalDecl { index: 3, ty: Ty::Bool, name: None },
                LocalDecl { index: 4, ty: Ty::Bool, name: None },
            ],
            blocks: vec![
                // bb0: _3 := Lt(a,100); SwitchInt(_3){0→bb3(else), otherwise→bb1}
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: p(3),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Lt,
                            Operand::Copy(p(1)),
                            Operand::Constant(ConstValue::Uint(100, 32)),
                        ),
                        span: Default::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Move(p(3)),
                        targets: vec![(0, BlockId(3))],
                        otherwise: BlockId(1),
                        exhaustive_enum_unreachable: false,
                        span: Default::default(),
                    },
                },
                // bb1: _4 := Lt(b,100); SwitchInt(_4){0→bb3(else), otherwise→bb2(then)}
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![Statement::Assign {
                        place: p(4),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Lt,
                            Operand::Copy(p(2)),
                            Operand::Constant(ConstValue::Uint(100, 32)),
                        ),
                        span: Default::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Move(p(4)),
                        targets: vec![(0, BlockId(3))],
                        otherwise: BlockId(2),
                        exhaustive_enum_unreachable: false,
                        span: Default::default(),
                    },
                },
                // bb2 (then): _0 := a + b; Goto bb4
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![Statement::Assign {
                        place: p(0),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Add,
                            Operand::Copy(p(1)),
                            Operand::Copy(p(2)),
                        ),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(4)),
                },
                // bb3 (else): _0 := 0; Goto bb4
                BasicBlock {
                    id: BlockId(3),
                    stmts: vec![Statement::Assign {
                        place: p(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(0, 32))),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(4)),
                },
                BasicBlock { id: BlockId(4), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 2,
            return_ty: u(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    let param_index =
        |local: usize| -> Option<u64> { (1..=2).contains(&local).then(|| (local - 1) as u64) };
    // RECOGNIZED: the conjunctive guard reflects to an `And` of the two comparisons.
    let cf = sem_cf_return_of_mir(&func, &param_index)
        .expect("a conjunctive (two-SwitchInt) guard is now recognized as an And cond");
    let SemCondTree::And(c1, c2) = &cf.cond else {
        panic!("a conjunctive guard must reflect to SemCondTree::And, got {:?}", cf.cond)
    };
    assert_eq!(
        **c1,
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(0),
            b: SemOperand::Const(100)
        })
    );
    assert_eq!(
        **c2,
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(1),
            b: SemOperand::Const(100)
        })
    );
    // The then/else arms: a + b (then) and 0 (else).
    assert_eq!(
        cf.then_rv,
        SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(0), SemOperand::Var(1))
    );
    assert_eq!(cf.else_rv, SemRvalue::Use(SemOperand::Const(0)));
    // Its branch refinement proves modulo 3 — the conjunctive guard IS adequate.
    assert_eq!(
        check_branch_refinement(&cf),
        RefinementVerdict::ProvenModulo3,
        "the conjunctive-guard branch refinement (And cond) must prove modulo 3"
    );
    // …so the whole-function contract witness now MINTS for it (additive depth).
    assert!(
        function_adequacy_witness(&func).is_some(),
        "a conjunctive-guard function now mints a composed contract witness (recognized)"
    );
}

// =======================================================================
// Trust: discriminant-guard leaf (M1, THE PICK — either::is_left/is_right).
// `SwitchInt` guarded by `Rvalue::Discriminant` (an enum-tag read), the
// EXHAUSTIVE 2-variant-match shape `Either::is_left`'s real MIR uses (see
// fixtures/either-discriminant-corpus, byte-for-byte the real dump). Plus
// the sibling Call-then-UnaryOp desugar `Either::is_right`'s `!is_left(self)`
// needs. Adversarial probes (W4 discipline): (a) multiply-assigned
// discriminant temp, (b) a `&mut`/reassigned receiver, (c) an inverted
// tag-to-block arm mapping (correctness, not just decline), (d) a >2-variant
// switch.
// =======================================================================

/// Build an `Either::is_left`-shaped `VerifiableFunction`: `self: &Either<L,
/// R>` (param 1, immutable reference), `_2 := Discriminant((*_1))`,
/// `switchInt(_2) -> [(0, bb3), (1, bb2)], otherwise: bb1 (Unreachable)`
/// (`exhaustive_enum_unreachable: true`), `bb3: _0 := true; goto bb4`,
/// `bb2: _0 := false; goto bb4`, `bb4: return`. This is BYTE-FOR-BYTE the
/// real `either` 1.15.0 `is_left` MIR shape (see
/// `fixtures/either-discriminant-corpus/Either__<L, R>__is_left.json`,
/// reproduced by hand here so each adversarial probe below can perturb
/// exactly one axis at a time).
fn either_is_left_shaped_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
        Statement, Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let either_ty = Ty::Ref {
        mutable: false,
        inner: Box::new(Ty::Adt { adt_kind: None, layout: None,
            name: "Either".to_string(),
            fields: vec![
                ("__tag".into(), Ty::Int { width: 64, signed: true }),
                (
                    "__v0_0".into(),
                    Ty::Unsupported {
                        kind: "TyKind::Param".into(),
                        detail: "generic parameter L/#0 needs monomorphization".into(),
                    },
                ),
                (
                    "__v1_0".into(),
                    Ty::Unsupported {
                        kind: "TyKind::Param".into(),
                        detail: "generic parameter R/#1 needs monomorphization".into(),
                    },
                ),
            ],
            variants: vec![],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, }),
    };
    VerifiableFunction {
        name: "is_left".into(),
        def_path: "Either::<L, R>::is_left".into(),
        span: trust_types::SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: either_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::Int { width: 64, signed: true }, name: None },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Discriminant(Place {
                            local: 1,
                            projections: vec![Projection::Deref],
                        }),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Move(Place::local(2)),
                        targets: vec![(0, BlockId(3)), (1, BlockId(2))],
                        otherwise: BlockId(1),
                        exhaustive_enum_unreachable: true,
                        span: trust_types::SourceSpan::default(),
                    },
                },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![],
                    terminator: Terminator::Unreachable,
                },
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(false))),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(4)),
                },
                BasicBlock {
                    id: BlockId(3),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(4)),
                },
                BasicBlock { id: BlockId(4), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 1,
            return_ty: Ty::Bool,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

fn either_param_index(local: usize) -> Option<u64> {
    (local == 1).then_some(0)
}

#[test]
fn either_is_left_discriminant_guard_recognized_and_proves_modulo_3() {
    let func = either_is_left_shaped_func();
    let cf = sem_cf_return_of_mir(&func, &either_param_index)
        .expect("the Either::is_left discriminant-guard shape is now recognized");
    let SemCondTree::Leaf(cond) = &cf.cond else {
        panic!("a single discriminant guard must be a Leaf, got {:?}", cf.cond)
    };
    assert_eq!(cond.op, SemCmpOp::Eq);
    assert_eq!(cond.a, SemOperand::Discriminant(Box::new(SemOperand::Var(0))));
    assert_eq!(cond.b, SemOperand::Const(0));
    // tag 0 -> the THEN target (bb3, `_0 := true`); tag 1 -> the ELSE target
    // (bb2, `_0 := false`) — matching the REAL fixture's block contents.
    assert_eq!(cf.then_rv, SemRvalue::Use(SemOperand::Const(1)));
    assert_eq!(cf.else_rv, SemRvalue::Use(SemOperand::Const(0)));
    assert_eq!(
        check_branch_refinement(&cf),
        RefinementVerdict::ProvenModulo3,
        "the discriminant-guard branch refinement must prove modulo 3"
    );
    assert!(
        branch_refinement_witness(&func).is_some_and(|c| c.is_modulo_3()),
        "the whole-function branch refinement witness must mint modulo 3"
    );
    assert!(
        function_adequacy_witness(&func).is_some(),
        "the discriminant-guarded is_left must mint a composed contract witness"
    );
}

#[test]
fn discriminant_base_accepts_only_validated_enum_representations() {
    use trust_types::{Place, Projection, Ty, VariantDef};

    let mut func = either_is_left_shaped_func();
    let discriminated = Place { local: 1, projections: vec![Projection::Deref] };
    let resolve = |func: &trust_types::VerifiableFunction| {
        sem_discriminant_base_of_mir(
            &func.body,
            &discriminated,
            &either_param_index,
            Some((trust_types::BlockId(0), Some(0))),
        )
    };
    assert_eq!(
        resolve(&func),
        Some(SemOperand::Var(0)),
        "the exact historical signed-tag/payload layout remains a validated enum carrier"
    );

    let replace_referent = |func: &mut trust_types::VerifiableFunction, ty: Ty| {
        let Ty::Ref { inner, .. } = &mut func.body.locals[1].ty else {
            panic!("Either self must remain a reference")
        };
        *inner = Box::new(ty);
    };
    let tag = || ("__tag".into(), Ty::Int { width: 64, signed: true });
    let legacy = |fields| Ty::Adt { adt_kind: None, layout: None,
        name: "MaybeEnum".into(),
        fields,
        variants: vec![],
        disc_index_safe: false,
        faithful_enum_repr: None, enum_layout: None, };
    let malformed = [
        ("scalar", Ty::Int { width: 64, signed: true }),
        ("ordinary struct", Ty::adt("S", vec![("value".into(), Ty::Bool)])),
        ("tag only", legacy(vec![tag()])),
        (
            "unsigned tag",
            legacy(vec![
                ("__tag".into(), Ty::Int { width: 64, signed: false }),
                ("__v0_0".into(), Ty::Bool),
            ]),
        ),
        ("noncanonical payload name", legacy(vec![tag(), ("value".into(), Ty::Bool)])),
        ("gapped payload positions", legacy(vec![tag(), ("__v0_1".into(), Ty::Bool)])),
        (
            "duplicate parsed payload position",
            legacy(vec![tag(), ("__v0_0".into(), Ty::Bool), ("__v00_0".into(), Ty::Bool)]),
        ),
    ];
    for (label, ty) in malformed {
        let mut bad = func.clone();
        replace_referent(&mut bad, ty);
        assert_eq!(resolve(&bad), None, "{label} must not acquire enum discriminant semantics");
    }

    replace_referent(
        &mut func,
        Ty::adt_enum(
            "Either",
            vec![
                VariantDef { name: "Left".into(), discriminant: 0, fields: vec![] },
                VariantDef { name: "Right".into(), discriminant: 1, fields: vec![] },
            ],
        ),
    );
    assert_eq!(
        resolve(&func),
        Some(SemOperand::Var(0)),
        "first-class VariantDef metadata is the canonical enum authority"
    );
}

#[test]
fn either_is_left_multiply_assigned_discriminant_declines() {
    // Adversarial probe (a): the SwitchInt discriminant temp `_2` is ALSO
    // (redundantly) assigned a SECOND time elsewhere in the body — the
    // block-order-first-decoy soundness gate (PRESERVED unchanged from the
    // pre-existing BinaryOp guard path, `ed5e506ce3`) must decline the WHOLE
    // shape, never silently resolve to the block-order-first assignment.
    use trust_types::{Place, Projection, Rvalue, Statement};
    let mut func = either_is_left_shaped_func();
    func.body.blocks[1].stmts.push(Statement::Assign {
        place: Place::local(2),
        rvalue: Rvalue::Discriminant(Place { local: 1, projections: vec![Projection::Deref] }),
        span: trust_types::SourceSpan::default(),
    });
    assert!(
        sem_cf_return_of_mir(&func, &either_param_index).is_none(),
        "a multiply-assigned discriminant temp must decline (block-order-first-decoy gate)"
    );
    assert!(branch_refinement_witness(&func).is_none());
}

#[test]
fn either_is_left_mutable_self_declines() {
    // Adversarial probe (b): `self: &mut Either<L, R>` — a MUTABLE reference.
    // A mutable alias could reassign the referent BETWEEN the discriminant
    // read and the switch (this leaf has no mechanism to verify no
    // intervening write occurred), mirroring `sem_field_read_operand`'s
    // identical `&mut` decline. Must decline.
    use trust_types::Ty;
    let mut func = either_is_left_shaped_func();
    let Ty::Ref { mutable, .. } = &mut func.body.locals[1].ty else {
        panic!("local 1 must be a Ref");
    };
    *mutable = true;
    assert!(
        sem_cf_return_of_mir(&func, &either_param_index).is_none(),
        "a `&mut self` discriminant receiver must decline (no reassignment-tracking)"
    );
}

#[test]
fn either_is_left_reassigned_self_declines() {
    // Adversarial probe (b), variant 2: `_1` (the reference LOCAL itself) is
    // REASSIGNED somewhere in the body (`_1 := move _3`) — a discriminant
    // read resolves `_1` to its ENTRY-TIME value, but a reassignment means
    // SOME use of `_1` sees a value the entry-time `Var` does not represent.
    // The REASSIGNED-PARAM soundness gate (`param_reassigned_by_stmt`, shared
    // with every other entry-time parameter read in this file) must decline.
    use trust_types::{LocalDecl, Operand, Place, Rvalue, Statement};
    let mut func = either_is_left_shaped_func();
    let self_ty = func.body.locals[1].ty.clone();
    func.body.locals.push(LocalDecl { index: 3, ty: self_ty, name: None });
    func.body.blocks[1].stmts.push(Statement::Assign {
        place: Place::local(1),
        rvalue: Rvalue::Use(Operand::Move(Place::local(3))),
        span: trust_types::SourceSpan::default(),
    });
    assert!(
        sem_cf_return_of_mir(&func, &either_param_index).is_none(),
        "a REASSIGNED `self` local must decline (REASSIGNED-PARAM soundness gate)"
    );
}

#[test]
fn either_is_left_inverted_arm_mapping_models_correctly() {
    // Adversarial probe (c): the tag-to-block VALUE mapping is INVERTED
    // relative to `is_left` (tag 0's target, bb3, now assigns `false`; tag
    // 1's target, bb2, now assigns `true` — as if this were `is_right`'s own
    // raw discriminant match, `Right` being variant 1). The recognizer must
    // follow the ACTUAL CFG target blocks, never assume "tag 0 is always the
    // true/first arm" — so `then_rv`/`else_rv` must come out SWAPPED
    // relative to `is_left`'s, tracking the REAL arm contents, not a
    // hardcoded convention.
    use trust_types::{BasicBlock, ConstValue, Operand, Place, Rvalue, Statement};
    let mut func = either_is_left_shaped_func();
    let set_val = |b: &mut BasicBlock, v: bool| {
        b.stmts = vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(v))),
            span: trust_types::SourceSpan::default(),
        }];
    };
    set_val(&mut func.body.blocks[2], true); // bb2 (tag 1's target) now assigns TRUE.
    set_val(&mut func.body.blocks[3], false); // bb3 (tag 0's target) now assigns FALSE.
    let cf = sem_cf_return_of_mir(&func, &either_param_index)
        .expect("the inverted-value shape is still recognized (same guard topology)");
    assert_eq!(
        cf.then_rv,
        SemRvalue::Use(SemOperand::Const(0)),
        "the THEN arm (tag 0 -> bb3) must reflect bb3's ACTUAL (now FALSE) value, \
         not is_left's original TRUE"
    );
    assert_eq!(
        cf.else_rv,
        SemRvalue::Use(SemOperand::Const(1)),
        "the ELSE arm (tag 1 -> bb2) must reflect bb2's ACTUAL (now TRUE) value, \
         not is_left's original FALSE"
    );
    assert_eq!(
        check_branch_refinement(&cf),
        RefinementVerdict::ProvenModulo3,
        "the inverted-mapping guard's branch refinement must ALSO prove modulo 3 — the \
         reflection tracks the REAL CFG, so it is adequate regardless of which literal \
         sits in which block"
    );
}

// Trust: DIAGNOSTIC (Item 1, wave-a) — the SINGLE-TARGET discriminant
// `matches!` shape (`matches!(b, Bound::Excluded(_))` on a 3-variant enum):
//   bb0: _d := Discriminant(self);  SwitchInt(_d) { K -> bbTrue } otherwise -> bbFalse
//   bbTrue:  _r := true;  goto join     bbFalse: _r := false; goto join
//   join:    _0 := Copy(_r);  Return
// K is read from the MIR switch value. tag_true is the value-K arm's bool.
fn bound_matches_shaped_func(k: u128, tag_true: bool) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VariantDef, VerifiableBody, VerifiableFunction,
    };
    let i32t = Ty::Int { width: 32, signed: true };
    let bound_ty = Ty::Adt { adt_kind: None, layout: None,
        name: "std::ops::Bound".to_string(),
        fields: vec![
            ("__tag".to_string(), Ty::Int { width: 64, signed: true }),
            ("__v0_0".to_string(), i32t.clone()),
            ("__v1_0".to_string(), i32t.clone()),
        ],
        variants: vec![
            VariantDef {
                name: "Included".to_string(),
                discriminant: 0,
                fields: vec![("0".to_string(), i32t.clone())],
            },
            VariantDef {
                name: "Excluded".to_string(),
                discriminant: 1,
                fields: vec![("0".to_string(), i32t.clone())],
            },
            VariantDef {
                name: "Unbounded".to_string(),
                discriminant: 2,
                fields: vec![],
            },
        ],
        disc_index_safe: true,
        faithful_enum_repr: None, enum_layout: None, };
    VerifiableFunction {
        name: "w_bound_matches".into(),
        def_path: "w_bound_matches".into(),
        span: trust_types::SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: bound_ty, name: Some("b".into()) },
                LocalDecl { index: 2, ty: Ty::Bool, name: None },
                LocalDecl { index: 3, ty: Ty::Int { width: 64, signed: true }, name: None },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Discriminant(Place::local(1)),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Copy(Place::local(3)),
                        targets: vec![(k, BlockId(1))],
                        otherwise: BlockId(2),
                        exhaustive_enum_unreachable: false,
                        span: trust_types::SourceSpan::default(),
                    },
                },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(tag_true))),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(3)),
                },
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(!tag_true))),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(3)),
                },
                BasicBlock {
                    id: BlockId(3),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                },
            ],
            arg_count: 1,
            return_ty: Ty::Bool,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn bound_single_target_matches_certifies_any_k_sound_polarity() {
    // Trust: Item 1 (wave-a) — `matches!(b, Bound::Excluded(_))` on the
    // 3-variant `Bound` lowers to a SINGLE-target discriminant SwitchInt
    // `[(K, true_arm)] otherwise -> false_arm`. The recognizer reads K from the
    // MIR and models `disc == K` for ANY K (is_included=0, is_excluded=1,
    // is_unbounded=2) — with the SOUND (non-inverted) polarity: value-K edge is
    // the MATCHED (guard-TRUE) arm. (The pre-Item-1 code routed this through the
    // Bool-comparison arm, INVERTING it to `disc != K`, and only fired for K=0.)
    let pidx = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    for k in [0u128, 1, 2] {
        let func = bound_matches_shaped_func(k, /*tag_true=*/ true);
        let cf = sem_cf_return_of_mir(&func, &pidx)
            .expect("single-target discriminant matches! must recognize for any K");
        assert_eq!(
            cf.cond,
            SemCondTree::Leaf(SemCond {
                op: SemCmpOp::Eq,
                a: SemOperand::Discriminant(Box::new(SemOperand::Var(0))),
                b: SemOperand::Const(i128::try_from(k).unwrap()),
            }),
            "the guard is EXACTLY tag(self) == K, K read from the MIR (k={k})"
        );
        assert_eq!(
            cf.then_rv,
            SemRvalue::Use(SemOperand::Const(1)),
            "value-K edge is the MATCHED (true=1) arm — NOT inverted (k={k})"
        );
        assert_eq!(
            cf.else_rv,
            SemRvalue::Use(SemOperand::Const(0)),
            "otherwise edge is the guard-false (false=0) arm (k={k})"
        );
        assert_eq!(check_branch_refinement(&cf), RefinementVerdict::ProvenModulo3);
        assert!(
            function_fully_faithful_witness(&func).is_some_and(|c| c.is_modulo_3()),
            "the single-target matches! (k={k}) must mint a fully-faithful cert"
        );
    }
    // Inverted-arm form `!matches!(b, Excluded(_))` (value-K edge sets FALSE):
    // the recognizer tracks the ACTUAL arm bools, modeling `disc != K`
    // (then=false, else=true), never a hardcoded convention.
    let neg = bound_matches_shaped_func(1, /*tag_true=*/ false);
    let cf_neg = sem_cf_return_of_mir(&neg, &pidx).expect("recognized");
    assert_eq!(cf_neg.then_rv, SemRvalue::Use(SemOperand::Const(0)));
    assert_eq!(cf_neg.else_rv, SemRvalue::Use(SemOperand::Const(1)));
    assert_eq!(check_branch_refinement(&cf_neg), RefinementVerdict::ProvenModulo3);
}

#[test]
fn bound_single_target_wrong_k_claim_is_kernel_rejected() {
    // FORGERY PROBE (Item 1): the recognized is_excluded (K=1) return denotes
    // `disc == 1`. CLAIMING it denotes the K=0 (`disc == 0`) eval_ite must fail
    // to type-check — the tag constant K is load-bearing in the KERNEL leaf,
    // exactly like the straight-line discr-compare lane's wrong-tag probe.
    let pidx = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    let func = bound_matches_shaped_func(1, true);
    let r = sem_cf_return_of_mir(&func, &pidx).expect("recognized");
    assert_eq!(check_branch_refinement(&r), RefinementVerdict::ProvenModulo3);
    // The wrong-K witness: the SAME arms, but the guard claims `disc == 0`.
    let wrong = SemCfReturn {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Eq,
            a: SemOperand::Discriminant(Box::new(SemOperand::Var(0))),
            b: SemOperand::Const(0),
        }),
        then_rv: r.then_rv.clone(),
        else_rv: r.else_rv.clone(),
    };
    let e_ref = Expr::bvar(0);
    let wrong_rhs = cf_return_denotation(&wrong, &e_ref);
    let verdict = check_cf_return_adequacy_inner(&r, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong tag constant (== 0 vs the MIR's == 1) MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn canonical_trait_method_bridges_from_forwarder_spellings() {
    // Trust: Item 2 (wave-a) — the call-site QUALIFIED spelling and the dump
    // IMPL-BLOCK spelling of the SAME `From` impl canonicalize to the SAME tuple.
    use trust_types::call_graph::canonical_trait_method;
    let call = "<u32 as std::convert::From<u8>>::from";
    let dump = "std::convert::num::<impl std::convert::From<u8> for u32>::from";
    let q = canonical_trait_method(call).expect("qualified spelling parses");
    let d = canonical_trait_method(dump).expect("impl-block spelling parses");
    assert_eq!(q, d, "the two spellings of `u32::from(u8)` must canonicalize equal");
    assert_eq!(
        q,
        (
            "std::convert::From".to_string(),
            "u8".to_string(),
            "u32".to_string(),
            "from".to_string()
        )
    );
    // NEGATIVE: two DIFFERENT From impls must NOT cross-match.
    let other_arg = canonical_trait_method("<u32 as std::convert::From<u16>>::from").unwrap();
    assert_ne!(q, other_arg, "From<u8> vs From<u16> (different ARGS) must NOT match");
    let other_self =
        canonical_trait_method("std::convert::num::<impl std::convert::From<u8> for u64>::from")
            .unwrap();
    assert_ne!(q, other_self, "for u32 vs for u64 (different SELF) must NOT match");
    // Inherent methods / free fns / niche transmute extractors decline (→ keep
    // the exact/suffix fallback, never a spurious canonical match).
    assert!(canonical_trait_method("std::num::NonZero::<u32>::get").is_none());
    assert!(canonical_trait_method("from_u8_u32").is_none());
    assert!(canonical_trait_method("std::cmp::max::<usize>").is_none());
}

#[test]
fn resolve_certified_callee_bridges_from_impl_spelling_no_cross_match() {
    // Trust: Item 2 — the From-forwarder call resolves to the certified
    // impl-block registry key across the spelling gap; a DIFFERENT impl never
    // borrows the certificate.
    use std::collections::BTreeMap;
    let fact =
        CalleeFact { arg_count: 1, requires: Some(vec![]), param_names: vec![Some("x".into())] };
    let mut reg: BTreeMap<String, CalleeFact> = BTreeMap::new();
    reg.insert(
        "std::convert::num::<impl std::convert::From<u8> for u32>::from".to_string(),
        fact.clone(),
    );
    let hit = resolve_certified_callee(&reg, "<u32 as std::convert::From<u8>>::from");
    assert!(hit.is_some(), "the From-forwarder call must resolve to the certified impl");
    assert_eq!(
        hit.unwrap().0,
        "std::convert::num::<impl std::convert::From<u8> for u32>::from"
    );
    // A DIFFERENT From impl (From<u16>) must NOT borrow this certificate.
    assert!(
        resolve_certified_callee(&reg, "<u32 as std::convert::From<u16>>::from").is_none(),
        "From<u16> must NOT cross-match the From<u8> certificate (unsound borrow)"
    );
    // A different SELF (u64::from) must NOT match either.
    assert!(resolve_certified_callee(&reg, "<u64 as std::convert::From<u8>>::from").is_none());
}

#[test]
fn resolve_certified_callee_canonical_ambiguity_fails_closed() {
    // Trust: Item 2 — two registry keys canonicalizing to the SAME tuple ⇒
    // ambiguous ⇒ decline (never guess). The exact/suffix tiers see no hit
    // (neither key ends with the qualified suffix), so the canonical tier is
    // reached and must fail closed.
    use std::collections::BTreeMap;
    let fact =
        CalleeFact { arg_count: 1, requires: Some(vec![]), param_names: vec![Some("x".into())] };
    let mut reg: BTreeMap<String, CalleeFact> = BTreeMap::new();
    reg.insert("a::<impl std::convert::From<u8> for u32>::from".to_string(), fact.clone());
    reg.insert("b::<impl std::convert::From<u8> for u32>::from".to_string(), fact.clone());
    assert!(
        resolve_certified_callee(&reg, "<u32 as std::convert::From<u8>>::from").is_none(),
        "an ambiguous canonical tuple MUST fail closed"
    );
}

// Trust: Item 3 (wave-a) — `Config::capped_count(&self, buf) -> u32` =
// `self.count.min(buf.cap as u32)`: the standard FF forwarder shape plus ONE
// width-changing `IntToInt` cast (`buf.cap as u32`, u64 -> u32) feeding a call arg.
fn capped_count_shaped_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Projection, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u32t = Ty::Int { width: 32, signed: false };
    let u64t = Ty::Int { width: 64, signed: false };
    let ref_to = |name: &str, field_ty: Ty| Ty::Ref {
        mutable: false,
        inner: Box::new(Ty::Adt { adt_kind: None, layout: None,
            name: name.to_string(),
            fields: vec![("padding".into(), Ty::Unit), ("value".into(), field_ty)],
            variants: vec![],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, }),
    };
    let field_read = |base: usize, fld: usize| {
        Rvalue::Use(Operand::Copy(Place {
            local: base,
            projections: vec![Projection::Deref, Projection::Field(fld)],
        }))
    };
    VerifiableFunction {
        name: "capped_count".into(),
        def_path: "Config::capped_count".into(),
        span: trust_types::SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u32t.clone(), name: None },
                LocalDecl {
                    index: 1,
                    ty: ref_to("Config", u32t.clone()),
                    name: Some("self".into()),
                },
                LocalDecl {
                    index: 2,
                    ty: ref_to("Buf", u64t.clone()),
                    name: Some("buf".into()),
                },
                LocalDecl { index: 3, ty: u32t.clone(), name: None },
                LocalDecl { index: 4, ty: u32t.clone(), name: None },
                LocalDecl { index: 5, ty: u64t, name: None },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![
                        Statement::Assign {
                            place: Place::local(3),
                            rvalue: field_read(1, 1), // self.count : u32
                            span: trust_types::SourceSpan::default(),
                        },
                        Statement::Assign {
                            place: Place::local(5),
                            rvalue: field_read(2, 1), // buf.cap : u64
                            span: trust_types::SourceSpan::default(),
                        },
                        Statement::Assign {
                            place: Place::local(4),
                            rvalue: Rvalue::Cast(Operand::Move(Place::local(5)), u32t.clone()),
                            span: trust_types::SourceSpan::default(),
                        },
                    ],
                    terminator: Terminator::Call {
                        func: "<u32 as std::cmp::Ord>::min".into(),
                        args: vec![
                            Operand::Move(Place::local(3)),
                            Operand::Move(Place::local(4)),
                        ],
                        dest: Place::local(0),
                        target: Some(BlockId(1)),
                        unwind: trust_types::UnwindEdge::Unreachable,
                        span: trust_types::SourceSpan::default(),
                        atomic: None,
                        is_foreign: false,
                        is_unsafe_sig: false,
                    },
                },
                BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 2,
            return_ty: u32t,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn width_changing_cast_arg_resolves_to_opaque_carrier_not_identity() {
    // Trust: Item 3 — `buf.cap as u32` (u64 -> u32 narrow) fed as a call arg
    // resolves to the OPAQUE `SemOperand::Cast` carrier (keyed by dest width 32),
    // NEVER an identity (which would be the false claim `cast == src` for a
    // truncating cast). The SAME-WIDTH reinterpret sibling declines (this is
    // genuinely width-changing).
    use trust_types::{Operand, Place};
    let func = capped_count_shaped_func();
    let body = &func.body;
    let pidx = |local: usize| -> Option<u64> {
        if (1..=2).contains(&local) { u64::try_from(local - 1).ok() } else { None }
    };
    let arg4 = Operand::Move(Place::local(4));
    assert!(
        sem_call_arg_samewidth_bitcast_operand(
            body,
            &arg4,
            trust_types::BlockId(0),
            &pidx,
        )
        .is_none(),
        "a width-changing cast must NOT resolve via the same-width reinterpret lane"
    );
    let carrier = sem_call_arg_widthchanging_cast_operand(
        body,
        &arg4,
        trust_types::BlockId(0),
        &pidx,
    )
        .expect("the width-changing cast arg must resolve to the opaque carrier");
    match carrier {
        SemOperand::Cast(base, 32, false) => {
            // The carrier wraps the resolved field read — an OPAQUE base, NOT a
            // flattened identity onto the source value.
            assert!(
                matches!(*base, SemOperand::Field(_, 1)),
                "the opaque cast base must be the resolved buf.cap field read, got {base:?}"
            );
        }
        other => panic!("expected an opaque Cast(_, 32, false) carrier, got {other:?}"),
    }
    // The call-arg entry point routes it the same way.
    assert!(matches!(
        sem_call_arg_operand(body, &arg4, trust_types::BlockId(0), &pidx),
        Some(SemOperand::Cast(_, 32, false))
    ));
}

#[test]
fn capped_count_forwarder_certifies_with_min_callee() {
    // Trust: Item 3 — end-to-end: `Config::capped_count` certifies fully-faithful
    // once its width-changing cast arg resolves, with the certified `min` callee
    // in the registry (callees-first, exactly as the FF gate processes it).
    use std::collections::BTreeMap;
    let func = capped_count_shaped_func();
    let mut reg: BTreeMap<String, CalleeFact> = BTreeMap::new();
    reg.insert(
        "<u32 as std::cmp::Ord>::min".to_string(),
        CalleeFact {
            arg_count: 2,
            requires: Some(vec![]),
            param_names: vec![Some("self".into()), Some("other".into())],
        },
    );
    assert!(
        function_fully_faithful_witness_with_callees(&func, &reg)
            .is_some_and(|c| c.is_modulo_3()),
        "capped_count must certify once its width-changing cast arg resolves"
    );
}

// Trust: Item 4 (wave-a) — the `char::is_ascii` leaf's SYNTHESIZED char
// validity-range precondition over the internal `_3` scalar-value read.
fn char_validity_fact(v: &str) -> trust_types::Formula {
    use trust_types::{Formula as F, Sort};
    let var = || Box::new(F::Var(v.to_string(), Sort::Int));
    F::And(vec![
        F::Ge(var(), Box::new(F::Int(0))),
        F::Le(var(), Box::new(F::Int(1_114_111))),
        F::Not(Box::new(F::And(vec![
            F::Ge(var(), Box::new(F::Int(55_296))),
            F::Le(var(), Box::new(F::Int(57_343))),
        ]))),
    ])
}

