#[test]
fn char_is_ascii_leaf_char_range_partitioned_requires_established() {
    // Trust: Item 4 — the leaf's synthesized char VALIDITY-RANGE precondition
    // over the internal `_3` is a type tautology; partitioning it out makes the
    // callee export NO caller obligation (`requires = Some([])`), so every call
    // site (e.g. `w_char_is_ascii`) is VACUOUSLY established.
    let func = char_is_ascii_leaf_func();
    assert!(
        is_internal_char_range_fact(&func.preconditions[0], &func.body),
        "the recognizer must fire on the exact leaf char-validity fact"
    );
    let fact = CalleeFact::of_certified(&func);
    assert_eq!(
        fact.requires,
        Some(vec![]),
        "the char-validity fact must be partitioned out → the callee exports NO requires"
    );
}

#[test]
fn is_internal_char_range_fact_tight_shape_rejects_offshape() {
    use trust_types::{Formula as F, Sort};
    let func = char_is_ascii_leaf_func();
    let body = &func.body;
    let var = |v: &str| Box::new(F::Var(v.to_string(), Sort::Int));
    // Positive: the exact internal-local char-validity fact.
    assert!(is_internal_char_range_fact(&char_validity_fact("_3"), body));
    // A PARAMETER-named var must NOT be partitioned (kept as a declared obligation).
    assert!(
        !is_internal_char_range_fact(&char_validity_fact("self"), body),
        "a parameter-named char fact must NOT be partitioned"
    );
    // A NARROWED range (127, not 0x10FFFF) is a GENUINE constraint — off-shape.
    let narrowed = F::And(vec![
        F::Ge(var("_3"), Box::new(F::Int(0))),
        F::Le(var("_3"), Box::new(F::Int(127))),
        F::Not(Box::new(F::And(vec![
            F::Ge(var("_3"), Box::new(F::Int(55_296))),
            F::Le(var("_3"), Box::new(F::Int(57_343))),
        ]))),
    ]);
    assert!(!is_internal_char_range_fact(&narrowed, body));
    // MISSING the surrogate exclusion (2-conjunct) — off-shape.
    let two = F::And(vec![
        F::Ge(var("_3"), Box::new(F::Int(0))),
        F::Le(var("_3"), Box::new(F::Int(1_114_111))),
    ]);
    assert!(!is_internal_char_range_fact(&two, body));
    // DIFFERENT variable per bound — off-shape (never a single-var tautology).
    let mixed = F::And(vec![
        F::Ge(var("_3"), Box::new(F::Int(0))),
        F::Le(var("_4"), Box::new(F::Int(1_114_111))),
        F::Not(Box::new(F::And(vec![
            F::Ge(var("_3"), Box::new(F::Int(55_296))),
            F::Le(var("_3"), Box::new(F::Int(57_343))),
        ]))),
    ]);
    assert!(!is_internal_char_range_fact(&mixed, body));
}

#[test]
fn bool_literal_operand_denotes_0_1_and_non_bool_consts_never_misdenote() {
    // GAP-BOOL adversarial probes (the census's mutant-proved co-gap: the 9
    // ascii_utils predicates + either's const-bool arms all hinge on the NEW
    // `ConstValue::Bool` clause in `sem_operand_of_mir`). Three facets:
    //
    //   1. VALUE-CORRECTNESS: `true`→`Const(1)`, `false`→`Const(0)` — the
    //      bool_as_int 0/1 convention, EXACTLY (never e.g. a nonzero-other-
    //      than-1 for true, which would break the `!x ≡ x==0` desugar's
    //      composition with a certified Bool-returning callee).
    //   2. NON-BOOL CONST IN A BOOL POSITION: a `Uint(2, 8)` arm value in the
    //      Bool-typed `_0` position (type-corrupted MIR — impossible from
    //      real rustc, constructible here) must NOT misdenote onto the bool
    //      convention (never collapsed to `Const(1)` "truthiness"); the model
    //      is VALUE-FAITHFUL (`Const(2)`) — it says what the MIR says.
    //   3. FAIL-CLOSED: every remaining const kind (`Float`, `FloatBits`,
    //      `Unit`, `Str`) stays OUTSIDE the fragment — `None`, never some
    //      truthiness coercion.
    use trust_types::{ConstValue, Operand};
    let body = no_reassign_body(1);
    let pidx = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
    // Facet 1: the exact 0/1 encoding.
    assert_eq!(
        sem_operand_of_mir(&body, &Operand::Constant(ConstValue::Bool(true)), &pidx),
        Some(SemOperand::Const(1)),
        "`true` must denote EXACTLY Const(1) (bool_as_int)"
    );
    assert_eq!(
        sem_operand_of_mir(&body, &Operand::Constant(ConstValue::Bool(false)), &pidx),
        Some(SemOperand::Const(0)),
        "`false` must denote EXACTLY Const(0) (bool_as_int)"
    );
    // Facet 2: a NON-BOOL const sitting in the Bool-typed arm position of the
    // is_left shape — the recognizer must stay VALUE-FAITHFUL (Const(2)),
    // never coerce to the 0/1 convention.
    use trust_types::{Place, Rvalue, Statement};
    let mut func = either_is_left_shaped_func();
    func.body.blocks[3].stmts = vec![Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Uint(2, 8))),
        span: trust_types::SourceSpan::default(),
    }];
    if let Some(cf) = sem_cf_return_of_mir(&func, &either_param_index) {
        assert_eq!(
            cf.then_rv,
            SemRvalue::Use(SemOperand::Const(2)),
            "a Uint(2) arm in a Bool-typed position must denote Const(2) VALUE-FAITHFULLY \
             — NEVER collapsed onto the bool convention (a `Const(1)` here would be a \
             truthiness misdenotation)"
        );
    } // (declining outright would also be sound; misdenoting would not.)
    // Facet 3: out-of-fragment const kinds fail closed.
    for c in [
        ConstValue::Float(1.0),
        ConstValue::FloatBits { bits: 0x3FF0_0000_0000_0000, width: 64 },
        ConstValue::Unit,
    ] {
        assert_eq!(
            sem_operand_of_mir(&body, &Operand::Constant(c.clone()), &pidx),
            None,
            "out-of-fragment const {c:?} must fail closed (no truthiness coercion)"
        );
    }
}

#[test]
fn either_is_left_three_variant_enum_declines() {
    // Adversarial probe (d): a THIRD explicit tag target (reusing bb2, so
    // the arm-block SET itself stays exactly {bb2, bb3} — this exercises
    // the NEW switch-SHAPE gate specifically, not the pre-existing
    // `arms.len() != 2` gate) — an enum with >2 variants hitting the
    // 2-variant-only assumption. Must decline, not silently generalize.
    use trust_types::{BlockId, Terminator};
    let mut func = either_is_left_shaped_func();
    let Terminator::SwitchInt { targets, .. } = &mut func.body.blocks[0].terminator else {
        panic!("bb0 must be a SwitchInt");
    };
    targets.push((2, BlockId(2)));
    assert!(
        sem_cf_return_of_mir(&func, &either_param_index).is_none(),
        "a >2-explicit-target discriminant switch must decline (the 2-variant-only shape gate)"
    );
}

#[test]
fn either_is_left_non_exhaustive_flag_declines() {
    // The `exhaustive_enum_unreachable` flag FALSE (a PARTIAL match, or a
    // plain integer switch that happens to look enum-shaped) must NOT be
    // treated as the 2-arm discriminant shape — the flag is load-bearing.
    use trust_types::Terminator;
    let mut func = either_is_left_shaped_func();
    let Terminator::SwitchInt { exhaustive_enum_unreachable, .. } =
        &mut func.body.blocks[0].terminator
    else {
        panic!("bb0 must be a SwitchInt");
    };
    *exhaustive_enum_unreachable = false;
    assert!(
        sem_cf_return_of_mir(&func, &either_param_index).is_none(),
        "a non-exhaustive-flagged 2-explicit-target switch must decline"
    );
}

#[test]
fn either_is_left_otherwise_not_unreachable_declines() {
    // Belt-and-suspenders: even if the flag were (hypothetically, an
    // upstream bug) wrongly set true, `otherwise` not ACTUALLY reaching an
    // Unreachable block must ALSO decline (the direct re-check
    // `exhaustive_two_arm_discriminant_switch` performs beyond trusting the
    // flag alone).
    use trust_types::{BlockId, Terminator};
    let mut func = either_is_left_shaped_func();
    let Terminator::SwitchInt { otherwise, .. } = &mut func.body.blocks[0].terminator else {
        panic!("bb0 must be a SwitchInt");
    };
    *otherwise = BlockId(4); // retarget to the join block, NOT Unreachable.
    assert!(
        sem_cf_return_of_mir(&func, &either_param_index).is_none(),
        "otherwise not reaching Unreachable must decline even if the flag is (wrongly) true"
    );
}

/// Build an `Either::is_right`-shaped `VerifiableFunction`: `self: &Either<L,
/// R>` (param 1), `_2 := call(Either::<L, R>::is_left, [self])`, `_0 :=
/// !Move(_2)`, `return` — BYTE-FOR-BYTE the real `either` 1.15.0 `is_right`
/// MIR shape (see
/// `fixtures/either-discriminant-corpus/Either__<L, R>__is_right.json`).
fn either_is_right_shaped_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator, Ty,
        UnOp, VerifiableBody, VerifiableFunction,
    };
    let either_ty = Ty::Ref {
        mutable: false,
        inner: Box::new(Ty::Adt { adt_kind: None, layout: None,
            name: "Either".to_string(),
            fields: vec![
                ("__tag".into(), Ty::Int { width: 64, signed: true }),
                (
                    "__v0_0".into(),
                    Ty::Unsupported {
                        kind: "TyKind::Param".into(),
                        detail: "generic parameter L/#0 needs monomorphization".into(),
                    },
                ),
                (
                    "__v1_0".into(),
                    Ty::Unsupported {
                        kind: "TyKind::Param".into(),
                        detail: "generic parameter R/#1 needs monomorphization".into(),
                    },
                ),
            ],
            variants: vec![],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, }),
    };
    VerifiableFunction {
        name: "is_right".into(),
        def_path: "Either::<L, R>::is_right".into(),
        span: trust_types::SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: either_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: Ty::Bool, name: None },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        unwind: UnwindEdge::Unreachable,
                        func: "Either::<L, R>::is_left".into(),
                        args: vec![Operand::Copy(Place::local(1))],
                        dest: Place::local(2),
                        target: Some(BlockId(1)),
                        span: trust_types::SourceSpan::default(),
                        atomic: None,
                        is_foreign: false,
                        is_unsafe_sig: false,
                    },
                },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::UnaryOp(UnOp::Not, Operand::Move(Place::local(2))),
                        span: trust_types::SourceSpan::default(),
                    }],
                    terminator: Terminator::Return,
                },
            ],
            arg_count: 1,
            return_ty: Ty::Bool,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

fn either_is_left_callee_registry() -> std::collections::BTreeMap<String, CalleeFact> {
    let mut registry = std::collections::BTreeMap::new();
    registry.insert(
        "Either::<L, R>::is_left".to_string(),
        CalleeFact {
            arg_count: 1,
            requires: Some(vec![]),
            param_names: vec![Some("self".into())],
        },
    );
    registry
}

#[test]
fn of_certified_partitions_internal_discriminant_facts_not_caller_clauses() {
    // ROOT-CAUSE pin (M1 either): the extractor appends the ALWAYS-TRUE
    // enum-tag range fact `_2 ∈ {0, 1}` (an INTERNAL-temp tautology) to
    // `preconditions`; `of_certified`'s declared-completeness gate must NOT
    // count it as an (unknown) caller obligation — the REAL is_left dump
    // declares 0 requires and must register `requires: Some([])`.
    use trust_types::{Formula as F, Sort};
    let tag_fact = |v: &str| {
        F::Or(vec![
            F::Eq(Box::new(F::Var(v.into(), Sort::Int)), Box::new(F::Int(0))),
            F::Eq(Box::new(F::Var(v.into(), Sort::Int)), Box::new(F::Int(1))),
        ])
    };
    let mut func = either_is_left_shaped_func(); // arg_count 1; local 2 = the tag temp.
    func.preconditions = vec![tag_fact("_2")];
    let fact = CalleeFact::of_certified(&func);
    assert_eq!(
        fact.requires,
        Some(vec![]),
        "the internal `_2 ∈ {{0,1}}` tautology must partition OUT of the caller-facing \
         requires (declared 0 clauses ⇒ Some([]), not None)"
    );

    // ADVERSARIAL (fail-closed direction): the SAME shape over a PARAMETER —
    // by name, or by its `_1` index spelling — is NOT internal vocabulary,
    // stays in the count, and (declared=0 ≠ 1) fails the gate to None.
    for v in ["self", "_1"] {
        let mut f2 = either_is_left_shaped_func();
        f2.preconditions = vec![tag_fact(v)];
        assert_eq!(
            CalleeFact::of_certified(&f2).requires,
            None,
            "a param-vocabulary fact ({v}) must NOT be classified internal — the \
             completeness gate must fail closed"
        );
    }

    // An out-of-body index spelling (`_9` names no local) is NOT recognized —
    // fail closed to None, never silently dropped.
    let mut f3 = either_is_left_shaped_func();
    f3.preconditions = vec![tag_fact("_9")];
    assert_eq!(CalleeFact::of_certified(&f3).requires, None);

    // A declared-but-unparsed clause still fails closed even WITH an internal
    // fact present: declared 1, parsed 0 (the tag fact partitions out) ⇒ None.
    let mut f4 = either_is_left_shaped_func();
    f4.preconditions = vec![tag_fact("_2")];
    f4.spec.requires.push("x < 10".into());
    assert_eq!(
        CalleeFact::of_certified(&f4).requires,
        None,
        "an unparsed declared clause must stay fail-closed even alongside a \
         partitioned internal fact"
    );

    // A MIXED-VARIABLE disjunction is not the emitted shape — not internal.
    let mut f5 = either_is_left_shaped_func();
    f5.preconditions = vec![F::Or(vec![
        F::Eq(Box::new(F::Var("_2".into(), Sort::Int)), Box::new(F::Int(0))),
        F::Eq(Box::new(F::Var("_3".into(), Sort::Int)), Box::new(F::Int(1))),
    ])];
    assert_eq!(CalleeFact::of_certified(&f5).requires, None);
}

#[test]
fn either_is_right_call_then_not_shape_recognized() {
    let func = either_is_right_shaped_func();
    let registry = either_is_left_callee_registry();
    let recognized = sem_call_then_pureop_of_mir(&func, &registry)
        .expect("the Call-then-Not shape (is_right's !is_left(self)) is now recognized");
    assert!(recognized.call_is_lhs, "the call result is the Not's sole operand (LHS position)");
    assert!(
        matches!(recognized.op, CallThenOp::Cmp(SemCmpOp::Eq)),
        "!x desugars to x == 0 (the bool_as_int 0/1 convention)"
    );
    assert_eq!(recognized.other, SemOperand::Const(0));
    let cert = call_then_pureop_adequacy_witness(&recognized)
        .expect("the Call-then-Not certificate must mint (REUSES the existing kernel proof)");
    assert!(cert.is_modulo_3(), "modulo exactly 3, no new axiom");
}

#[test]
fn call_then_not_on_int_dest_declines() {
    // SOUNDNESS: `!x` on an INTEGER is BITWISE complement, not `x == 0` — the
    // desugaring must NOT fire for a non-bool call-result dest (a `!x` on a
    // `u32` `x`, hypothetically reachable if some OTHER certified callee
    // returned an int and a caller bitwise-negated it).
    let mut func = either_is_right_shaped_func();
    func.body.locals[2].ty = trust_types::Ty::Int { width: 32, signed: false };
    let registry = either_is_left_callee_registry();
    assert!(
        sem_call_then_pureop_of_mir(&func, &registry).is_none(),
        "`!x` on an INT-typed call result must NOT desugar to `x == 0` (bitwise vs logical)"
    );
}

#[test]
fn call_then_neg_shape_recognized_on_signed_int_dest() {
    // The sibling `Neg` desugar (`-x ≡ 0 - x`), exercised directly: swap the
    // is_right fixture's `UnaryOp(Not, _)` for `UnaryOp(Neg, _)` over a
    // SIGNED int call result (Neg is invalid on bool/unsigned in real Rust).
    use trust_types::{Rvalue, Statement, Ty, UnOp};
    let mut func = either_is_right_shaped_func();
    func.body.locals[0].ty = Ty::Int { width: 32, signed: true };
    func.body.locals[2].ty = Ty::Int { width: 32, signed: true };
    func.body.return_ty = Ty::Int { width: 32, signed: true };
    let Statement::Assign { rvalue, .. } = &mut func.body.blocks[1].stmts[0] else {
        panic!("bb1's sole statement must be an Assign");
    };
    let Rvalue::UnaryOp(op, operand) = rvalue else { panic!("must be a UnaryOp") };
    *op = UnOp::Neg;
    let operand = operand.clone();
    *rvalue = Rvalue::UnaryOp(UnOp::Neg, operand);
    let registry = either_is_left_callee_registry();
    let recognized = sem_call_then_pureop_of_mir(&func, &registry)
        .expect("the Call-then-Neg shape is recognized on a signed-int dest");
    assert!(!recognized.call_is_lhs, "wrap computes Sub(other, x) = 0 - x = -x");
    assert!(matches!(recognized.op, CallThenOp::Bin(SemBinOp::Sub)));
    assert_eq!(recognized.other, SemOperand::Const(0));
    let cert = call_then_pureop_adequacy_witness(&recognized)
        .expect("the Call-then-Neg certificate must mint");
    assert!(cert.is_modulo_3(), "modulo exactly 3, no new axiom");
}

#[test]
fn call_then_neg_on_bool_dest_declines() {
    // SOUNDNESS: `Neg` is never valid on `bool` in real Rust — the desugar
    // must decline rather than silently accept a shape that cannot occur
    // (and, if it somehow did, would not mean `0 - x` over a Bool sort).
    use trust_types::{Rvalue, Statement, UnOp};
    let mut func = either_is_right_shaped_func(); // dest (_2) stays Ty::Bool.
    let Statement::Assign { rvalue, .. } = &mut func.body.blocks[1].stmts[0] else {
        panic!("bb1's sole statement must be an Assign");
    };
    let Rvalue::UnaryOp(_, operand) = rvalue else { panic!("must be a UnaryOp") };
    let operand = operand.clone();
    *rvalue = Rvalue::UnaryOp(UnOp::Neg, operand);
    let registry = either_is_left_callee_registry();
    assert!(
        sem_call_then_pureop_of_mir(&func, &registry).is_none(),
        "Neg on a Bool-typed call result must decline (Neg is never valid on bool)"
    );
}

// =======================================================================
// Trust: DISCRIMINANT-AS-VALUE (M5 slice B, 2026-07-08 — THE PICK). The
// VALUE-position sibling of the discriminant-GUARD leaf above (4958c9fb59):
// `_0 := Discriminant(place)` used DIRECTLY as the return value, not as a
// `SwitchInt` guard. `Ordering::as_raw`'s real MIR (`fixtures/
// census-core-m5-2026-07-07/cmp-ordering/cmp__Ordering__as_raw.json`) is a
// 1-block leaf: `_2 := &_1 (self: Ordering, BY VALUE); _0 :=
// Discriminant((*_2)); return` — unlike `Either::is_left`'s `self: &Either`
// DIRECT reference receiver, `as_raw` takes `self` BY VALUE and re-borrows
// it INLINE (`crate::intrinsics::discriminant_value(&self)`), so
// `sem_discriminant_base_of_mir` needed a SECOND base shape: resolve
// through the locally-taken `&self` (reusing the deref-self identity
// `*(&x) ≡ x`, gated by [`crate::prove::local_soundly_resolvable`] +
// [`deref_write_exists`] + [`param_reassigned_by_stmt`] — the SAME
// belt-and-suspenders discipline every sibling temp-chase in this file
// uses, including the GAP-DEREF-SELF identity `b42adf3079` established for
// the direct-reference-parameter case). Adversarial probes (W4
// discipline): (a) multiply-assigned reference temp, (b) a `&mut` self
// re-borrow, (c) a write reaching through the reference temp, (d) a
// reassigned referent, (e) a wrong-tag-claim, (f) multi-variant (3+) tag
// honesty (the recognized value is NOT coerced to a 2-variant/bool shape).
// =======================================================================

/// Build an `Ordering::as_raw`-shaped `VerifiableFunction`: `self: Ordering`
/// (param 1, BY VALUE — unlike `Either::is_left`'s reference receiver),
/// `_2 := &_1` (an immutable, LOCALLY-TAKEN reference), `_0 :=
/// Discriminant((*_2))`, `return`. This is BYTE-FOR-BYTE the real `core`
/// `Ordering::as_raw` MIR shape (see
/// `fixtures/census-core-m5-2026-07-07/cmp-ordering/cmp__Ordering__as_raw.json`,
/// reproduced by hand here so each adversarial probe below can perturb
/// exactly one axis at a time). `variant_count` controls how many
/// (fieldless) variants the modeled `Ordering`-like enum declares — the
/// honesty probe below builds this at 3 (matching the REAL `Ordering`:
/// `Less`/`Equal`/`Greater`) to demonstrate the recognizer draws no
/// 2-variant/bool conclusion.
fn ordering_as_raw_shaped_func(variant_count: usize) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Place, Projection, Rvalue, SourceSpan, Statement,
        Terminator, Ty, VariantDef, VerifiableBody, VerifiableFunction,
    };
    let ordering_ty = Ty::adt_enum(
        "cmp::Ordering",
        (0..variant_count)
            .map(|i| VariantDef {
                name: format!("V{i}"),
                discriminant: i128::try_from(i).unwrap_or(0),
                fields: vec![],
            })
            .collect(),
    );
    let ordering_ref_ty = Ty::Ref { mutable: false, inner: Box::new(ordering_ty.clone()) };
    VerifiableFunction {
        name: "as_raw".into(),
        def_path: "cmp::Ordering::as_raw".into(),
        span: SourceSpan::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Int { width: 8, signed: true }, name: None },
                LocalDecl { index: 1, ty: ordering_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: ordering_ref_ty, name: None },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Ref { mutable: false, place: Place::local(1) },
                        span: SourceSpan::default(),
                    },
                    Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Discriminant(Place {
                            local: 2,
                            projections: vec![Projection::Deref],
                        }),
                        span: SourceSpan::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: Ty::Int { width: 8, signed: true },
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

fn as_raw_param_index(local: usize) -> Option<u64> {
    (local == 1).then_some(0)
}

#[test]
fn ordering_as_raw_discriminant_value_recognized_and_fully_faithful() {
    let func = ordering_as_raw_shaped_func(3); // Less/Equal/Greater — the real shape.
    let ret = sem_return_of_mir(&func, &as_raw_param_index)
        .expect("the as_raw discriminant-AS-VALUE leaf must now recognize");
    assert!(ret.stmts.is_empty(), "the discriminant read is a CLOSED operand return");
    assert_eq!(ret.ret, SemOperand::Discriminant(Box::new(SemOperand::Var(0))));
    assert_eq!(
        check_return_adequacy(&ret),
        AdequacyVerdict::ProvenModulo3,
        "the discriminant-value return witness must prove modulo 3"
    );
    let cert = function_fully_faithful_witness(&func)
        .expect("as_raw's discriminant-value leaf must mint a fully-faithful certificate");
    assert!(cert.is_modulo_3());
    assert!(cert.safety.is_none(), "a discriminant read raises NO safety VC — vacuously safe");
    assert!(
        matches!(cert.contract.ret, ReturnCertificate::StraightLine(_)),
        "as_raw must certify via the StraightLine (MirSem fallback) return certificate"
    );
}

#[test]
fn ordering_as_raw_multiply_assigned_reference_temp_declines() {
    // Adversarial probe (a): `_2` is ALSO (redundantly) assigned a SECOND
    // time — `local_soundly_resolvable`'s single-assignment gate must
    // decline the whole shape, never silently resolve to the first write.
    use trust_types::{Place, Rvalue, SourceSpan, Statement};
    let mut func = ordering_as_raw_shaped_func(3);
    func.body.blocks[0].stmts.insert(
        1,
        Statement::Assign {
            place: Place::local(2),
            rvalue: Rvalue::Ref { mutable: false, place: Place::local(1) },
            span: SourceSpan::default(),
        },
    );
    assert!(
        sem_return_of_mir(&func, &as_raw_param_index).is_none(),
        "a multiply-assigned reference temp must decline (single-assignment gate)"
    );
    assert!(function_fully_faithful_witness(&func).is_none());
}

#[test]
fn ordering_as_raw_mutable_reborrow_declines() {
    // Adversarial probe (b): `_2 := &mut _1` — a MUTABLE re-borrow. A
    // mutable alias could be written through between the borrow and the
    // discriminant read; the immutable-only `Rvalue::Ref` match must miss
    // it entirely (no referent resolves), mirroring the direct-receiver
    // `&mut self` decline above.
    use trust_types::{Place, Rvalue, Statement};
    let mut func = ordering_as_raw_shaped_func(3);
    let Statement::Assign { rvalue, .. } = &mut func.body.blocks[0].stmts[0] else {
        panic!("stmt 0 must be the reference Assign");
    };
    *rvalue = Rvalue::Ref { mutable: true, place: Place::local(1) };
    assert!(
        sem_return_of_mir(&func, &as_raw_param_index).is_none(),
        "a mutable self re-borrow must decline — no immutable-Ref referent to resolve"
    );
    assert!(function_fully_faithful_witness(&func).is_none());
}

#[test]
fn ordering_as_raw_deref_write_through_reference_declines() {
    // Adversarial probe (c): a (malformed/adversarial) write reaches through
    // `_2` between the borrow and the discriminant read — `deref_write_exists`
    // must catch it even though it is invisible to the plain write-count scan
    // (its place projects THROUGH `_2`, not a direct `_2 := …` write).
    use trust_types::{ConstValue, Operand, Place, Projection, Rvalue, SourceSpan, Statement};
    let mut func = ordering_as_raw_shaped_func(3);
    func.body.blocks[0].stmts.insert(
        1,
        Statement::Assign {
            place: Place { local: 2, projections: vec![Projection::Deref] },
            rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(0))),
            span: SourceSpan::default(),
        },
    );
    assert!(
        sem_return_of_mir(&func, &as_raw_param_index).is_none(),
        "a write reaching through the reference temp must decline (deref-self defense)"
    );
    assert!(function_fully_faithful_witness(&func).is_none());
}

#[test]
fn ordering_as_raw_reassigned_referent_declines() {
    // Adversarial probe (d): `_1` (the BY-VALUE `self` the reference is
    // taken of) is reassigned somewhere in the body — the entry-time-value
    // soundness gate (`param_reassigned_by_stmt`, applied to the REAL
    // underlying parameter, not just the reference temp) must decline.
    use trust_types::{Operand, Place, Rvalue, SourceSpan, Statement};
    let mut func = ordering_as_raw_shaped_func(3);
    func.body.blocks[0].stmts.insert(
        1,
        Statement::Assign {
            place: Place::local(1),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
            span: SourceSpan::default(),
        },
    );
    assert!(
        sem_return_of_mir(&func, &as_raw_param_index).is_none(),
        "a reassigned referent (self) must decline (entry-time-value soundness)"
    );
    assert!(function_fully_faithful_witness(&func).is_none());
}

#[test]
fn ordering_as_raw_wrong_tag_claim_is_kernel_rejected() {
    // Adversarial probe (e): CLAIM the discriminant read denotes the
    // literal constant 0 for EVERY `self`. FALSE — `Discriminant`'s
    // denotation is the opaque, uninterpreted `idx_elem(base, -1)` carrier;
    // claiming it collapses to a closed literal must fail to type-check.
    let r = SemReturn {
        stmts: vec![],
        ret: SemOperand::Discriminant(Box::new(SemOperand::Var(0))),
    };
    let wrong_rhs = int_lit(0);
    let verdict = check_return_adequacy_inner(&r, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong tag claim (Discriminant(self) = 0) MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn ordering_as_raw_multi_variant_tag_honesty_2_through_5_variants() {
    // Adversarial probe (f): the recognized shape and its modulo-3 proof
    // are IDENTICAL whether the source enum has 2 variants (`Either`-class)
    // or matches the REAL `Ordering`'s 3 (`Less`/`Equal`/`Greater`) — or
    // more. The `SemOperand::Discriminant` carrier is the SAME opaque,
    // uninterpreted `idx_elem` selector regardless of `variant_count`: the
    // recognizer never inspects the enum's variant LIST at all (it only
    // resolves the REFERENT place), so it cannot silently assume a
    // 2-variant/bool-shaped tag domain — the value is honestly opaque, not
    // secretly `{0,1}`.
    for variant_count in 2..=5 {
        let func = ordering_as_raw_shaped_func(variant_count);
        let ret = sem_return_of_mir(&func, &as_raw_param_index).unwrap_or_else(|| {
            panic!("{variant_count}-variant enum's discriminant-value leaf must recognize")
        });
        assert_eq!(
            ret.ret,
            SemOperand::Discriminant(Box::new(SemOperand::Var(0))),
            "the denoted carrier does not vary with variant_count={variant_count}"
        );
        assert_eq!(check_return_adequacy(&ret), AdequacyVerdict::ProvenModulo3);
        assert!(
            function_fully_faithful_witness(&func).is_some_and(|c| c.is_modulo_3()),
            "variant_count={variant_count} must certify fully faithful, same as the 2-variant case"
        );
    }
}

