#[test]
fn umul_overflow_disjunct_grounds_exactly_like_ground_prop() {
    // GUARD (live grounder): the modeled reflected unsigned-MUL overflow disjunct
    // must be the SAME kernel term the LIVE `clean_ground::ground_prop` produces for
    // the REAL emitted `Formula` `Gt(Mul(Var a, Var b), Int(2^32−1))` — so the def-eq
    // link is to the live pipeline (`ground_int (Mul a b) = Int.mul a b`), not a
    // hand-reconstructed fixture. Genuine drift in clean_ground's Mul grounding is
    // caught here.
    use trust_types::Formula as F;
    let env = mirsem_safety_env().expect("env");
    let tc = TypeChecker::new(&env);
    let a = Expr::bvar(1);
    let b = Expr::bvar(0);
    let real = F::Gt(
        Box::new(F::Mul(
            Box::new(F::Var("a".into(), trust_types::Sort::Int)),
            Box::new(F::Var("b".into(), trust_types::Sort::Int)),
        )),
        Box::new(F::Int(UWidth::W32.max_value())),
    );
    let grounded = live_ground(&real, &["a", "b"]);
    let modeled = reflected_umul_overflow_disjunct(&a, &b, UWidth::W32);
    assert!(
        tc.is_def_eq(&modeled, &grounded),
        "the modeled umul overflow disjunct must equal the LIVE grounder's output for `a*b > MAX`"
    );
}

#[test]
fn wrong_head_umul_overflow_claim_fails_closed() {
    // FORGERY PROBE (wrong spec head): CLAIM the u32 reflected unsigned-MUL overflow
    // disjunct equals the ADD spec `uadd_overflows_u32 a b` (whose body heads
    // `Int.add`). The reflected LHS heads `Int.mul` — a DIFFERENT computed result —
    // so the two Prop terms are NOT def-eq and the `Eq.refl` proof is KERNEL-REJECTED.
    // A mul-overflow VC can never be certified against the add spec (or vice versa).
    let a = Expr::bvar(1);
    let b = Expr::bvar(0);
    let wrong_rhs = Expr::apps(cst(&uadd_overflows_name(UWidth::W32)), [a, b]);
    let verdict = check_umul_overflow_adequacy_inner(UWidth::W32, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a mul-VC-reflected-as-add-spec (Int.mul vs Int.add head) claim MUST be \
         kernel-rejected, got {verdict:?}"
    );
}

