#[test]
fn uwidth_from_mir_maps_unsigned_widths_and_fails_closed_otherwise() {
    assert_eq!(UWidth::from_mir(8, false), Some(UWidth::W8));
    assert_eq!(UWidth::from_mir(16, false), Some(UWidth::W16));
    assert_eq!(UWidth::from_mir(32, false), Some(UWidth::W32));
    assert_eq!(UWidth::from_mir(64, false), Some(UWidth::W64));
    // signed is out of the unsigned-overflow fragment
    assert_eq!(UWidth::from_mir(32, true), None);
    // u128 is out of the modeled-literal fragment
    assert_eq!(UWidth::from_mir(128, false), None);
    // The threshold literal matches type_max_formula(w, false) = (1<<w)-1.
    assert_eq!(UWidth::W8.max_value(), 255);
    assert_eq!(UWidth::W32.max_value(), 4_294_967_295);
}

/// `fn uadd(a: u32, b: u32) -> u32 { a + b }` — a u32 add whose result local is
/// u32, so it raises a modeled u32 unsigned-add overflow obligation. Uses
/// `Rvalue::BinaryOp` (the UNCHECKED arithmetic): empirically THIS is the form
/// `trust_vcgen::generate_vcs` raises the `VcKind::ArithmeticOverflow` (Int-path)
/// VC for — `Rvalue::CheckedBinaryOp` is the explicitly-checked form and emits NO
/// implicit overflow VC (the check is the source branch). The metric still keys on
/// both forms (`function_uadd_overflow_widths`), but the emitted-shape end-to-end
/// test must drive the form that actually produces the VC.
fn u32_add_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
        Ty, VerifiableBody, VerifiableFunction,
    };
    let u = || Ty::Int { width: 32, signed: false };
    VerifiableFunction {
        name: "uadd".into(),
        def_path: "crate::uadd".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: u(), name: Some("a".into()) },
                LocalDecl { index: 2, ty: u(), name: Some("b".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Add,
                        Operand::Copy(Place::local(1)),
                        Operand::Copy(Place::local(2)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: u(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn function_safety_vc_faithful_certifies_u32_add() {
    let func = u32_add_func();
    let certs = function_safety_vc_faithful(&func)
        .expect("a u32-add function's overflow VC is certified adequate");
    assert!(!certs.is_empty(), "at least one overflow-adequacy certificate");
    assert!(certs.iter().all(OverflowAdequacyCertificate::is_modulo_3));
    assert!(certs.iter().any(|c| c.width == UWidth::W32));
    // The width detector finds exactly the u32 width.
    assert_eq!(function_uadd_overflow_widths(&func), vec![UWidth::W32]);
}

