#[test]
fn overflow_vc_shape_matches_trust_vcgen_emission() {
    // END-TO-END SHAPE CHECK against the REAL emitter. Build a u32-add function,
    // run `trust_vcgen::generate_vcs`, find the ArithmeticOverflow VC, ground its
    // violation core via the production `ground_prop` path, and confirm the
    // OVERFLOW disjunct it contains is def-eq to the modeled
    // `reflected_overflow_disjunct` — i.e. the adequacy lemma is stated against
    // the shape the emitter+grounder ACTUALLY produce, not an assumed one.
    use trust_types::VcKind;
    let func = u32_add_func();
    let vcs = trust_vcgen::generate_vcs(&func);
    let overflow_vc = vcs
        .iter()
        .find(|vc| matches!(vc.kind, VcKind::ArithmeticOverflow { .. }))
        .expect("a u32-add function must raise an ArithmeticOverflow VC");
    // The emitted formula must contain a `Gt(Add(..), Int(2^32−1))` overflow
    // disjunct (the violation core). Search the formula tree for it and confirm
    // the threshold literal is exactly 2^32−1 (= 4294967295), NOT 2^32.
    assert!(
        formula_has_uadd_overflow_disjunct(&overflow_vc.formula, 4_294_967_295),
        "the emitted u32 overflow VC must carry a `a+b > 2^32−1` disjunct, got {:?}",
        overflow_vc.formula
    );
    // And it must NOT use the off-by-one 2^32 threshold.
    assert!(
        !formula_has_uadd_overflow_disjunct(&overflow_vc.formula, 1i128 << 32),
        "the emitted u32 overflow VC must NOT use the 2^32 (off-by-one) threshold"
    );
}

/// Search a `Formula` tree for an overflow disjunct `Gt(Add(_, _), Int(threshold))`
/// — the unsigned-add overflow violation core trust-vcgen emits. Confirms the VC
/// the adequacy lemma models is the one the emitter produces (with the exact
/// threshold literal).
fn formula_has_uadd_overflow_disjunct(f: &trust_types::Formula, threshold: i128) -> bool {
    use trust_types::Formula as F;
    match f {
        F::Gt(lhs, rhs) => {
            matches!(&**lhs, F::Add(_, _)) && matches!(&**rhs, F::Int(k) if *k == threshold)
        }
        F::And(v) | F::Or(v) => {
            v.iter().any(|x| formula_has_uadd_overflow_disjunct(x, threshold))
        }
        F::Not(a) => formula_has_uadd_overflow_disjunct(a, threshold),
        F::Implies(a, b) | F::Eq(a, b) => {
            formula_has_uadd_overflow_disjunct(a, threshold)
                || formula_has_uadd_overflow_disjunct(b, threshold)
        }
        _ => false,
    }
}

// ---- Step 2H: Lemma 5 — SIGNED add/sub OVERFLOW safety-VC adequacy ----

#[test]
fn signed_overflow_anchor_pins_modulo_3() {
    // The per-(op,width) signed machine-overflow predicates AND the adequacy lemma
    // kernel-check resting on ONLY the 3 foundational axioms (Or/Int.lt/Int.add/
    // Int.sub/Int.ofNat/Int.negSucc are prelude DEFINITIONS). NO 4th axiom.
    assert_eq!(pin_signed_overflow_anchor(), AnchorVerdict::Modulo3);
}

#[test]
fn signed_overflows_type_checks_against_int_to_int_to_prop() {
    let env = mirsem_safety_env().expect("MirSem safety env builds");
    let tc = TypeChecker::new(&env);
    for op in [SignedOp::Add, SignedOp::Sub] {
        let inferred = tc
            .infer_type(&cst(&signed_overflows_name(op, SWidth::W32)))
            .expect("signed_overflows_i32 has a type");
        let bd = || BinderData::from(BinderInfo::Default);
        let expected = Expr::pi(bd(), int_ty(), Expr::pi(bd(), int_ty(), Expr::prop()));
        assert!(
            tc.is_def_eq(&inferred, &expected),
            "s{}_overflows_i32 should have type Int → Int → Prop, got {inferred:?}",
            op.tag()
        );
    }
}

#[test]
fn lemma_5_signed_overflow_adequacy_i32_add_proven_modulo_3() {
    // THE CRUX: the reflected `i32` signed-add out-of-range disjunction
    // `Or([Lt(a+b, -2^31), Gt(a+b, 2^31-1)])`, grounded as
    // `Or (Int.lt (Int.add a b) (Int.negSucc 2147483647)) (Int.lt (Int.ofNat
    // 2147483647) (Int.add a b))`, IS def-eq to the pinned machine signed-overflow
    // condition `sadd_overflows_i32 a b`. Proven modulo 3.
    assert_eq!(
        check_signed_overflow_adequacy(SignedOp::Add, SWidth::W32),
        AdequacyVerdict::ProvenModulo3
    );
}

#[test]
fn lemma_5_signed_overflow_adequacy_all_ops_all_widths_proven_modulo_3() {
    // Both ADD and SUB, at w ∈ {8,16,32,64}, reduce by the same reflexivity — the
    // ±2^(W-1) thresholds are closed Int.ofNat/Int.negSucc literals at each width.
    for op in [SignedOp::Add, SignedOp::Sub] {
        for w in [SWidth::W8, SWidth::W16, SWidth::W32, SWidth::W64] {
            assert_eq!(
                check_signed_overflow_adequacy(op, w),
                AdequacyVerdict::ProvenModulo3,
                "s{}_overflows_i{} adequacy must prove modulo 3",
                op.tag(),
                w.bits()
            );
        }
    }
}

#[test]
fn signed_out_of_range_grounds_exactly_like_ground_prop() {
    // GUARD (live grounder): the modeled reflected signed out-of-range disjunction
    // must equal the LIVE `clean_ground::ground_prop` output for the REAL emitted
    // core `Or([Lt(a+b, -2^31), Gt(a+b, 2^31-1)])`. We INVOKE the live grounder.
    use trust_types::Formula as F;
    let env = mirsem_safety_env().expect("env");
    let tc = TypeChecker::new(&env);
    let a = Expr::bvar(1);
    let b = Expr::bvar(0);
    let real_sum = || {
        F::Add(
            Box::new(F::Var("a".into(), trust_types::Sort::Int)),
            Box::new(F::Var("b".into(), trust_types::Sort::Int)),
        )
    };
    let real = F::Or(vec![
        F::Lt(Box::new(real_sum()), Box::new(F::Int(SWidth::W32.min_value()))),
        F::Gt(Box::new(real_sum()), Box::new(F::Int(SWidth::W32.max_value()))),
    ]);
    let grounded = live_ground(&real, &["a", "b"]);
    let modeled = reflected_signed_out_of_range(SignedOp::Add, &a, &b, SWidth::W32);
    assert!(
        tc.is_def_eq(&modeled, &grounded),
        "the modeled signed out-of-range disjunction must equal the LIVE grounder's output"
    );
}

// ---- Step 2H (soundness): a WRONG signed-overflow claim must NOT prove ----

#[test]
fn wrong_max_threshold_off_by_one_signed_overflow_fails_closed() {
    // OFF-BY-ONE (upper): claim the i32 reflected disjunction equals a spec whose
    // OVERFLOW threshold is 2^31 (= 2147483648), NOT 2^31-1. The closed Int.ofNat
    // literal differs ⇒ NOT def-eq ⇒ Eq.refl KERNEL-REJECTED.
    let a = Expr::bvar(1);
    let b = Expr::bvar(0);
    let sum = || Expr::apps(cst("Int.add"), [a.clone(), b.clone()]);
    let wrong_rhs = Expr::apps(
        cst("Or"),
        [
            Expr::apps(cst("Int.lt"), [sum(), signed_min_expr(SWidth::W32)]),
            // wrong: 2^31 instead of 2^31-1
            Expr::apps(cst("Int.lt"), [int_lit(1i128 << 31), sum()]),
        ],
    );
    let verdict =
        check_signed_overflow_adequacy_inner(SignedOp::Add, SWidth::W32, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong MAX threshold (2^31 vs 2^31-1) claim MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn wrong_min_threshold_off_by_one_signed_overflow_fails_closed() {
    // OFF-BY-ONE (lower): claim the i32 disjunction's UNDERFLOW threshold is
    // -2^31+1 (= -2147483647), NOT -2^31. The closed Int.negSucc literal differs ⇒
    // NOT def-eq ⇒ kernel-rejected. Guards the signed MIN boundary specifically.
    let a = Expr::bvar(1);
    let b = Expr::bvar(0);
    let sum = || Expr::apps(cst("Int.add"), [a.clone(), b.clone()]);
    let wrong_rhs = Expr::apps(
        cst("Or"),
        [
            // wrong: -2^31+1 instead of -2^31
            Expr::apps(cst("Int.lt"), [sum(), int_lit((-(1i128 << 31)) + 1)]),
            Expr::apps(cst("Int.lt"), [signed_max_expr(SWidth::W32), sum()]),
        ],
    );
    let verdict =
        check_signed_overflow_adequacy_inner(SignedOp::Add, SWidth::W32, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong MIN threshold (-2^31+1 vs -2^31) claim MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn dropped_underflow_disjunct_signed_overflow_fails_closed() {
    // DROP-DISJUNCT CRUX: claim the i32 signed-add disjunction equals ONLY the
    // overflow half `Int.lt (Int.ofNat 2^31-1) (Int.add a b)` (the unsigned shape),
    // dropping the live underflow disjunct. `Or p q` is NOT def-eq to `q` ⇒
    // kernel-rejected. This is the crux: for SIGNED arithmetic BOTH disjuncts are
    // load-bearing, and dropping the underflow check must fail closed.
    let a = Expr::bvar(1);
    let b = Expr::bvar(0);
    let sum = Expr::apps(cst("Int.add"), [a, b]);
    // wrong: just the overflow disjunct, no `Or`, no underflow check.
    let wrong_rhs = Expr::apps(cst("Int.lt"), [signed_max_expr(SWidth::W32), sum]);
    let verdict =
        check_signed_overflow_adequacy_inner(SignedOp::Add, SWidth::W32, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "dropping the underflow disjunct MUST be kernel-rejected, got {verdict:?}"
    );
}

