#[test]
fn swidth_from_mir_maps_signed_widths_and_fails_closed_otherwise() {
    assert_eq!(SWidth::from_mir(8, true), Some(SWidth::W8));
    assert_eq!(SWidth::from_mir(16, true), Some(SWidth::W16));
    assert_eq!(SWidth::from_mir(32, true), Some(SWidth::W32));
    assert_eq!(SWidth::from_mir(64, true), Some(SWidth::W64));
    // unsigned is out of the SIGNED-overflow fragment
    assert_eq!(SWidth::from_mir(32, false), None);
    // i128 is out of the modeled-literal fragment
    assert_eq!(SWidth::from_mir(128, true), None);
    // The thresholds match signed_min/signed_max = ∓(1<<(w-1)).
    assert_eq!(SWidth::W8.min_value(), -128);
    assert_eq!(SWidth::W8.max_value(), 127);
    assert_eq!(SWidth::W32.min_value(), -2_147_483_648);
    assert_eq!(SWidth::W32.max_value(), 2_147_483_647);
}

/// `fn sadd(a: i32, b: i32) -> i32 { a + b }` — a signed i32 add (UNCHECKED
/// `Rvalue::BinaryOp`, the form that empirically raises the `ArithmeticOverflow`
/// Int-path VC). Its result local is i32, so the emitter raises a signed i32 add
/// overflow obligation (the FULL out-of-range disjunction).
fn i32_add_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
        Ty, VerifiableBody, VerifiableFunction,
    };
    let i = || Ty::Int { width: 32, signed: true };
    VerifiableFunction {
        name: "sadd".into(),
        def_path: "crate::sadd".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: i(), name: Some("a".into()) },
                LocalDecl { index: 2, ty: i(), name: Some("b".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Add,
                        Operand::Copy(Place::local(1)),
                        Operand::Copy(Place::local(2)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: i(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn function_safety_vcs_faithful_certifies_i32_add_signed_overflow() {
    // `fn sadd(a: i32, b: i32) { a + b }` — its ONLY safety VC is the signed-add
    // i32 overflow (Lemma 5), now MODELED and certified modulo 3. NO regression to
    // unsigned/bounds/div (those stay empty/None).
    let func = i32_add_func();
    let certs = function_safety_vcs_faithful(&func)
        .expect("an i32-add function's signed overflow VC is certified adequate");
    assert!(certs.any(), "at least one modeled safety VC certified");
    assert!(certs.all_modulo_3());
    assert!(
        certs
            .signed_overflow
            .iter()
            .any(|c| c.kind == SafetyVcKind::SignedOverflow(SignedOp::Add, SWidth::W32)),
        "the certified safety VC is the i32 signed-add overflow"
    );
    // No regression: the UNSIGNED-overflow axis is untouched by a signed function.
    assert!(certs.overflow.is_empty(), "no unsigned-add overflow cert for a signed add");
    assert!(certs.bounds.is_none() && certs.div.is_none());
}

#[test]
fn signed_overflow_vc_modeled_classifies_signed_add_sub_mul() {
    use trust_types::{BinOp, Ty, VcKind};
    let i32t = Ty::Int { width: 32, signed: true };
    let u32t = Ty::Int { width: 32, signed: false };
    // signed i32 add ⇒ modeled (Add, W32).
    assert_eq!(
        signed_overflow_vc_modeled(&VcKind::ArithmeticOverflow {
            op: BinOp::Add,
            operand_tys: (i32t.clone(), i32t.clone()),
        }),
        Some((SignedOp::Add, SWidth::W32))
    );
    // signed i32 sub ⇒ modeled (Sub, W32).
    assert_eq!(
        signed_overflow_vc_modeled(&VcKind::ArithmeticOverflow {
            op: BinOp::Sub,
            operand_tys: (i32t.clone(), i32t.clone()),
        }),
        Some((SignedOp::Sub, SWidth::W32))
    );
    // signed i32 MUL ⇒ now KIND-modeled (Mul, W32). This is necessary-not-sufficient:
    // the LOAD-BEARING gate is the formula-aware def-eq bridge, which certifies only the
    // LIA constant-multiplier shape and declines a var*var BV mul (see
    // `signed_mul_fails_closed_deferred_gap`). The kind classification itself is `Some`.
    assert_eq!(
        signed_overflow_vc_modeled(&VcKind::ArithmeticOverflow {
            op: BinOp::Mul,
            operand_tys: (i32t.clone(), i32t.clone()),
        }),
        Some((SignedOp::Mul, SWidth::W32))
    );
    // UNSIGNED add/mul ⇒ not a signed shape (None here; both operands must be signed).
    assert_eq!(
        signed_overflow_vc_modeled(&VcKind::ArithmeticOverflow {
            op: BinOp::Add,
            operand_tys: (u32t.clone(), u32t.clone()),
        }),
        None
    );
    assert_eq!(
        signed_overflow_vc_modeled(&VcKind::ArithmeticOverflow {
            op: BinOp::Mul,
            operand_tys: (u32t.clone(), u32t),
        }),
        None
    );
    // i128 signed add ⇒ unmodeled width.
    let i128t = Ty::Int { width: 128, signed: true };
    assert_eq!(
        signed_overflow_vc_modeled(&VcKind::ArithmeticOverflow {
            op: BinOp::Add,
            operand_tys: (i128t.clone(), i128t),
        }),
        None
    );
}

#[test]
fn signed_mul_fails_closed_deferred_gap() {
    // HONEST DEFERRED GAP (var*var BV path): a signed i32 MUL `fn smul(a,b){ a*b }`
    // raises an ArithmeticOverflow{op:Mul} VC that the emitter models with BITVECTOR
    // reasoning (BvMul/BvSignExt/BvExtract) — NOT a clean LIA out-of-range
    // disjunction. Lemma 5's MUL spec heads `Int.mul`, so the VcKind is now MODELED
    // (kind-level), but the LOAD-BEARING gate is the formula-aware def-eq bridge:
    // a BV-shaped VC has no `Or([Lt(Mul…),Gt(Mul…)])` leaf, so the bridge DECLINES
    // and the function STILL FAILS CLOSED (we do not fake a var*var multiply
    // adequacy). The const-multiplier LIA mul IS certified (separate Int-path shape).
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
        Ty, VcKind, VerifiableBody, VerifiableFunction,
    };
    let i = || Ty::Int { width: 32, signed: true };
    let func = VerifiableFunction {
        name: "smul".into(),
        def_path: "crate::smul".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: i(), name: Some("a".into()) },
                LocalDecl { index: 2, ty: i(), name: Some("b".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Mul,
                        Operand::Copy(Place::local(1)),
                        Operand::Copy(Place::local(2)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: i(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    // The emitter DOES raise a signed-mul ArithmeticOverflow VC.
    let vcs = trust_vcgen::generate_vcs(&func);
    assert!(
        vcs.iter()
            .any(|vc| matches!(&vc.kind, VcKind::ArithmeticOverflow { op: BinOp::Mul, .. })),
        "a signed i32 mul raises an ArithmeticOverflow{{op:Mul}} VC"
    );
    // The var*var signed-mul VcKind is now KIND-modeled (Lemma 5's MUL spec), so it
    // is NOT flagged unmodeled at the kind level …
    assert!(
        !function_emits_unmodeled_safety_vc(&func),
        "signed-mul is now a kind-modeled ArithmeticOverflow (Lemma 5 MUL spec)"
    );
    // … but the LOAD-BEARING formula-aware bridge DECLINES the BITVECTOR shape, so
    // the function STILL fails closed — the deferred var*var gap is preserved SOUNDLY
    // (no false faithfulness certificate is ever minted for a BV mul VC).
    assert!(
        function_safety_vcs_faithful(&func).is_none(),
        "a var*var signed-mul function must fail closed — the formula-aware bridge \
         declines its bitvector overflow VC"
    );
}

#[test]
fn signed_overflow_vc_shape_matches_trust_vcgen_emission() {
    // END-TO-END SHAPE CHECK against the REAL emitter. Build an i32-add function,
    // run `trust_vcgen::generate_vcs`, find the ArithmeticOverflow VC, and confirm
    // its violation core carries the FULL out-of-range disjunction
    // `Or([Lt(Add(..), Int(-2^31)), Gt(Add(..), Int(2^31-1))])` — BOTH disjuncts,
    // with the exact ±2^31 boundary literals (NOT the off-by-one 2^31). I.e. the
    // adequacy lemma is stated against the shape the emitter ACTUALLY produces.
    use trust_types::VcKind;
    let func = i32_add_func();
    let vcs = trust_vcgen::generate_vcs(&func);
    let overflow_vc = vcs
        .iter()
        .find(|vc| {
            matches!(vc.kind, VcKind::ArithmeticOverflow { op: trust_types::BinOp::Add, .. })
        })
        .expect("an i32-add function must raise an ArithmeticOverflow VC");
    // BOTH disjuncts present with exact boundary literals.
    assert!(
        formula_has_sadd_overflow_disjunct(&overflow_vc.formula, 2_147_483_647),
        "the emitted i32 overflow VC must carry a `a+b > 2^31-1` disjunct, got {:?}",
        overflow_vc.formula
    );
    assert!(
        formula_has_sadd_underflow_disjunct(&overflow_vc.formula, -2_147_483_648),
        "the emitted i32 overflow VC must carry a `a+b < -2^31` disjunct (signed underflow)"
    );
    // It must NOT use the off-by-one 2^31 threshold on the upper bound.
    assert!(
        !formula_has_sadd_overflow_disjunct(&overflow_vc.formula, 1i128 << 31),
        "the emitted i32 overflow VC must NOT use the 2^31 (off-by-one) upper threshold"
    );
}

/// Search a `Formula` tree for the signed-add OVERFLOW disjunct
/// `Gt(Add(_, _), Int(max))` — the upper out-of-range half.
fn formula_has_sadd_overflow_disjunct(f: &trust_types::Formula, max: i128) -> bool {
    use trust_types::Formula as F;
    match f {
        F::Gt(lhs, rhs) => {
            matches!(&**lhs, F::Add(_, _)) && matches!(&**rhs, F::Int(k) if *k == max)
        }
        F::And(v) | F::Or(v) => v.iter().any(|x| formula_has_sadd_overflow_disjunct(x, max)),
        F::Not(a) => formula_has_sadd_overflow_disjunct(a, max),
        F::Implies(a, b) | F::Eq(a, b) => {
            formula_has_sadd_overflow_disjunct(a, max)
                || formula_has_sadd_overflow_disjunct(b, max)
        }
        _ => false,
    }
}

/// Search a `Formula` tree for the signed-add UNDERFLOW disjunct
/// `Lt(Add(_, _), Int(min))` — the lower out-of-range half (the LIVE disjunct that
/// distinguishes the signed VC from the unsigned one).
fn formula_has_sadd_underflow_disjunct(f: &trust_types::Formula, min: i128) -> bool {
    use trust_types::Formula as F;
    match f {
        F::Lt(lhs, rhs) => {
            matches!(&**lhs, F::Add(_, _)) && matches!(&**rhs, F::Int(k) if *k == min)
        }
        F::And(v) | F::Or(v) => v.iter().any(|x| formula_has_sadd_underflow_disjunct(x, min)),
        F::Not(a) => formula_has_sadd_underflow_disjunct(a, min),
        F::Implies(a, b) | F::Eq(a, b) => {
            formula_has_sadd_underflow_disjunct(a, min)
                || formula_has_sadd_underflow_disjunct(b, min)
        }
        _ => false,
    }
}

// ---- Step 2I: Lemma 6 — signed NEGATION-overflow safety-VC adequacy ----

/// `fn neg(x: iW) -> iW { -x }` — a signed `UnaryOp(Neg)` whose operand is iW, so
/// the emitter raises a `NegationOverflow{ty: iW}` VC (core `Eq(x, MIN)`).
