#[test]
fn lemma_6_negation_adequacy_i32_proven_modulo_3() {
    // THE CRUX: the reflected negation core `Eq(x, Int(-2^31))`, grounded as
    // `@Eq Int x (Int.negSucc 2147483647)`, IS def-eq to the pinned condition
    // `neg_overflows_i32 x` (= `x = -2^31`). Proven modulo 3.
    assert_eq!(check_neg_overflow_adequacy(SWidth::W32), AdequacyVerdict::ProvenModulo3);
}

