#[test]
fn negation_vc_shape_matches_trust_vcgen_emission() {
    // END-TO-END SHAPE CHECK against the REAL emitter. Build a `-x` i32 function,
    // run `trust_vcgen::generate_vcs`, find the NegationOverflow VC, and confirm its
    // violation core carries the equality `Eq(Var x, Int(-2^31))` with the exact MIN
    // boundary literal (NOT the off-by-one MIN+1). I.e. the adequacy lemma is stated
    // against the shape the emitter ACTUALLY produces.
    use trust_types::VcKind;
    let func = neg_func(32);
    let vcs = trust_vcgen::generate_vcs(&func);
    let neg_vc = vcs
        .iter()
        .find(|vc| matches!(vc.kind, VcKind::NegationOverflow { .. }))
        .expect("a `-x` i32 function must raise a NegationOverflow VC");
    assert!(
        formula_has_neg_overflow_core(&neg_vc.formula, -2_147_483_648),
        "the emitted i32 negation VC must carry an `x = -2^31` equality, got {:?}",
        neg_vc.formula
    );
    // It must NOT use the off-by-one MIN+1 threshold.
    assert!(
        !formula_has_neg_overflow_core(&neg_vc.formula, -2_147_483_647),
        "the emitted i32 negation VC must NOT use the -2^31+1 (off-by-one) threshold"
    );
}

/// Search a `Formula` tree for the negation-overflow core `Eq(Var(_), Int(min))`.
fn formula_has_neg_overflow_core(f: &trust_types::Formula, min: i128) -> bool {
    use trust_types::Formula as F;
    match f {
        F::Eq(lhs, rhs) => {
            matches!(&**lhs, F::Var(_, _)) && matches!(&**rhs, F::Int(k) if *k == min)
        }
        F::And(v) | F::Or(v) => v.iter().any(|x| formula_has_neg_overflow_core(x, min)),
        F::Not(a) => formula_has_neg_overflow_core(a, min),
        F::Implies(a, b) => {
            formula_has_neg_overflow_core(a, min) || formula_has_neg_overflow_core(b, min)
        }
        _ => false,
    }
}

#[test]
fn function_safety_vcs_faithful_certifies_i32_negation() {
    // `fn neg(x: i32) { -x }` — its ONLY safety VC is the i32 negation overflow
    // (Lemma 6), now MODELED and certified modulo 3. NO regression to other kinds.
    let func = neg_func(32);
    let certs = function_safety_vcs_faithful(&func)
        .expect("an i32-negation function's negation VC is certified adequate");
    assert!(certs.any(), "at least one modeled safety VC certified");
    assert!(certs.all_modulo_3());
    assert!(
        certs.negation.iter().any(|c| c.kind == SafetyVcKind::NegationOverflow(SWidth::W32)),
        "the certified safety VC is the i32 negation overflow"
    );
    assert!(certs.overflow.is_empty() && certs.signed_overflow.is_empty());
    assert!(certs.bounds.is_none() && certs.div.is_none() && certs.shift.is_empty());
}

#[test]
fn i32_negation_safety_vc_certifies_but_unaryop_return_not_yet_whole_function() {
    // `fn neg(x: i32) { -x }`: its only SAFETY VC is the i32 negation overflow,
    // modeled+certified modulo 3 by Lemma 6 ⇒ the SAFETY-VC tier closes. HONEST
    // SCOPE: the orthogonal whole-function CONTRACT tier (Lemma 1A/1B/1C) does NOT
    // yet model a `UnaryOp(Neg)` return rvalue (`sem_rvalue_of_mir` covers only
    // Use/Add/Sub/Mul), so the composed contract witness fail-closes and the
    // function is NOT (yet) FULLY FAITHFUL. The metric correctly does NOT over-claim.
    let func = neg_func(32);
    // The negation safety VC certifies modulo 3 (the Lemma-6 win).
    assert!(function_safety_vcs_faithful(&func).is_some_and(|c| c.all_modulo_3()));
    // No UNMODELED safety VC is emitted (the only safety VC is the modeled negation).
    assert!(!function_emits_unmodeled_safety_vc(&func));
    // But the whole-function FULLY-FAITHFUL witness is NOT minted: the `Neg` return
    // is outside the modeled contract fragment, so it fail-closes (no over-claim).
    assert!(
        function_fully_faithful_witness(&func).is_none(),
        "a UnaryOp(Neg) return is not in the modeled contract fragment ⇒ no whole-function \
         witness (the SAFETY-VC tier still certifies; this is honest scope, not a regression)"
    );
}

// ---- Step 2J: Lemma 7 — SHIFT-amount-OOB safety-VC adequacy ----

/// `fn shf(x: vW, n: aW) -> vW { x op n }` — a `BinaryOp(Shl|Shr)` whose value is
/// vW and amount is aW, so the emitter raises a `ShiftOverflow` VC (core `Ge(n,W)`).
fn shift_func(
    op: trust_types::BinOp,
    value_width: u32,
    value_signed: bool,
    amount_signed: bool,
) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator, Ty,
        VerifiableBody, VerifiableFunction,
    };
    let val_ty = Ty::Int { width: value_width, signed: value_signed };
    let amt_ty = Ty::Int { width: 32, signed: amount_signed };
    VerifiableFunction {
        name: "shf".into(),
        def_path: "crate::shf".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: val_ty.clone(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: val_ty.clone(), name: Some("x".into()) },
                LocalDecl { index: 2, ty: amt_ty, name: Some("n".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        op,
                        Operand::Copy(Place::local(1)),
                        Operand::Copy(Place::local(2)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: val_ty,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

