// ---- Step 2J (soundness): a WRONG shift claim must NOT prove (fail-closed) ----

#[test]
fn wrong_strict_vs_nonstrict_shift_claim_fails_closed() {
    // THE OFF-BY-ONE CRUX (`<` vs `≤`). CLAIM: the i32 shift core equals
    // `Int.lt (Int.ofNat 32) n` (`32 < n`, i.e. W < n) instead of `Int.le (Int.ofNat
    // 32) n` (`32 ≤ n`, i.e. W ≤ n). Shifting by EXACTLY W is UB, so `W ≤ n` is
    // load-bearing; `W < n` would WRONGLY allow `n = W`. Different Prop ⇒
    // kernel-rejected.
    let n = Expr::bvar(0);
    let wrong_rhs = Expr::apps(cst("Int.lt"), [shift_width_expr(ShiftWidth::W32), n]);
    let verdict = check_shift_oob_adequacy_inner(ShiftWidth::W32, false, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a `W < n` vs `W ≤ n` off-by-one shift claim MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn wrong_width_w_minus_one_shift_claim_fails_closed() {
    // CLAIM: the i32 shift core equals `Int.le (Int.ofNat 31) n` (`W−1 ≤ n`, i.e.
    // threshold 31 not 32). Shifting by 31 on a 32-bit value is VALID, so a `31 ≤ n`
    // threshold would WRONGLY flag it. Different closed literal ⇒ kernel-rejected.
    let n = Expr::bvar(0);
    let wrong_rhs = Expr::apps(cst("Int.le"), [int_lit(31), n]);
    let verdict = check_shift_oob_adequacy_inner(ShiftWidth::W32, false, Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a W−1 (31 vs 32) threshold shift claim MUST be kernel-rejected, got {verdict:?}"
    );
}

