#[test]
fn shift_vc_shape_matches_trust_vcgen_emission() {
    // END-TO-END SHAPE CHECK against the REAL emitter. Build `x:u32 << n:u32`, run
    // `trust_vcgen::generate_vcs`, find the ShiftOverflow VC, and confirm its
    // violation core carries the disjunct `Ge(Var n, Int(32))` (W = the 32-bit value
    // width), NOT the off-by-one 31. The adequacy lemma is stated against the shape
    // the emitter ACTUALLY produces.
    use trust_types::{BinOp, VcKind};
    let func = shift_func(BinOp::Shl, 32, false, false);
    let vcs = trust_vcgen::generate_vcs(&func);
    let shift_vc = vcs
        .iter()
        .find(|vc| matches!(vc.kind, VcKind::ShiftOverflow { .. }))
        .expect("a `x << n` u32 function must raise a ShiftOverflow VC");
    assert!(
        formula_has_shift_oob_core(&shift_vc.formula, 32),
        "the emitted u32 shift VC must carry an `n ≥ 32` disjunct, got {:?}",
        shift_vc.formula
    );
    // It must NOT use the off-by-one 31 threshold.
    assert!(
        !formula_has_shift_oob_core(&shift_vc.formula, 31),
        "the emitted u32 shift VC must NOT use the 31 (W−1 off-by-one) threshold"
    );
}

/// Search a `Formula` tree for the shift-amount-OOB core `Ge(Var(_), Int(w))`.
fn formula_has_shift_oob_core(f: &trust_types::Formula, w: i128) -> bool {
    use trust_types::Formula as F;
    match f {
        F::Ge(lhs, rhs) => {
            matches!(&**lhs, F::Var(_, _)) && matches!(&**rhs, F::Int(k) if *k == w)
        }
        F::And(v) | F::Or(v) => v.iter().any(|x| formula_has_shift_oob_core(x, w)),
        F::Not(a) => formula_has_shift_oob_core(a, w),
        F::Implies(a, b) => {
            formula_has_shift_oob_core(a, w) || formula_has_shift_oob_core(b, w)
        }
        _ => false,
    }
}

#[test]
fn function_safety_vcs_faithful_certifies_u32_shift() {
    // `fn shf(x: u32, n: u32) { x << n }` — its ONLY safety VC is the u32 shift-OOB
    // (Lemma 7), now MODELED and certified modulo 3. NO regression to other kinds.
    use trust_types::BinOp;
    let func = shift_func(BinOp::Shl, 32, false, false);
    let certs = function_safety_vcs_faithful(&func)
        .expect("a u32-shift function's shift VC is certified adequate");
    assert!(certs.any(), "at least one modeled safety VC certified");
    assert!(certs.all_modulo_3());
    assert!(
        certs.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W32, false)),
        "the certified safety VC is the u32 shift-amount OOB"
    );
    assert!(certs.overflow.is_empty() && certs.signed_overflow.is_empty());
    assert!(certs.bounds.is_none() && certs.div.is_none() && certs.negation.is_empty());
}

/// Trust: 128-BIT SHIFT VC WIDTH residue closure — the same end-to-end
/// certification at the 128-bit value widths, on the REAL emitter output.
/// `u128 << n:u32` certifies ShiftOob(W128, unsigned); `i128 << n:i32`
/// certifies ShiftOob(W128, signed) — each with the emitted `n ≥ 128`
/// threshold (never a truncated/fabricated 64).
#[test]
fn function_safety_vcs_faithful_certifies_128bit_shift() {
    use trust_types::BinOp;
    // u128 value, unsigned amount.
    let func_u = shift_func(BinOp::Shl, 128, false, false);
    let vcs = trust_vcgen::generate_vcs(&func_u);
    let shift_vc = vcs
        .iter()
        .find(|vc| matches!(vc.kind, trust_types::VcKind::ShiftOverflow { .. }))
        .expect("a u128-shift function must raise a ShiftOverflow VC");
    assert!(
        formula_has_shift_oob_core(&shift_vc.formula, 128),
        "the emitted u128 shift VC must carry the full `n ≥ 128` disjunct, got {:?}",
        shift_vc.formula
    );
    assert!(
        !formula_has_shift_oob_core(&shift_vc.formula, 64),
        "the u128 threshold must never be a truncated/fabricated 64"
    );
    let certs = function_safety_vcs_faithful(&func_u)
        .expect("a u128-shift function's shift VC is certified adequate");
    assert!(certs.all_modulo_3());
    assert!(
        certs.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W128, false)),
        "the certified safety VC is the width-128 shift-amount OOB, got {:?}",
        certs.shift.iter().map(|c| c.kind.clone()).collect::<Vec<_>>()
    );
    // i128 value, SIGNED amount (adds the `n < 0` disjunct).
    let func_s = shift_func(BinOp::Shl, 128, true, true);
    let certs_s = function_safety_vcs_faithful(&func_s)
        .expect("an i128-shift function's shift VC is certified adequate");
    assert!(certs_s.all_modulo_3());
    assert!(
        certs_s.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W128, true)),
        "the certified safety VC is the width-128 SIGNED-amount shift OOB, got {:?}",
        certs_s.shift.iter().map(|c| c.kind.clone()).collect::<Vec<_>>()
    );
}

/// Build `fn cshf(n) -> i32 { 1i32 << n }` — a CONSTANT shifted value. The emitter
/// FABRICATES `operand_ty = i64` for the `1i32` constant at extraction, so the OLD
/// `shift_vc_modeled(&vc.kind)` (which read `operand_ty`) classified W64 — yet the
/// emitter's UB threshold is the DEST/result width 32 (`n ≥ 32`). The amount type is
/// configurable.
fn const_shift_func(amount_signed: bool) -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let i32t = || Ty::Int { width: 32, signed: true };
    let amt_ty = Ty::Int { width: 32, signed: amount_signed };
    VerifiableFunction {
        name: "cshf".into(),
        def_path: "crate::cshf".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i32t(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: amt_ty, name: Some("n".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Shl,
                        Operand::Constant(ConstValue::Int(1)),
                        Operand::Copy(Place::local(1)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: i32t(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn const_shift_does_not_receive_false_64_width_cert() {
    // THE FALSE-CERTIFICATE PROBE (CRITICAL — the shift desync). For `1i32 << n` the
    // emitter records `operand_ty = i64` (a FABRICATED width-64) but emits the UB
    // threshold `n ≥ 32` (the dest/result width). The OLD apparatus read the width
    // from `operand_ty` and minted a W64 cert — claiming the discharge refutes
    // `64 ≤ n` while it actually refutes `n ≥ 32`, a FALSE faithfulness cert over a
    // reachable `n ∈ [32, 64)` UB shift.
    //
    // The FORMULA-AWARE certifier reads the width from the EMITTED `Ge(n, Int(32))`
    // threshold and grounds the REAL core through the LIVE grounder, so it mints the
    // CORRECT W32 cert (matching the emitted threshold) and NEVER a W64 one.
    use trust_types::VcKind;
    let func = const_shift_func(false);

    // The emitted VC's kind STILL carries the fabricated i64 operand_ty (the emitter
    // bug is real and orthogonal); confirm the desync exists at the source.
    let vcs = trust_vcgen::generate_vcs(&func);
    let shift_vc = vcs
        .iter()
        .find(|vc| matches!(vc.kind, VcKind::ShiftOverflow { .. }))
        .expect("a `1i32 << n` function raises a ShiftOverflow VC");
    assert_eq!(
        shift_vc_modeled(&shift_vc.kind),
        Some((ShiftWidth::W64, false)),
        "the OLD operand_ty-driven classifier reads the FABRICATED W64 — the desync source"
    );
    assert!(
        formula_has_shift_oob_core(&shift_vc.formula, 32),
        "but the EMITTED threshold is `n ≥ 32` (the dest width), got {:?}",
        shift_vc.formula
    );

    // THE FIX: the function's shift cert is the CORRECT W32 (from the formula), and
    // NEVER a false W64.
    let certs = function_safety_vcs_faithful(&func)
        .expect("the const-shift function certifies at the CORRECT width");
    assert!(certs.all_modulo_3());
    assert!(
        certs.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W32, false)),
        "the const-shift cert must be W32 (the emitted threshold), got {:?}",
        certs.shift.iter().map(|c| c.kind.clone()).collect::<Vec<_>>()
    );
    assert!(
        !certs.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W64, false)),
        "NO false W64 cert may be minted for `1i32 << n` (the emitter refutes `n ≥ 32`, not `64 ≤ n`)"
    );
}

#[test]
fn const_shift_signed_amount_uses_correct_width() {
    // The SIGNED-amount const shift `1i32 << n:i32` likewise certifies at the CORRECT
    // W32 (emitted threshold), with the `n < 0` disjunct — and NEVER a W64 cert. The
    // formula-aware path reads W from the emitted `Ge(n, Int(32))`, not operand_ty.
    let func = const_shift_func(true);
    let certs = function_safety_vcs_faithful(&func)
        .expect("the signed-amount const-shift certifies at the correct width");
    assert!(certs.all_modulo_3());
    assert!(
        certs.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W32, true)),
        "the signed-amount const-shift cert must be W32 (signed), got {:?}",
        certs.shift.iter().map(|c| c.kind.clone()).collect::<Vec<_>>()
    );
    assert!(
        !certs
            .shift
            .iter()
            .any(|c| matches!(c.kind, SafetyVcKind::ShiftOob(ShiftWidth::W64, _))),
        "NO false W64 cert for the signed-amount const-shift either"
    );
}

#[test]
fn formula_aware_bridge_rejects_wrong_width_spec() {
    // ADVERSARIAL: the formula-aware bridge MUST fail closed when the live-grounded
    // emitted core is NOT def-eq to the claimed spec. Here we ground the REAL shift
    // core `Ge(n, Int(32))` (→ `Int.le (Int.ofNat 32) n`) but claim the W64 spec
    // `shift_amount_oob_64 n` (= `Int.le (Int.ofNat 64) n`). They are DIFFERENT Props,
    // so `live_ground_def_eq_spec` must return FALSE — exactly the gate that blocks
    // the `1i32<<n` false 64-cert.
    use trust_types::Formula as F;
    let real_core =
        F::Ge(Box::new(F::Var("n".into(), trust_types::Sort::Int)), Box::new(F::Int(32)));
    let mut params = std::collections::HashMap::new();
    params.insert("n".to_string(), Expr::bvar(0));
    let cg = CoreGround { core: &real_core, params };
    // WRONG spec: the W64 threshold (the false-cert the desync used to mint).
    let wrong_spec =
        Expr::app(cst(&shift_amount_oob_name(ShiftWidth::W64, false)), Expr::bvar(0));
    assert!(
        !live_ground_def_eq_spec(&cg, &wrong_spec, 1),
        "the bridge must REJECT grounding `n ≥ 32` against the W64 spec `64 ≤ n`"
    );
    // SANITY: the CORRECT W32 spec IS accepted (the bridge is not vacuously false).
    let right_spec =
        Expr::app(cst(&shift_amount_oob_name(ShiftWidth::W32, false)), Expr::bvar(0));
    assert!(
        live_ground_def_eq_spec(&cg, &right_spec, 1),
        "the bridge must ACCEPT grounding `n ≥ 32` against the W32 spec `32 ≤ n`"
    );
}

#[test]
fn formula_aware_path_certifies_overflow_family_from_real_emitted_vc() {
    // END-TO-END (formula-aware): drive the REAL emitter for each overflow-family
    // fixture, find its arithmetic/negation VC, and confirm `safety_vc_is_faithful_
    // formula_aware` mints the EXPECTED (kind, ProvenModulo3) by live-grounding the
    // ACTUAL emitted `vc.formula` — not a hand-built core. This is the bridge: the
    // certified term IS the live-grounded emitted formula, def-eq to the spec.
    use trust_types::VcKind as K;
    let cases: [(trust_types::VerifiableFunction, SafetyVcKind); 4] = [
        (u32_add_func(), SafetyVcKind::Overflow(UWidth::W32)),
        (i32_add_func(), SafetyVcKind::SignedOverflow(SignedOp::Add, SWidth::W32)),
        (u32_sub_func(), SafetyVcKind::UnsignedSubUnderflow(UWidth::W32)),
        (neg_func(32), SafetyVcKind::NegationOverflow(SWidth::W32)),
    ];
    for (func, expect) in cases {
        let vcs = trust_vcgen::generate_vcs(&func);
        let vc = vcs
            .iter()
            .find(|vc| {
                matches!(vc.kind, K::ArithmeticOverflow { .. } | K::NegationOverflow { .. })
            })
            .expect("an overflow-family fixture raises an arithmetic/negation VC");
        let (kind, verdict) = safety_vc_is_faithful_formula_aware(&func, vc)
            .expect("the formula-aware path must certify the real emitted overflow-family VC");
        assert_eq!(kind, expect, "the formula-aware kind+width must match");
        assert_eq!(verdict, AdequacyVerdict::ProvenModulo3);
    }
}

#[test]
fn formula_aware_certifies_overflow_with_constant_operand() {
    // `fn bump(x: i32) { x + 1 }` — one operand is a CONSTANT. The emitted core is
    // `Or([Lt(Add(x,1),MIN), Gt(Add(x,1),MAX)])`, where `1` is `Int(1)`, NOT a Var.
    // The formula-aware bridge grounds `1` directly to a closed literal (no binder)
    // through the SAME live `ground_int`, so `sadd_overflows_i32 x 1` is def-eq to the
    // live-grounded core — the bridge closes for mixed const operands too, not just
    // `x + y`. (Guards the `x + 1` regression: a Var-only operand fragment would have
    // fail-closed `bump`, dropping the safe-corpus signed-overflow cert.)
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let i = || Ty::Int { width: 32, signed: true };
    let func = VerifiableFunction {
        name: "bump".into(),
        def_path: "crate::bump".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: i(), name: Some("x".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Add,
                        Operand::Copy(Place::local(1)),
                        Operand::Constant(ConstValue::Int(1)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: i(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    let certs = function_safety_vcs_faithful(&func)
        .expect("`x + 1` signed overflow VC must certify (const operand grounds live)");
    assert!(certs.all_modulo_3());
    assert!(
        certs
            .signed_overflow
            .iter()
            .any(|c| c.kind == SafetyVcKind::SignedOverflow(SignedOp::Add, SWidth::W32)),
        "the const-operand `x + 1` certifies as a signed i32 overflow"
    );
}

#[test]
fn formula_aware_bridge_rejects_wrong_width_unsigned_overflow_spec() {
    // ADVERSARIAL (Lemma 2, formula-aware): the unsigned-add OVERFLOW bridge MUST
    // fail closed when the live-grounded emitted overflow disjunct is NOT def-eq to
    // the claimed spec. Ground the REAL u32 overflow disjunct `Gt(Add(a,b),
    // Int(2^32−1))` (→ `Int.lt (Int.ofNat 4294967295) (Int.add a b)`) but claim the
    // u16 spec `uadd_overflows_u16 a b` (threshold 2^16−1). DIFFERENT closed literals
    // ⇒ NOT def-eq ⇒ REJECTED. Also a constant-FOLDED form (threshold 2^32, the
    // off-by-one) must fail closed.
    use trust_types::Formula as F;
    let a = F::Var("a".into(), trust_types::Sort::Int);
    let b = F::Var("b".into(), trust_types::Sort::Int);
    let core = F::Gt(
        Box::new(F::Add(Box::new(a.clone()), Box::new(b.clone()))),
        Box::new(F::Int(UWidth::W32.max_value())),
    );
    // WRONG width spec: u16 (2^16−1).
    let wrong = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        Expr::apps(cst(&uadd_overflows_name(UWidth::W16)), [ops[0].clone(), ops[1].clone()])
    });
    assert!(!wrong, "grounding a u32 overflow core against the u16 spec MUST be rejected");
    // WRONG (constant-folded/off-by-one) spec: threshold 2^32 instead of 2^32−1.
    let off_by_one = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        let sum = Expr::apps(cst("Int.add"), [ops[0].clone(), ops[1].clone()]);
        Expr::apps(cst("Int.lt"), [int_lit(1i128 << 32), sum])
    });
    assert!(!off_by_one, "an off-by-one (2^32) overflow spec MUST be rejected (no false cert)");
    // SANITY: the CORRECT u32 spec IS accepted (the bridge is not vacuously false).
    let right = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        Expr::apps(cst(&uadd_overflows_name(UWidth::W32)), [ops[0].clone(), ops[1].clone()])
    });
    assert!(right, "the correct u32 overflow spec MUST be accepted");
}

#[test]
fn formula_aware_bridge_rejects_wrong_spec_signed_overflow() {
    // ADVERSARIAL (Lemma 5, formula-aware): the signed out-of-range bridge MUST fail
    // closed for a wrong-WIDTH spec (i32 core vs i16 spec) AND a DROPPED-disjunct
    // (constant-reassociated) form claiming only the overflow half — for SIGNED
    // arithmetic BOTH disjuncts are load-bearing.
    use trust_types::Formula as F;
    let a = F::Var("a".into(), trust_types::Sort::Int);
    let b = F::Var("b".into(), trust_types::Sort::Int);
    let sum = || F::Add(Box::new(a.clone()), Box::new(b.clone()));
    let core = F::Or(vec![
        F::Lt(Box::new(sum()), Box::new(F::Int(SWidth::W32.min_value()))),
        F::Gt(Box::new(sum()), Box::new(F::Int(SWidth::W32.max_value()))),
    ]);
    // WRONG width: i16 thresholds.
    let wrong_w = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        Expr::apps(
            cst(&signed_overflows_name(SignedOp::Add, SWidth::W16)),
            [ops[0].clone(), ops[1].clone()],
        )
    });
    assert!(!wrong_w, "grounding an i32 signed core against the i16 spec MUST be rejected");
    // WRONG (dropped-disjunct, reassociated): claim only the overflow half `MAX < a+b`.
    let dropped = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        let s = Expr::apps(cst("Int.add"), [ops[0].clone(), ops[1].clone()]);
        Expr::apps(cst("Int.lt"), [signed_max_expr(SWidth::W32), s])
    });
    assert!(
        !dropped,
        "dropping the signed UNDERFLOW disjunct MUST be rejected (no false cert)"
    );
    // SANITY: the correct sadd_overflows_i32 spec IS accepted.
    let right = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        Expr::apps(
            cst(&signed_overflows_name(SignedOp::Add, SWidth::W32)),
            [ops[0].clone(), ops[1].clone()],
        )
    });
    assert!(right, "the correct sadd_overflows_i32 spec MUST be accepted");
}

#[test]
fn formula_aware_bridge_rejects_wrong_spec_usub_underflow() {
    // ADVERSARIAL (Lemma 8, formula-aware): the unsigned-sub UNDERFLOW bridge MUST
    // fail closed for a wrong-DIRECTION spec (`b − a < 0` instead of `a − b < 0`) and
    // a wrong-COMPARATOR spec (`a − b ≤ 0` instead of `< 0`).
    use trust_types::Formula as F;
    let a = F::Var("a".into(), trust_types::Sort::Int);
    let b = F::Var("b".into(), trust_types::Sort::Int);
    let core =
        F::Lt(Box::new(F::Sub(Box::new(a.clone()), Box::new(b.clone()))), Box::new(F::Int(0)));
    // WRONG direction: Int.lt (Int.sub b a) 0  (= b < a).
    let wrong_dir = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        let diff = Expr::apps(cst("Int.sub"), [ops[1].clone(), ops[0].clone()]);
        Expr::apps(cst("Int.lt"), [diff, int_lit(0)])
    });
    assert!(!wrong_dir, "a wrong-direction usub spec (`b − a < 0`) MUST be rejected");
    // WRONG comparator: Int.le (Int.sub a b) 0  (= a − b ≤ 0, includes a == b).
    let wrong_cmp = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        let diff = Expr::apps(cst("Int.sub"), [ops[0].clone(), ops[1].clone()]);
        Expr::apps(cst("Int.le"), [diff, int_lit(0)])
    });
    assert!(!wrong_cmp, "a wrong-comparator usub spec (`a − b ≤ 0`) MUST be rejected");
    // SANITY: the correct usub_underflows_u32 spec IS accepted.
    let right = overflow_family_live_def_eq(&core, &[&a, &b], &|ops| {
        Expr::apps(cst(&usub_underflows_name(UWidth::W32)), [ops[0].clone(), ops[1].clone()])
    });
    assert!(right, "the correct usub_underflows_u32 spec MUST be accepted");
}

#[test]
fn formula_aware_bridge_rejects_wrong_spec_negation() {
    // ADVERSARIAL (Lemma 6, formula-aware): the negation-overflow bridge MUST fail
    // closed for a wrong-WIDTH spec (i32 core vs i16 spec) and a wrong-RELATION spec
    // (`x < MIN` instead of `x = MIN`).
    use trust_types::Formula as F;
    let x = F::Var("x".into(), trust_types::Sort::Int);
    let core = F::Eq(Box::new(x.clone()), Box::new(F::Int(SWidth::W32.min_value())));
    // WRONG width: neg_overflows_i16 (MIN = −2^15).
    let wrong_w = overflow_family_live_def_eq(&core, &[&x], &|ops| {
        Expr::app(cst(&neg_overflows_name(SWidth::W16)), ops[0].clone())
    });
    assert!(!wrong_w, "grounding an i32 negation core against the i16 spec MUST be rejected");
    // WRONG relation: Int.lt x MIN  (= x < MIN) instead of x = MIN.
    let wrong_rel = overflow_family_live_def_eq(&core, &[&x], &|ops| {
        Expr::apps(cst("Int.lt"), [ops[0].clone(), signed_min_expr(SWidth::W32)])
    });
    assert!(!wrong_rel, "a wrong-relation negation spec (`x < MIN`) MUST be rejected");
    // SANITY: the correct neg_overflows_i32 spec IS accepted.
    let right = overflow_family_live_def_eq(&core, &[&x], &|ops| {
        Expr::app(cst(&neg_overflows_name(SWidth::W32)), ops[0].clone())
    });
    assert!(right, "the correct neg_overflows_i32 spec MUST be accepted");
}

#[test]
fn shift_i128_value_certifies_the_former_deferred_gap() {
    // THE FORMER "128-BIT SHIFT VC WIDTH" DEFERRED GAP, NOW CLOSED (measured, not
    // assumed): a shift on an i128 value `x:i128 << n:u32` raises a ShiftOverflow
    // VC whose threshold is the WIDTH LITERAL `Int(128)` — a closed `Int.ofNat`
    // that never actually left the literal fragment (unlike the 128-bit OVERFLOW
    // thresholds `±2^127`, which do). Lemma 7 now models it via `ShiftWidth::W128`,
    // so the VC classifies as MODELED and the function's safety VCs certify.
    use trust_types::BinOp;
    let func = shift_func(BinOp::Shl, 128, true, false);
    let vcs = trust_vcgen::generate_vcs(&func);
    assert!(
        vcs.iter().any(|vc| matches!(&vc.kind, trust_types::VcKind::ShiftOverflow { .. })),
        "an i128 shift raises a ShiftOverflow VC"
    );
    assert!(
        !function_emits_unmodeled_safety_vc(&func),
        "the i128 shift VC is MODELED (the width-128 residue is closed)"
    );
    let certs = function_safety_vcs_faithful(&func)
        .expect("an i128-shift function's shift VC certifies at W128");
    assert!(certs.all_modulo_3());
    assert!(
        certs.shift.iter().any(|c| c.kind == SafetyVcKind::ShiftOob(ShiftWidth::W128, false)),
        "the certified kind is ShiftOob(W128, unsigned amount), got {:?}",
        certs.shift.iter().map(|c| c.kind.clone()).collect::<Vec<_>>()
    );
}

