#[test]
fn bounds_disjunct_grounds_exactly_like_ground_prop() {
    // GUARD (live grounder): the modeled reflected OOB disjunct must equal the LIVE
    // `clean_ground::ground_prop` output for the REAL emitted core `Ge(i, len)`
    // (both VARIABLES). We INVOKE the live grounder; `len = bvar(1)`, `i = bvar(0)`.
    use trust_types::Formula as F;
    let mut env = mirsem_safety_env().expect("env");
    register_idx_oob(&mut env).expect("idx_oob");
    let tc = TypeChecker::new(&env);
    let len = Expr::bvar(1);
    let i = Expr::bvar(0);
    let real = F::Ge(
        Box::new(F::Var("i".into(), trust_types::Sort::Int)),
        Box::new(F::Var("len".into(), trust_types::Sort::Int)),
    );
    let grounded = live_ground(&real, &["len", "i"]);
    let modeled = reflected_bounds_disjunct(&len, &i);
    assert!(
        tc.is_def_eq(&modeled, &grounded),
        "the modeled OOB disjunct must equal the LIVE grounder's `Int.le len i` output"
    );
}

// ---- Step 2E (soundness): WRONG bounds claims fail closed ----

#[test]
fn wrong_strict_vs_nonstrict_bounds_claim_fails_closed() {
    // THE OFF-BY-ONE CRUX. CLAIM: the OOB disjunct equals `Int.lt len i` (STRICT
    // `len < i`) instead of `Int.le len i` (`len ≤ i`). The access `s[i]` is OOB at
    // `i = len` too (`len ≤ i`), so the strict form is the classic off-by-one — a
    // different `Prop` term (Int.lt vs Int.le), NOT def-eq ⇒ KERNEL-REJECTED.
    let len = Expr::bvar(1);
    let i = Expr::bvar(0);
    let wrong_rhs = Expr::apps(cst("Int.lt"), [len, i]);
    let verdict = check_bounds_adequacy_inner(Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a strict-vs-non-strict (len<i vs len≤i) off-by-one claim MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
fn wrong_order_bounds_claim_fails_closed() {
    // CLAIM: the OOB disjunct equals `Int.le i len` (`i ≤ len`, the operands
    // SWAPPED) instead of `Int.le len i` (`len ≤ i`). `i ≤ len` is the IN-bounds
    // direction, not the violation — a different Prop ⇒ kernel-rejected. Guards
    // against a direction confusion in the bounds condition.
    let len = Expr::bvar(1);
    let i = Expr::bvar(0);
    let wrong_rhs = Expr::apps(cst("Int.le"), [i, len]);
    let verdict = check_bounds_adequacy_inner(Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong-order (i≤len vs len≤i) claim MUST be kernel-rejected, got {verdict:?}"
    );
}

