// ---- Step 2F (soundness): WRONG div-by-zero claims fail closed ----

#[test]
fn wrong_value_div_by_zero_claim_fails_closed() {
    // THE WRONG-VALUE CRUX. CLAIM: the div-by-zero VC equals `@Eq Int b (Int.ofNat
    // 1)` (`b = 1`) instead of `@Eq Int b (Int.ofNat 0)` (`b = 0`). The divisor is
    // unsafe at `b = 0`, not `b = 1` — a different closed literal, NOT def-eq ⇒
    // KERNEL-REJECTED. The `b=1` vs `b=0` mistake fails closed.
    let b = Expr::bvar(0);
    let eq = Expr::const_(Name::from_string("Eq"), vec![Level::succ(Level::zero())]);
    let wrong_rhs = Expr::apps(eq, [int_ty(), b, int_lit(1)]);
    let verdict = check_div_adequacy_inner(Some(&wrong_rhs));
    assert!(
        matches!(verdict, AdequacyVerdict::KernelRejected(_)),
        "a wrong-value (b=1 vs b=0) div-by-zero claim MUST be kernel-rejected, got {verdict:?}"
    );
}

#[test]
