    let vcs = trust_vcgen::generate_vcs(&func);
    let div_vc = vcs
        .iter()
        .find(|vc| matches!(vc.kind, VcKind::DivisionByZero | VcKind::RemainderByZero))
        .expect("a division function must raise a DivisionByZero VC");
