    // certified def-eq to `idx_oob`. The function counts (bounds cert present), and
    // it raises NO unmodeled safety VC.
    let func = idx_array_func();
    let certs = function_safety_vcs_faithful(&func)
        .expect("an array-index function's bounds VC is certified adequate");
