#[test]
fn function_safety_vcs_faithful_certifies_pure_division() {
    // `fn pure_div(a,b) { a % b }` — a remainder with a symbolic divisor raises a
    // RemainderByZero VC (NO signed `MIN/-1` overflow VC for `%`, unlike `/` whose
    // signed-div-overflow VC would fail-close). So the REM cert (Lemma 9, its own
    // kind) is present and the function is certified.
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator,
        Ty, VerifiableBody, VerifiableFunction,
    };
    let u = || Ty::Int { width: 32, signed: false };
    let func = VerifiableFunction {
        name: "urem".into(),
        def_path: "crate::urem".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: u(), name: Some("a".into()) },
                LocalDecl { index: 2, ty: u(), name: Some("b".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        BinOp::Rem,
                        Operand::Copy(Place::local(1)),
                        Operand::Copy(Place::local(2)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: u(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    };
    let certs = function_safety_vcs_faithful(&func)
        .expect("a `%` function's rem-by-zero VC is certified adequate");
    assert!(certs.all_modulo_3());
    assert!(certs.rem.is_some(), "a rem certificate must be present (Lemma 9, its own kind)");
    assert!(certs.div.is_none(), "the `%` cert is rem, NOT div");
    assert!(certs.bounds.is_none() && certs.overflow.is_empty());
}

