#[test]
fn call_return_recognizer_fails_closed_on_ambiguous_suffix() {
    // NEGATIVE: two registry keys sharing the `::caller`-style suffix make a
    // bare-name callee AMBIGUOUS — never guess which certified function is
    // called (fail-closed).
    let caller = load_call_spine("caller");
    let mut m = std::collections::BTreeMap::new();
    m.insert("a::helper".to_string(), no_requires_fact(2));
    m.insert("b::helper".to_string(), no_requires_fact(2));
    assert_eq!(
        function_adequacy_witness_with_callees(&caller, &m),
        None,
        "an ambiguous callee resolution MUST fail closed"
    );
    // A UNIQUE suffix match, by contrast, resolves (the call-graph lane's
    // resolution discipline, mirrored).
    let mut u = std::collections::BTreeMap::new();
    u.insert("a::helper".to_string(), no_requires_fact(2));
    let cert = function_adequacy_witness_with_callees(&caller, &u)
        .expect("a unique suffix resolution admits the shape");
    let ReturnCertificate::Call(call_cert) = &cert.ret else {
        panic!("expected the CALL return certificate");
    };
    assert_eq!(call_cert.call.callee, "a::helper");
}

#[test]
fn call_result_projects_the_callee_return() {
    // The call DENOTATION is a genuine recursor projection (NOT a bare identity):
    // `call_result (Call.mk callee arg ret)` ι-reduces to `ret`. Confirms the
    // contract-call reasons over the value flowing out of the call site.
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    // Call.mk 7 (Operand.Const 3) (Int.ofNat 42)
    let call = Expr::apps(
        cst(MIRSEM_CALL_MK),
        [Expr::nat_lit(7), Expr::app(cst(MIRSEM_OPERAND_CONST), int_lit(3)), int_lit(42)],
    );
    let lhs = Expr::app(cst(MIRSEM_CALL_RESULT), call);
    assert!(
        tc.is_def_eq(&lhs, &int_lit(42)),
        "call_result (Call.mk _ _ 42) must ι-reduce to 42"
    );
}

// ---- Step 6T: TOTAL correctness — the termination (ranking) while-rule ----

/// A closed WRONG / NON-DECREASING rank `λ (_ : Env). Nat.zero` — a fixed
/// `Env → Nat`. The termination proof concludes the loop halts within `R e`
/// fuel for the BOUND rank `R`; claiming the conclusion at this constant `0`
/// rank (which can never strictly decrease) is a DIFFERENT statement (fuel
/// `0` not `R e`) the honest proof does not inhabit → kernel-rejected.
fn wrong_rank() -> Expr {
    let bd = || BinderData::from(BinderInfo::Default);
    Expr::lam(bd(), env_ty(), cst("Nat.zero"))
}

/// A closed WRONG contract family `λ (_ : Nat)(_ : Int). True` — a fixed
/// `Nat → Int → Prop` distinct from the abstract bound `Post`. The mutual rule
/// composes the bound `Post`; claiming the conclusion at this unrelated
/// contract is not inhabited → kernel-rejected.
fn wrong_contract_family() -> Expr {
    let bd = || BinderData::from(BinderInfo::Default);
    Expr::lam(bd(), cst("Nat"), Expr::lam(bd(), int_ty(), cst("True")))
}

#[test]
fn loop_rank_terminates_proven_modulo_3() {
    // TASK 1 — TOTAL correctness via a well-founded RANKING. The ∀-quantified
    // termination while-rule
    //   ∀ (R : Env→Nat) cond body,
    //     (∀ e, eval_cond e cond = true → Nat.lt (R (exec e body)) (R e))   -- decrease
    //     → ∀ e, eval_cond (exec_loop e cond body (R e)) cond = false        -- halts
    // kernel-checks (by strong/bounded Nat.rec induction on the rank) modulo
    // exactly 3. Combined with loopInvariantRule (partial) this is TOTAL
    // correctness: the invariant holds AND the loop terminates.
    assert_eq!(check_loop_rank_terminates(), RefinementVerdict::ProvenModulo3);
}

#[test]
fn loop_rank_terminates_quantifies_over_the_rank() {
    // GENUINENESS: the termination rule is `∀ R, decrease → terminates` over a
    // REAL `Env → Nat` ranking PARAMETER `R` — not a fact about one fixed
    // measure. The registered theorem's type is def-eq to the constructed
    // ∀-over-rank statement, whose OUTERMOST Π domain is `Env → Nat`.
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    let inferred = tc
        .infer_type(&cst(MIRSEM_LOOP_RANK_TERMINATES))
        .expect("loopRankTerminates has a type");
    let expected = loop_rank_terminates_type(None);
    assert!(
        tc.is_def_eq(&inferred, &expected),
        "the termination rule's type MUST be the ∀ (R : Env→Nat), decrease → … statement"
    );
    // Confirm the outermost Π domain is the ranking Env → Nat (a real measure
    // parameter), not a bare proposition.
    let bd = || BinderData::from(BinderInfo::Default);
    let env_to_nat = Expr::pi(bd(), env_ty(), cst("Nat"));
    assert!(
        !tc.is_def_eq(&expected, &env_to_nat),
        "the termination rule is NOT itself a ranking — it quantifies over one"
    );
}

#[test]
fn non_decreasing_rank_fails_closed() {
    // FAIL-CLOSED (TASK 1): claim the loop halts within a WRONG / NON-DECREASING
    // rank `λ _. 0` (a constant measure that can never strictly drop). The honest
    // proof concludes halting at fuel `R e` for the BOUND rank `R`; the conclusion
    // measured by the constant-`0` rank is a DIFFERENT statement (fuel `0`) the
    // proof does not inhabit → KernelRejected. This is exactly "a non-decreasing
    // rank does not license termination".
    let wrong = wrong_rank();
    let verdict = check_loop_rank_terminates_inner(Some(&wrong));
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a non-decreasing / wrong rank MUST be kernel-rejected, got {verdict:?}"
    );
}

// ---- Step 6TC: TOTAL correctness as a SINGLE composed theorem ----

#[test]
fn loop_total_correct_proven_modulo_3() {
    // TOTAL correctness = partial + termination, as ONE kernel-checked theorem.
    // `loopTotalCorrect`:
    //   ∀ (I : Env→Prop)(R : Env→Nat) cond body,
    //     preservation → decrease → ∀ e, I e →
    //       And (I (exec_loop e cond body (R e)))               -- (a) PARTIAL at halting state
    //           (eval_cond (exec_loop e cond body (R e)) cond = false)  -- (b) TERMINATION
    // kernel-checks modulo exactly 3. Proven by `And.intro` of `loopInvariantRule`
    // (at fuel `R e`) and `loopRankTerminates` (at `e`) — NOT two separate lemmas.
    assert_eq!(check_loop_total_correct(), RefinementVerdict::ProvenModulo3);
}

#[test]
fn loop_total_correct_type_is_the_and_of_the_two_conclusions() {
    // GENUINENESS: the theorem's conclusion is EXACTLY the `And` of (a) the
    // partial-correctness conclusion `I (exec_loop e cond body (R e))` and (b) the
    // termination conclusion `eval_cond (exec_loop e cond body (R e)) cond = false`,
    // at the SHARED fuel `R e`. We (1) confirm the registered theorem's type is def-eq
    // to the composed `And A B` type, and (2) confirm that replacing EITHER conjunct by
    // a vacuous `True` placeholder (`And A True` / `And True B`) yields a type the real
    // theorem is NOT def-eq to — so BOTH real conclusions are load-bearing, not
    // stand-ins. Building the wrong types via `loop_total_correct_type_with_concl`
    // (the SAME binder/hypothesis chain, only the conclusion swapped) isolates the
    // conjunction as the thing under test.
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    let inferred =
        tc.infer_type(&cst(MIRSEM_LOOP_TOTAL_CORRECT)).expect("loopTotalCorrect has a type");
    let (_r_e, real_a, real_b) = loop_total_correct_conjuncts(None);
    let real = loop_total_correct_type_with_concl(Expr::apps(
        cst("And"),
        [real_a.clone(), real_b.clone()],
    ));
    assert!(
        tc.is_def_eq(&inferred, &real),
        "loopTotalCorrect's type MUST be the ∀…, pres → decrease → ∀ e, I e → And A B statement"
    );
    // And it MUST match the canonical `loop_total_correct_type(None)` too.
    assert!(
        tc.is_def_eq(&inferred, &loop_total_correct_type(None)),
        "loopTotalCorrect's type MUST be def-eq to the canonical composed type"
    );
    // The conclusion is genuinely the conjunction of BOTH real conclusions: dropping
    // either conjunct to vacuous `True` is a DIFFERENT (strictly weaker) statement.
    let and_a_true = loop_total_correct_type_with_concl(Expr::apps(
        cst("And"),
        [real_a.clone(), cst("True")],
    ));
    let and_true_b = loop_total_correct_type_with_concl(Expr::apps(
        cst("And"),
        [cst("True"), real_b.clone()],
    ));
    assert!(
        !tc.is_def_eq(&inferred, &and_a_true),
        "the TERMINATION conjunct is NOT vacuous `True` — it is a real conclusion"
    );
    assert!(
        !tc.is_def_eq(&inferred, &and_true_b),
        "the PARTIAL conjunct is NOT vacuous `True` — it is a real conclusion"
    );
    // It is also NOT either conjunct ALONE (i.e. it really is a conjunction, not just
    // one half): the bare partial-only / termination-only statements differ.
    let partial_only = loop_total_correct_type_with_concl(real_a);
    let termination_only = loop_total_correct_type_with_concl(real_b);
    assert!(
        !tc.is_def_eq(&inferred, &partial_only),
        "loopTotalCorrect is the CONJUNCTION, not the partial-correctness half alone"
    );
    assert!(
        !tc.is_def_eq(&inferred, &termination_only),
        "loopTotalCorrect is the CONJUNCTION, not the termination half alone"
    );
}

