// ---- Step 6LF: PER-FUNCTION loop instantiation (standalone-vs-wired gap) ----

/// The concrete loop function `loop_keep_zero(n)`:
/// ```text
/// let r = 0;          // local 2, NEVER assigned in the loop
/// let mut i = 0;      // local 3
/// while i < n {       // guard: Cmp Lt (Var 3) (Var 1)   (i < n)
///     i = i + 1;      // body : [Assign 3 (Bin Add (Var 3) (Const 1))]
/// }
/// r                   // returns local 2 (== 0)
/// ```
/// PROVIDED invariant: `I := λ e. e[2] = 0` (the untouched local `r` stays 0).
/// The body assigns ONLY local 3 (the counter `i`), never local 2, so `I` is
/// preserved DEFINITIONALLY — the postcondition `ret == 0` is a corollary.
fn loop_keep_zero_function() -> SemLoopFunction {
    SemLoopFunction {
        // i < n  : Cmp Lt (Var 3) (Var 1)
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(3),
            b: SemOperand::Var(1),
        }),
        // i = i + 1 : Assign 3 (Bin Add (Var 3) (Const 1))
        body: vec![SemStmt {
            idx: 3,
            rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(3), SemOperand::Const(1)),
        }],
        inv_local: 2, // the untouched local `r`
        inv_const: 0, // `r == 0`
        synth_inv: None,
    }
}

#[test]
fn loop_refinement_instance_proven_modulo_3() {
    // THE WIRED CASE: the GENERAL Hoare while-rule `loopInvariantRule`, INSTANTIATED
    // at `loop_keep_zero`'s CONCRETE invariant `I := λ e. e[2] = 0`, guard `i < n`,
    // and body `[i := i+1]`, fed a CONCRETE preservation proof (`λ e hI _g. hI`,
    // sound because the body leaves local 2 untouched ⇒ `I (exec e body)` is def-eq
    // to `I e`), kernel-checks the per-function partial-correctness instance
    //   ∀ n e, I e → I (exec_loop e (i<n) [i:=i+1] n)
    // modulo exactly 3. This is the loop rule WIRED for this one real function — the
    // standalone-vs-instantiated gap, closed for a concrete case.
    let lf = loop_keep_zero_function();
    assert_eq!(check_loop_refinement_instance(&lf), RefinementVerdict::ProvenModulo3);
}

#[test]
fn loop_refinement_witness_mints_certificate_modulo_3() {
    // The witness mints a LoopRefinementCertificate for the keep-zero loop (its body
    // does NOT assign the invariant local 2 ⇒ the soundness guard passes ⇒ the
    // kernel proves the per-function instance modulo 3).
    let lf = loop_keep_zero_function();
    let cert = loop_refinement_witness(&lf).expect("keep-zero loop has a certificate");
    assert!(cert.is_modulo_3(), "the per-function loop instance must be modulo 3");
}

#[test]
fn loop_refinement_instance_axiom_deps_subset_of_3() {
    // The per-function loop instance rests on ⊆ the 3 foundational axioms — NO 4th
    // axiom (it only applies the kernel-checked `loopInvariantRule` to a closed
    // invariant/guard/body + a def-eq preservation proof). We register the SAME
    // instance into the loop-instance env and audit its axiom closure directly.
    let lf = loop_keep_zero_function();
    let mut env = loop_instance_env().expect("loop-instance env builds");
    let concl_ty = loop_instance_conclusion_type(&lf, None);
    let proof = loop_instance_proof(&lf, None);
    {
        let tc = TypeChecker::new(&env);
        tc.check_type(&proof, &concl_ty).expect("instance type-checks");
    }
    let name = Name::from_string("Trust.MirSem.loopInstance.partialCorrect.audit");
    env.add_decl(Declaration::Theorem {
        name: name.clone(),
        level_params: vec![],
        type_: concl_ty,
        value: proof,
    })
    .expect("register instance");
    let residue = env.axiom_deps(&name).expect("instance present");
    assert!(
        residue.is_empty(),
        "the per-function loop instance must rest on ⊆ the 3 foundational axioms, \
         got residue {residue:?}"
    );
}

#[test]
fn loop_refinement_instance_conclusion_is_the_per_function_invariant_rule() {
    // GENUINENESS: the per-function conclusion is EXACTLY `loopInvariantRule`
    // SPECIALIZED at this function's `(I, cond, body)` — `∀ n e, I e → I (exec_loop
    // e cond body n)` — NOT a vacuous statement. We confirm the registered instance's
    // type is def-eq to the constructed per-function conclusion, and that swapping the
    // invariant to a DIFFERENT constant (`I := λ e. e[2] = 1`) is a DIFFERENT
    // (non-def-eq) statement — so the pinned invariant is load-bearing.
    let lf = loop_keep_zero_function();
    let env = loop_instance_env().expect("env");
    let tc = TypeChecker::new(&env);
    let real = loop_instance_conclusion_type(&lf, None);
    let proof = loop_instance_proof(&lf, None);
    let inferred = tc.infer_type(&proof).expect("the instance proof has a type");
    assert!(
        tc.is_def_eq(&inferred, &real),
        "the instance's type MUST be loopInvariantRule specialized at (I, cond, body)"
    );
    // A DIFFERENT invariant constant is a strictly different statement.
    let mut other = lf.clone();
    other.inv_const = 1;
    let other_ty = loop_instance_conclusion_type(&other, None);
    assert!(
        !tc.is_def_eq(&real, &other_ty),
        "the invariant predicate is load-bearing: `e[2]=0` ≠ `e[2]=1` as a statement"
    );
}

#[test]
fn wrong_loop_invariant_assigned_local_fails_closed() {
    // FAIL-CLOSED: claim the invariant about a local the body DOES assign — local 3
    // (the counter `i`, which the body writes `i := i+1`). The invariant `I := λ e.
    // e[3] = 0` is NOT preserved (after one step `i` is `0+1=1`, not 0), so the
    // def-eq preservation proof `λ e hI _g. hI` is ILL-TYPED: `I (exec e body)`
    // reduces to `(set e 3 (i+1)) 3 = 0` ≡ `eval_rvalue e (i+1) = 0`, which is NOT
    // def-eq to the hypothesis `I e ≡ e[3] = 0`. The kernel rejects it.
    let lf = loop_keep_zero_function();
    let verdict = check_loop_refinement_instance_inner(&lf, Some(3));
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a WRONG invariant about the body-assigned counter MUST be kernel-rejected, \
         got {verdict:?}"
    );
}

#[test]
fn loop_instance_preservation_proof_is_definitional_for_untouched_local() {
    // The CORE soundness fact the per-function loop certificate rests on: the
    // CONCRETE preservation proof `λ e hI _g. hI` type-checks against the CONCRETE
    // preservation TYPE `∀ e, I e → eval_cond e cond = true → I (exec e body)` for the
    // untouched-local invariant `I := λ e. e[2] = 0` — because `I (exec e body)` is
    // DEF-EQ to `I e` (the body leaves local 2 untouched, `exec`/`set` collapse it).
    // For the body-ASSIGNED local 3 the SAME proof FAILS to type-check (the codomain
    // `I (exec e body)` no longer reduces to `I e`) — fail-closed at the preservation
    // level, the root of the certificate's soundness.
    let lf = loop_keep_zero_function();
    let env = loop_instance_env().expect("env");
    let tc = TypeChecker::new(&env);
    // Untouched local 2: the def-eq preservation proof type-checks.
    let good_ty = loop_instance_preservation_type(&lf, None);
    let good_proof = loop_instance_preservation_proof(&lf, None);
    assert!(
        tc.check_type(&good_proof, &good_ty).is_ok(),
        "the def-eq preservation proof must type-check for the untouched local"
    );
    // Body-assigned local 3 (the counter): the SAME `λ e hI _g. hI` proof does NOT
    // type-check (the codomain no longer reduces to the hypothesis).
    let bad_ty = loop_instance_preservation_type(&lf, Some(3));
    let bad_proof = loop_instance_preservation_proof(&lf, Some(3));
    assert!(
        tc.check_type(&bad_proof, &bad_ty).is_err(),
        "the def-eq preservation proof MUST fail for a body-assigned local (fail-closed)"
    );
}

#[test]
fn loop_refinement_witness_fails_closed_on_assigned_invariant_local() {
    // The witness itself fail-closes when the invariant pins a body-ASSIGNED local:
    // the soundness guard (`body_assigns(inv_local)`) returns None BEFORE any kernel
    // check, so no certificate is minted for an unsound invariant.
    let mut lf = loop_keep_zero_function();
    lf.inv_local = 3; // the counter the body assigns — NOT preserved.
    assert!(
        loop_refinement_witness(&lf).is_none(),
        "no certificate may be minted when the invariant pins a body-assigned local"
    );
}

// ---- Step 6SI: SYNTHESIZED invariant (inference, not hand-provided) ----

/// The SAME `loop_keep_zero` counter loop, but carrying a SYNTHESIZED invariant
/// `I := λ e. Int.le 0 (e 3)` (`0 ≤ i`) instead of the untouched-local equality.
/// This is the abstract-domain-inferred lower bound the interval domain finds.
fn loop_keep_zero_synth_ge0() -> SemLoopFunction {
    SemLoopFunction {
        synth_inv: Some(SynthInvariant::CounterGeConst { i_idx: 3, c: 0 }),
        ..loop_keep_zero_function()
    }
}

#[test]
fn synth_invariant_loop_instance_proven_modulo_3() {
    // The Hoare while-rule INSTANTIATED at the SYNTHESIZED invariant `0 ≤ i`, with a
    // GENUINE inductive preservation proof (`Int.le_trans 0 i (i+1) hI
    // (Int.le_self_add_one i)`, which USES the hypothesis `hI : 0 ≤ i`), kernel-checks
    // the per-function partial-correctness instance modulo 3. The invariant is INFERRED
    // (interval lower bound), not the untouched-local equality.
    let lf = loop_keep_zero_synth_ge0();
    assert_eq!(check_loop_refinement_instance(&lf), RefinementVerdict::ProvenModulo3);
}

#[test]
fn synth_invariant_witness_mints_certificate_modulo_3() {
    // The witness mints a certificate for the SYNTHESIZED invariant even though the
    // body DOES assign the invariant's counter local (the untouched-local soundness
    // guard does NOT apply to the synthesized form — the genuine kernel preservation
    // proof handles the assignment).
    let lf = loop_keep_zero_synth_ge0();
    assert!(lf.body_assigns(3), "the synthesized invariant is ABOUT the body-assigned counter");
    let cert =
        loop_refinement_witness(&lf).expect("synthesized-invariant loop has a certificate");
    assert!(cert.is_modulo_3(), "the synthesized-invariant instance must be modulo 3");
}

#[test]
fn synth_invariant_instance_axiom_deps_subset_of_3() {
    // The synthesized-invariant per-function instance rests on ⊆ the 3 foundational
    // axioms — its preservation uses only the CONSTRUCTIVE (modulo-3) prelude lemmas
    // `Int.le_trans` / `Int.le_self_add_one`, no 4th axiom.
    let lf = loop_keep_zero_synth_ge0();
    let mut env = loop_instance_env().expect("loop-instance env builds");
    let concl_ty = loop_instance_conclusion_type(&lf, None);
    let proof = loop_instance_proof(&lf, None);
    {
        let tc = TypeChecker::new(&env);
        tc.check_type(&proof, &concl_ty).expect("synthesized instance type-checks");
    }
    let name = Name::from_string("Trust.MirSem.loopInstance.synth.audit");
    env.add_decl(Declaration::Theorem {
        name: name.clone(),
        level_params: vec![],
        type_: concl_ty,
        value: proof,
    })
    .expect("register synthesized instance");
    let residue = env.axiom_deps(&name).expect("instance present");
    assert!(
        residue.is_empty(),
        "the synthesized-invariant loop instance must rest on ⊆ the 3 foundational \
         axioms, got residue {residue:?}"
    );
}

#[test]
fn synth_invariant_conclusion_is_about_the_inferred_lower_bound() {
    // GENUINENESS: the synthesized instance's conclusion is `∀ n e, I e → I (exec_loop
    // …)` for `I := λ e. Int.le 0 (e 3)` — a NON-TRIVIAL inferred lower bound, NOT a
    // vacuous statement and NOT the untouched-local equality. Swapping the synthesized
    // constant to `5 ≤ i` is a STRICTLY DIFFERENT statement.
    let lf = loop_keep_zero_synth_ge0();
    let env = loop_instance_env().expect("env");
    let tc = TypeChecker::new(&env);
    let real = loop_instance_conclusion_type(&lf, None);
    let proof = loop_instance_proof(&lf, None);
    let inferred = tc.infer_type(&proof).expect("the synthesized instance proof has a type");
    assert!(
        tc.is_def_eq(&inferred, &real),
        "the synthesized instance's type MUST be loopInvariantRule at the inferred I"
    );
    // The synthesized invariant `0 ≤ i` is a DIFFERENT statement from the
    // untouched-local equality `e[2] = 0` and from a different lower bound `5 ≤ i`.
    let eq_ty = loop_instance_conclusion_type(&loop_keep_zero_function(), None);
    assert!(
        !tc.is_def_eq(&real, &eq_ty),
        "the synthesized inequality `0 ≤ i` ≠ the untouched-local equality `e[2]=0`"
    );
    let other = SemLoopFunction {
        synth_inv: Some(SynthInvariant::CounterGeConst { i_idx: 3, c: 5 }),
        ..loop_keep_zero_function()
    };
    let other_ty = loop_instance_conclusion_type(&other, None);
    assert!(
        !tc.is_def_eq(&real, &other_ty),
        "the synthesized bound is load-bearing: `0 ≤ i` ≠ `5 ≤ i` as a statement"
    );
}

#[test]
fn wrong_synth_invariant_fails_closed_on_decrement_body() {
    // FAIL-CLOSED (the load-bearing soundness test): a synthesized lower bound `0 ≤ i`
    // claimed for a DECREMENT loop `i := i - 1` is NOT preserved (`0 ≤ i` does NOT give
    // `0 ≤ i - 1`). The preservation proof's `Int.le_self_add_one` bridge builds the
    // codomain `0 ≤ i + 1`, but the ACTUAL `I (exec e [i:=i-1])` reduces to `0 ≤ i - 1`,
    // which is NOT def-eq to `0 ≤ i + 1`. The kernel REJECTS the instance — a wrong
    // synthesized invariant cannot mint a certificate.
    let lf = SemLoopFunction {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(3),
            b: SemOperand::Var(1),
        }),
        // i = i - 1 : the body SUBTRACTS, so the lower bound is NOT preserved.
        body: vec![SemStmt {
            idx: 3,
            rvalue: SemRvalue::Bin(SemBinOp::Sub, SemOperand::Var(3), SemOperand::Const(1)),
        }],
        inv_local: 2,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::CounterGeConst { i_idx: 3, c: 0 }),
    };
    let verdict = check_loop_refinement_instance(&lf);
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a synthesized lower bound on a DECREMENT body MUST be kernel-rejected, got {verdict:?}"
    );
    // The witness therefore mints NO certificate (fail-closed end to end).
    assert!(
        loop_refinement_witness(&lf).is_none(),
        "no certificate may be minted for an unsound synthesized invariant"
    );
}

