// ---- Step 6CU: CONDITIONALLY-UPDATED accumulator `if i>m { m=i }` ----

/// The `max_scan`-shape loop `while i < n { if i > m { m = i }; i = i + 1 }` as a
/// `SemLoopFunction`, carrying the CONDITIONAL-UPDATE invariant `c ≤ m ∧ 0 ≤ i`. Env
/// indices: `m` = 4 (the accumulator), `i` = 5 (the counter), `n` = 1 (the guard bound) —
/// matching the `max_scan.json` MIR locals. The body is the TWO-statement
/// `[m := Sel (i>m) i m; i := i+1]`: the conditional MAX update FIRST (so the `Sel`'s
/// `i`/`m` arms read the PRE-update values), the counter increment SECOND.
fn loop_max_scan_function(c: i128) -> SemLoopFunction {
    SemLoopFunction {
        // i < n  : Cmp Lt (Var 5) (Var 1)
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(5),
            b: SemOperand::Var(1),
        }),
        body: vec![
            // m := if (i > m) { i } else { m }  : Assign 4 (Sel (Gt (Var 5)(Var 4)) (Var 5)(Var 4))
            SemStmt {
                idx: 4,
                rvalue: SemRvalue::Sel(
                    SemCond { op: SemCmpOp::Gt, a: SemOperand::Var(5), b: SemOperand::Var(4) },
                    SemOperand::Var(5),
                    SemOperand::Var(4),
                ),
            },
            // i := i + 1  : Assign 5 (Bin Add (Var 5) (Const 1))
            SemStmt {
                idx: 5,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(5), SemOperand::Const(1)),
            },
        ],
        inv_local: 0,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::CondUpdateGeConst { m_idx: 4, c, i_idx: 5, n_idx: 1 }),
    }
}

#[test]
fn cond_update_loop_instance_proven_modulo_3() {
    // The Hoare while-rule INSTANTIATED at the CONDITIONAL-UPDATE invariant `0 ≤ m ∧ 0 ≤ i`,
    // with the preservation proof case-splitting (`Bool.rec`) over the update condition
    // `i > m`: the THEN-arm (`m := i`) discharges `0 ≤ m` from `0 ≤ i`, the ELSE-arm
    // (`m` unchanged) from the hypothesis's `0 ≤ m`. Kernel-checks the per-function
    // partial-correctness instance modulo 3 — the conditional MAX update is FAITHFUL.
    let lf = loop_max_scan_function(0);
    assert_eq!(check_loop_refinement_instance(&lf), RefinementVerdict::ProvenModulo3);
}

#[test]
fn cond_update_total_correctness_and_postcondition_proven_modulo_3() {
    // The conditional-update invariant composes with TOTAL correctness (ranking
    // `toNat(n − i)` over the counter `i`, decreasing each `i := i+1` step — the
    // conditional `m` update leaves `i` untouched) AND discharges the source
    // postcondition `ret ≥ 0` (the return reads `m`; `And.left (I halt) : 0 ≤ halt m`).
    let lf = loop_max_scan_function(0);
    let total = loop_total_correct_witness(&lf)
        .expect("max_scan conditional-update loop has a total-correctness certificate");
    assert!(total.is_modulo_3(), "the cond-update total-correctness instance must be modulo 3");
    let cert = loop_postcondition_witness(&lf, LoopPostcondition::ConstLeRet { c: 0 })
        .expect("the cond-update invariant discharges `ret ≥ 0`");
    assert!(cert.is_modulo_3(), "the cond-update postcondition discharge must be modulo 3");
}

