#[test]
fn wrong_synth_upper_bound_fails_closed_on_decrement_body() {
    // FAIL-CLOSED: the upper bound `i ≤ n` claimed for a DECREMENT loop `i := i - 1`.
    // The codomain `I (exec e [i:=i-1])` reduces to `Int.le (i-1) n`, but the guard
    // `i < n` only yields `Int.le (i+1) n` — `i-1` vs `i+1` are NOT def-eq ⇒ the proof
    // is ill-typed ⇒ KernelRejected. (Even though `i ≤ n` IS actually preserved here,
    // our guard-USING proof term does not retype against the decrement body — fail
    // closed, never falsely accept via a mismatched proof.)
    let lf = SemLoopFunction {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(3),
            b: SemOperand::Var(1),
        }),
        body: vec![SemStmt {
            idx: 3,
            rvalue: SemRvalue::Bin(SemBinOp::Sub, SemOperand::Var(3), SemOperand::Const(1)),
        }],
        inv_local: 2,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::CounterLeBound { i_idx: 3, bound_idx: 1 }),
    };
    assert!(
        matches!(check_loop_refinement_instance(&lf), RefinementVerdict::KernelRejected(_)),
        "the guard-using upper-bound proof must be kernel-rejected on a decrement body"
    );
}

