#[test]
fn wrong_synth_in_range_fails_closed_on_wrong_lower_bound() {
    // FAIL-CLOSED: a wrong lower constant (`1 ≤ i`, false at entry) in the range. The
    // lower conjunct's `Int.le_trans` chain builds `Int.le 1 (i+1)` from `And.left hI :
    // Int.le 1 (e i)`, which retypes as a STATEMENT — but the inference path never
    // proposes `1 ≤ i` (it must match init 0). Here we exercise a wrong UPPER bound
    // index in the conjunction, which DOES fail the kernel: the upper conjunct's
    // guard-extraction targets the wrong bound.
    let lf = SemLoopFunction {
        synth_inv: Some(SynthInvariant::CounterInRange { i_idx: 3, c: 0, bound_idx: 2 }),
        ..loop_keep_zero_function()
    };
    assert!(
        matches!(check_loop_refinement_instance(&lf), RefinementVerdict::KernelRejected(_)),
        "a conjoined range with a non-guard upper bound MUST be kernel-rejected"
    );
}

// ---- Step 6M: MUTUAL recursion — the mutual-contract composition rule ----

#[test]
fn mutual_call_contracts_proven_modulo_3() {
    // TASK 2 — MUTUAL recursion. The ∀-quantified mutual-contract rule
    //   ∀ (Post : Nat→Int→Prop)(rank : Call→Nat),
    //     (∀ c, (∀ c', Nat.lt (rank c') (rank c) → Post (callee c')(result c'))
    //            → Post (callee c)(result c))                     -- the mutual STEP
    //     → ∀ c, Post (callee c)(result c)
    // kernel-checks (by well-founded/strong induction on the call rank) modulo
    // exactly 3. ASSUME-the-callees (modular): the step is assumed for every
    // smaller-rank call; the rule composes the per-callee contracts over the
    // (mutually-recursive) call graph.
    assert_eq!(check_mutual_call_contracts(), RefinementVerdict::ProvenModulo3);
}

#[test]
fn mutual_call_contracts_quantifies_over_contracts_and_rank() {
    // GENUINENESS: the mutual rule is `∀ Post rank, step → …` over the per-callee
    // contract family `Post : Nat → Int → Prop` AND the call ranking `rank :
    // Call → Nat` — both real PARAMETERS. The registered type is def-eq to the
    // constructed ∀-over-(Post,rank) statement, whose outermost Π domain is the
    // contract family `Nat → Int → Prop`.
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    let inferred = tc
        .infer_type(&cst(MIRSEM_MUTUAL_CALL_CONTRACTS))
        .expect("mutualCallContracts has a type");
    let expected = mutual_call_contracts_type(None);
    assert!(
        tc.is_def_eq(&inferred, &expected),
        "the mutual rule's type MUST be the ∀ (Post)(rank), step → … statement"
    );
    let bd = || BinderData::from(BinderInfo::Default);
    let post_ty = Expr::pi(bd(), cst("Nat"), Expr::pi(bd(), int_ty(), Expr::prop()));
    assert!(
        !tc.is_def_eq(&expected, &post_ty),
        "the mutual rule is NOT itself a contract — it quantifies over a family of them"
    );
}

#[test]
fn mutual_call_contracts_assumes_the_callees_not_proves() {
    // MODULARITY: the rule does NOT discharge any callee body. Its type carries a
    // genuine STEP HYPOTHESIS (an `Env`-free Π whose domain is the mutual step);
    // dropping that hypothesis would make the conclusion unprovable. We confirm
    // the step hypothesis is a real Π (non-trivial assumption), by checking the
    // statement is NOT def-eq to the hypothesis-free conclusion `∀ c, Post …`.
    let bd = || BinderData::from(BinderInfo::Default);
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    // hypothesis-free body `∀ Post rank, ∀ c, Post (callee c)(result c)` (NO step):
    let post_ty = Expr::pi(bd(), cst("Nat"), Expr::pi(bd(), int_ty(), Expr::prop()));
    let rank_ty = Expr::pi(bd(), cst(MIRSEM_CALL), cst("Nat"));
    let hyp_free = {
        // inside `∀ Post ∀ rank ∀ c`: c=0,rank=1,Post=2.
        let cod = post_holds(Expr::bvar(2), Expr::bvar(0));
        Expr::pi(bd(), post_ty, Expr::pi(bd(), rank_ty, Expr::pi(bd(), cst(MIRSEM_CALL), cod)))
    };
    let real = mutual_call_contracts_type(None);
    assert!(
        !tc.is_def_eq(&real, &hyp_free),
        "the mutual rule MUST carry the assume-the-callees STEP hypothesis (not be the bare conclusion)"
    );
}

