// =======================================================================
// Step 6X — THE UNBOUNDED IRREDUCIBLE-CFG TERMINATION rule via a CFG-state
// RANKING: cfgRankTerminates (the CFG run reaches an exit/stable state within
// `R s` steps GIVEN the rank strictly decreases each step until exit), proven
// by the well-founded Nat descent over CfgState/step_cfg/exec_cfg, modulo 3.
// =======================================================================

/// A closed WRONG / NON-DECREASING CFG rank `λ (_ : CfgState). Nat.zero` — a fixed
/// `CfgState → Nat`. The termination proof concludes the run reaches exit within
/// `R s` fuel for the BOUND rank `R`; claiming the conclusion at this constant `0`
/// rank (which can never strictly decrease) is a DIFFERENT statement (fuel `0` not
/// `R s`) the honest proof does not inhabit → kernel-rejected.
fn wrong_cfg_rank() -> Expr {
    let bd = || BinderData::from(BinderInfo::Default);
    Expr::lam(bd(), cfg_state_ty(), cst("Nat.zero"))
}

#[test]
fn cfg_rank_terminates_proven_modulo_3() {
    // TASK 1 — UNBOUNDED irreducible-CFG TOTAL correctness via a CFG-state RANKING.
    // The ∀-quantified termination rule
    //   ∀ (R : CfgState→Nat)(at_exit : CfgState→Bool)(next : Nat→Env→CfgState),
    //     (∀ s, at_exit s = true → step_cfg next s = s)                    -- stable
    //     → (∀ s, at_exit s = false → Nat.lt (R (step_cfg next s)) (R s))  -- decrease
    //     → ∀ s, at_exit (exec_cfg next (R s) s) = true                    -- halts
    // kernel-checks (by bounded Nat.rec descent on the rank over CfgState/step_cfg/
    // exec_cfg) modulo exactly 3. This UPGRADES the BOUNDED `cfgRefinement` to TOTAL
    // correctness for an UNBOUNDED irreducible CFG that carries a ranking — `next` is
    // an ARBITRARY transition function, so it covers irreducible back-edges.
    assert_eq!(check_cfg_rank_terminates(), RefinementVerdict::ProvenModulo3);
}

#[test]
fn cfg_rank_terminates_quantifies_over_the_cfg_state_rank() {
    // GENUINENESS: the rule is `∀ R, stable → decrease → terminates` over a REAL
    // `CfgState → Nat` ranking PARAMETER `R` — not a fact about one fixed measure.
    // The registered theorem's type is def-eq to the constructed ∀-over-rank
    // statement, whose OUTERMOST Π domain is `CfgState → Nat`.
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    let inferred =
        tc.infer_type(&cst(MIRSEM_CFG_RANK_TERMINATES)).expect("cfgRankTerminates has a type");
    let expected = cfg_rank_terminates_type(None);
    assert!(
        tc.is_def_eq(&inferred, &expected),
        "the CFG termination rule's type MUST be the ∀ (R : CfgState→Nat), stable → decrease → … statement"
    );
    // The outermost Π domain is the ranking CfgState → Nat (a real measure
    // parameter), not a bare proposition.
    assert!(
        !tc.is_def_eq(&expected, &cfg_rank_ty()),
        "the CFG termination rule is NOT itself a ranking — it quantifies over one"
    );
}

#[test]
fn cfg_rank_terminates_carries_the_stable_and_decrease_hypotheses() {
    // MODULARITY / NON-VACUITY: the rule carries BOTH the exit-stability hypothesis
    // and the rank-decrease hypothesis. Dropping the decrease would make the
    // conclusion unprovable (no measure to descend on). We confirm the statement is
    // NOT def-eq to the hypothesis-light variant `∀ R at_exit next, stable → ∀ s,
    // at_exit (exec_cfg next (R s) s) = true` (decrease REMOVED) — so the decrease
    // hypothesis is a real, load-bearing Π.
    let bd = || BinderData::from(BinderInfo::Default);
    let env = mirsem_whole_program_env().expect("env");
    let tc = TypeChecker::new(&env);
    // ∀ R at_exit next, stable → ∀ s, cfg_halts …  (NO decrease)
    let no_decrease = {
        // inside `∀ R ∀ at_exit ∀ next`: next=0,at_exit=1,R=2.
        let stable = cfg_stable_hyp_type(&Expr::bvar(1), &Expr::bvar(0));
        // conclusion under `(stable→) ∀ s`: s=0,stable=1,next=2,at_exit=3,R=4.
        let fuel = Expr::app(Expr::bvar(4), Expr::bvar(0)); // R s
        let halts = cfg_halts_prop(Expr::bvar(3), Expr::bvar(2), fuel, Expr::bvar(0));
        let body_s = Expr::pi(bd(), cfg_state_ty(), halts);
        let after_stable = Expr::pi(bd(), stable, body_s);
        Expr::pi(
            bd(),
            cfg_rank_ty(),
            Expr::pi(bd(), cfg_at_exit_ty(), Expr::pi(bd(), cfg_next_ty(), after_stable)),
        )
    };
    let real = cfg_rank_terminates_type(None);
    assert!(
        !tc.is_def_eq(&real, &no_decrease),
        "the CFG termination rule MUST carry the rank-DECREASE hypothesis (not be the decrease-free statement)"
    );
}

