/// FAIL-CLOSED (STEP 6LT) — a WRONG / NON-DECREASING ranking `R := λ e. toNat(i)` (the
/// counter itself, which INCREASES on `i := i + 1`) supplied with the HONEST decrease
/// proof (typed for the CORRECT ranking) must be KernelRejected: the conclusion's fuel
/// `R e` is measured by the wrong rank, so the honest decrease proof does not inhabit
/// it. A ranking that does not strictly decrease does NOT license termination.
#[test]
fn loop_keep_zero_wrong_ranking_fails_closed() {
    let lf = loop_keep_zero_lf();
    let (i_idx, n_idx) = recognize_counter_loop(&lf).expect("recognized counter loop");
    // The honest decrease proof (built for the correct ranking R := toNat(n - i)).
    let decrease = counter_loop_decrease_proof(&lf, i_idx, n_idx);
    // The WRONG ranking R := λ e. Int.toNat (e i_idx) = i — INCREASES on i := i + 1.
    let bd = || BinderData::from(BinderInfo::Default);
    let wrong = Expr::lam(
        bd(),
        env_ty(),
        Expr::app(cst("Int.toNat"), Expr::app(Expr::bvar(0), Expr::nat_lit(i_idx))),
    );
    let verdict = check_loop_total_correct_instance_inner(&lf, &wrong, &decrease);
    assert!(
        matches!(verdict, RefinementVerdict::KernelRejected(_)),
        "a wrong / non-decreasing ranking MUST be kernel-rejected, got {verdict:?}"
    );
}

/// STEP 6LT (RANKING SYNTHESIS) — the ranking is now SYNTHESIZED from the loop
/// structure, not hand-supplied. `synthesize_counter_ranking` recognizes the
/// `counter < bound` + `+1`-increment shape and PROPOSES `R := λ e. toNat(bound -
/// counter)`. The proposed ranking is the SAME term `counter_loop_ranking` builds at
/// the recognized `(i_idx, bound_idx)`, and the kernel VERIFIES its decrease.
#[test]
fn ranking_is_synthesized_from_loop_structure() {
    let lf = loop_keep_zero_lf();
    let (ranking, _decrease) =
        synthesize_counter_ranking(&lf).expect("the counter loop's ranking is synthesizable");
    let (i_idx, n_idx) = recognize_counter_loop(&lf).expect("recognized");
    let env = loop_total_correct_instance_env().expect("env");
    let tc = TypeChecker::new(&env);
    // The synthesized ranking is exactly toNat(bound - counter) — the structural measure.
    assert!(
        tc.is_def_eq(&ranking, &counter_loop_ranking(i_idx, n_idx)),
        "the synthesized ranking must be the structural measure toNat(n - i)"
    );
    // And it is a genuine Env → Nat (type-checks against the ranking type).
    let r_ty = Expr::pi(BinderData::from(BinderInfo::Default), env_ty(), cst("Nat"));
    tc.check_type(&ranking, &r_ty).expect("synthesized ranking is an Env → Nat");
}

