#[test]
fn probe_defeqs_for_new_shapes() {
    let env = loop_instance_env().expect("env");
    let tc = TypeChecker::new(&env);
    let add = |a: Expr, b: Expr| Expr::apps(cst("Int.add"), [a, b]);
    let sub = |a: Expr, b: Expr| Expr::apps(cst("Int.sub"), [a, b]);
    let neg = |a: Expr| Expr::app(cst("Int.neg"), a);
    // (A) `Int.sub i 1 ≡ Int.add i (Int.neg 1)`.
    let i = int_lit(7);
    assert!(
        tc.is_def_eq(&sub(i.clone(), int_one()), &add(i.clone(), neg(int_one()))),
        "Int.sub reduces to Int.add . Int.neg"
    );
    // (B) `Int.add 1 (Int.neg 1) ≡ Int.ofNat 0`.
    assert!(
        tc.is_def_eq(&add(int_one(), neg(int_one())), &int_lit(0)),
        "1 + (-1) reduces to 0"
    );
    // (C) `Int.neg (Int.ofNat 1) ≡ Int.negSucc 0` (= int_lit(-1)).
    assert!(tc.is_def_eq(&neg(int_one()), &int_lit(-1)), "neg 1 reduces to negSucc 0");
    // (D) `Int.lt 0 i ≡ Int.le (Int.add 0 1) i` and `Int.add 0 1 ≡ 1`.
    assert!(tc.is_def_eq(&add(int_lit(0), int_one()), &int_one()), "0 + 1 reduces to 1");
    // (E) stride: `Int.add i k` where k = ofNat 3 is just a value (no reduction needed),
    // and `i ≤ i + k` via add_le_add_left needs `0 ≤ k` and `i + 0 ≡ i`.
    assert!(tc.is_def_eq(&add(i.clone(), int_lit(0)), &i), "i + 0 reduces to i");
    // (F) `Int.add 0 i ≡ i` (left zero) — needed if we use add_le_add_left form.
    assert!(tc.is_def_eq(&add(int_lit(0), i.clone()), &i), "0 + i reduces to i");
}

// ============================================================================
// Step 6SI-EXT: ADDITIONAL LOOP SHAPES — `≤` guard, COUNTDOWN, STRIDE.
// ============================================================================

/// The `≤`-guarded counter loop `while i ≤ n { i = i + 1 }`: guard `Le (Var 3)(Var 1)`,
/// body `i = i + 1`. `i` is env index 3, the bound `n` is env index 1.
fn loop_count_le_function() -> SemLoopFunction {
    SemLoopFunction {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Le,
            a: SemOperand::Var(3),
            b: SemOperand::Var(1),
        }),
        body: vec![SemStmt {
            idx: 3,
            rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(3), SemOperand::Const(1)),
        }],
        inv_local: 2,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::CounterLeBoundSucc { i_idx: 3, bound_idx: 1 }),
    }
}

/// The COUNTDOWN loop `while i > 0 { i = i - 1 }`: guard `Gt (Var 3)(Const 0)`, body
/// `i = i - 1`. `i` is env index 3.
fn loop_countdown_function() -> SemLoopFunction {
    SemLoopFunction {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Gt,
            a: SemOperand::Var(3),
            b: SemOperand::Const(0),
        }),
        body: vec![SemStmt {
            idx: 3,
            rvalue: SemRvalue::Bin(SemBinOp::Sub, SemOperand::Var(3), SemOperand::Const(1)),
        }],
        inv_local: 2,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::CountdownGeConst { i_idx: 3, c: 0 }),
    }
}

/// The STRIDE loop `while i < n { i = i + k }`: guard `Lt (Var 3)(Var 1)`, body
/// `i = i + k`. `i` is env index 3, bound `n` is env index 1, stride `k`.
fn loop_stride_function(k: i128) -> SemLoopFunction {
    SemLoopFunction {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(3),
            b: SemOperand::Var(1),
        }),
        body: vec![SemStmt {
            idx: 3,
            rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(3), SemOperand::Const(k)),
        }],
        inv_local: 2,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::StrideGeConst { i_idx: 3, c: 0, k }),
    }
}

/// The ACCUMULATOR loop `while i < n { s = s + 1; i = i + 1 }` with a MULTI-STATEMENT
/// body. Guard `Lt (Var 3)(Var 1)` over the counter `i` (env index 3); body is TWO
/// assignments — `s = s + 1` (accumulator `s`, env index 4) THEN `i = i + 1` (counter).
/// Bound `n` is env index 1. The synthesized invariant is the lower bound `0 ≤ s` on the
/// ACCUMULATOR (`AccumGeConst`).
fn loop_accum_function() -> SemLoopFunction {
    SemLoopFunction {
        cond: SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(3),
            b: SemOperand::Var(1),
        }),
        body: vec![
            // s := s + 1
            SemStmt {
                idx: 4,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(4), SemOperand::Const(1)),
            },
            // i := i + 1
            SemStmt {
                idx: 3,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(3), SemOperand::Const(1)),
            },
        ],
        inv_local: 2,
        inv_const: 0,
        synth_inv: Some(SynthInvariant::AccumGeConst { s_idx: 4, c: 0, i_idx: 3, n_idx: 1 }),
    }
}

// ---- (1) `≤`-GUARDED upper bound `i ≤ n+1` ----

#[test]
fn synth_le_upper_bound_loop_instance_proven_modulo_3() {
    // The while-rule INSTANTIATED at the SYNTHESIZED `≤`-guard upper bound `i ≤ n+1`,
    // with a GUARD-USING preservation proof (`Int.add_le_add_right` on the extracted
    // `i ≤ n`), kernel-checks the partial-correctness instance modulo 3.
    let lf = loop_count_le_function();
    assert_eq!(check_loop_refinement_instance(&lf), RefinementVerdict::ProvenModulo3);
}

#[test]
fn synth_le_upper_bound_total_correctness_modulo_3() {
    // The `≤`-guard upper bound composes with TOTAL correctness via the SYNTHESIZED
    // ranking `toNat((n+1) - i)` — `i ≤ n+1` holds at the halting state AND the loop halts.
    let lf = loop_count_le_function();
    let total = loop_total_correct_witness(&lf)
        .expect("≤-guard counter loop has a total-correctness certificate");
    assert!(total.is_modulo_3(), "the ≤-guard total-correctness instance must be modulo 3");
}

#[test]
fn wrong_synth_le_upper_bound_too_tight_fails_closed() {
    // FAIL-CLOSED: claiming the TOO-TIGHT `i ≤ n` (a `Lt`-style `CounterLeBound`) on a
    // `Le`-guarded loop. The codomain `Int.le (i+1) n` is NOT provided by the `Le` guard
    // `i ≤ n` (only `Lt` gives `i+1 ≤ n`), and `eval_cond` reduces to `decide (Int.le …)`,
    // not `decide (Int.lt …)`, so the `Lt`-extracting `of_decide_eq_true` proof is
    // ill-typed ⇒ KernelRejected.
    let lf = SemLoopFunction {
        synth_inv: Some(SynthInvariant::CounterLeBound { i_idx: 3, bound_idx: 1 }),
        ..loop_count_le_function()
    };
    assert!(
        matches!(check_loop_refinement_instance(&lf), RefinementVerdict::KernelRejected(_)),
        "the too-tight `i ≤ n` on a Le-guarded loop MUST be kernel-rejected"
    );
    assert!(loop_refinement_witness(&lf).is_none());
}

#[test]
fn wrong_synth_le_upper_bound_wrong_index_fails_closed() {
    // FAIL-CLOSED: `i ≤ m+1` for a bound index `m` (env index 2 = the untouched local)
    // the `Le` guard `i ≤ n` (env index 1) does NOT mention. The guard yields `i ≤ n`,
    // but the proof adds 1 to get `i+1 ≤ n+1` while the codomain demands `i+1 ≤ m+1`
    // (m ≠ n) ⇒ ill-typed ⇒ KernelRejected.
    let lf = SemLoopFunction {
        synth_inv: Some(SynthInvariant::CounterLeBoundSucc { i_idx: 3, bound_idx: 2 }),
        ..loop_count_le_function()
    };
    assert!(
        matches!(check_loop_refinement_instance(&lf), RefinementVerdict::KernelRejected(_)),
        "a Le upper bound against a non-guard index MUST be kernel-rejected"
    );
}

// ---- (1b) `≤`-guard CONJOINED range `c ≤ i ∧ i ≤ n+1` + postcondition ----

#[test]
fn synth_le_in_range_and_postcondition_modulo_3() {
    let lf = SemLoopFunction {
        synth_inv: Some(SynthInvariant::CounterInRangeSucc { i_idx: 3, c: 0, bound_idx: 1 }),
        ..loop_count_le_function()
    };
    // The conjoined range `0 ≤ i ∧ i ≤ n+1` kernel-checks modulo 3.
    assert_eq!(check_loop_refinement_instance(&lf), RefinementVerdict::ProvenModulo3);
    let total = loop_total_correct_witness(&lf).expect("range total-correctness");
    assert!(total.is_modulo_3());
    // It discharges `ret ≤ n+1` (the `≤`-loop returns `n+1`) by projecting the upper
    // conjunct `i ≤ n+1` at the halting state.
    let cert =
        loop_postcondition_witness(&lf, LoopPostcondition::RetLeBoundSucc { bound_idx: 1 })
            .expect("the Le upper bound discharges `ret ≤ n+1` modulo 3");
    assert!(cert.is_modulo_3());
    // And it discharges `0 ≤ ret` via the lower conjunct.
    let cert2 = loop_postcondition_witness(&lf, LoopPostcondition::ConstLeRet { c: 0 })
        .expect("the lower bound discharges `0 ≤ ret`");
    assert!(cert2.is_modulo_3());
}

