// ---- (4R) RELATIONAL accumulator invariant `s == i ∧ i ≤ n` (PART 1) ----

/// The SAME lockstep accumulator loop as [`loop_accum_function`], but carrying the
/// RELATIONAL conjoined invariant `s == i ∧ i ≤ n` (`AccumEqCounter`) instead of the bare
/// lower bound. `s` is env index 4, `i` is 3, the guard bound `n` is 1.
fn loop_accum_eq_function() -> SemLoopFunction {
    SemLoopFunction {
        synth_inv: Some(SynthInvariant::AccumEqCounter { s_idx: 4, i_idx: 3, n_idx: 1 }),
        ..loop_accum_function()
    }
}

#[test]
fn synth_accum_eq_relational_loop_instance_proven_modulo_3() {
    // The while-rule INSTANTIATED at the RELATIONAL `s == i ∧ i ≤ n`. Preservation is the
    // `And.intro` of the CONGRUENCE step (`s == i → s+1 == i+1` via `congrArg (·+1)`) and
    // the guard-aware upper bound (`i < n → i+1 ≤ n`), kernel-checked modulo 3.
    let lf = loop_accum_eq_function();
    assert_eq!(check_loop_refinement_instance(&lf), RefinementVerdict::ProvenModulo3);
    let cert =
        loop_refinement_witness(&lf).expect("relational accum loop has a partial certificate");
    assert!(cert.is_modulo_3(), "the relational partial instance must be modulo 3");
}

#[test]
fn synth_accum_eq_relational_total_correctness_modulo_3() {
    // TOTAL correctness: `s == i ∧ i ≤ n` holds at the halting state AND the loop halts via
    // the ranking `toNat(n − i)` over the GUARD counter `i` (same termination as the bare
    // accumulator — the invariant is relational, but the measure is still over `i`).
    let lf = loop_accum_eq_function();
    let total = loop_total_correct_witness(&lf)
        .expect("relational accumulator loop has a total-correctness certificate");
    assert!(total.is_modulo_3(), "the relational total-correctness instance must be modulo 3");
}

#[test]
fn synth_accum_eq_relational_axiom_deps_subset_of_3() {
    // The relational TOTAL instance rests on ⊆ the 3 foundational axioms (no 4th axiom —
    // `congrArg`/`Eq.subst`/`Eq.symm`/`And.intro`/`of_decide_eq_true` are all modulo 3).
    let lf = loop_accum_eq_function();
    assert_eq!(
        check_loop_total_correct_instance(&lf),
        RefinementVerdict::ProvenModulo3,
        "the relational total instance must be ProvenModulo3 (axiom residue ⊆ 3)"
    );
}

#[test]
fn synth_accum_eq_relational_postcondition_ret_le_n_modulo_3() {
    // The STRONGER postcondition `ret ≤ n` (which the bare lower bound `0 ≤ s` CANNOT
    // discharge): at the halting state project `s == i` and `i ≤ n` out of the relational
    // invariant, then `Eq.subst` along `i = s` to rewrite `i ≤ n` into `s ≤ n` (`ret = s`),
    // kernel-checked modulo 3.
    let lf = loop_accum_eq_function();
    let cert = loop_postcondition_witness(&lf, LoopPostcondition::RetLeBound { bound_idx: 1 })
        .expect("the relational invariant discharges `ret ≤ n` modulo 3");
    assert!(cert.is_modulo_3(), "the relational postcondition discharge must be modulo 3");
}

#[test]
fn wrong_synth_accum_eq_relation_off_by_one_fails_closed() {
    // FAIL-CLOSED: the WRONG relational invariant `s == i + 1` (the off-by-one offset). The
    // congruence proof builds `s == i → s+1 == i+1`, but with the invariant `s == i+1` the
    // hypothesis is `s == i+1` and the codomain (after the body) is `s+1 == i+1`, so
    // `congrArg (·+1) (hI : s == i+1) : s+1 == (i+1)+1` ≠ the codomain `s+1 == i+1`
    // ⇒ ill-typed ⇒ KernelRejected. We encode `s == i + 1` by pointing the equality's RHS
    // index at a DISTINCT local; here we use a synthetic invariant via the n_idx swap so the
    // built `Eq` operands disagree with the body reduction.
    // The cleanest off-by-one is a relation against a local the body increments differently.
    // We exercise it by claiming `s == i` but with the accumulator body that adds 2 (below).
    // Here we directly verify the congruence is genuine by mutating the body's accum stride.
    let lf = SemLoopFunction {
        body: vec![
            // s := s + 2 (NOT lockstep with i := i + 1) — breaks `s == i` preservation.
            SemStmt {
                idx: 4,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(4), SemOperand::Const(2)),
            },
            SemStmt {
                idx: 3,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(3), SemOperand::Const(1)),
            },
        ],
        synth_inv: Some(SynthInvariant::AccumEqCounter { s_idx: 4, i_idx: 3, n_idx: 1 }),
        ..loop_accum_function()
    };
    // Codomain LEFT conjunct is `(s+2) == (i+1)`, but `congrArg (·+1) (hI : s == i)` proves
    // `(s+1) == (i+1)` ≠ `(s+2) == (i+1)` ⇒ KernelRejected.
    assert!(
        matches!(check_loop_refinement_instance(&lf), RefinementVerdict::KernelRejected(_)),
        "the relational `s == i` on a NON-lockstep (s += 2) body MUST be kernel-rejected"
    );
    assert!(loop_refinement_witness(&lf).is_none());
}

#[test]
fn wrong_synth_accum_eq_relation_counter_stride_2_fails_closed() {
    // FAIL-CLOSED (the mirror): `s == i` claimed when the COUNTER advances by 2 but the
    // accumulator by 1 — `(s+1) == (i+2)` codomain, `congrArg (·+1) (hI : s == i)` proves
    // `(s+1) == (i+1)` ≠ `(s+1) == (i+2)` ⇒ KernelRejected.
    let lf = SemLoopFunction {
        body: vec![
            SemStmt {
                idx: 4,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(4), SemOperand::Const(1)),
            },
            // i := i + 2 (NOT lockstep with s := s + 1).
            SemStmt {
                idx: 3,
                rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(3), SemOperand::Const(2)),
            },
        ],
        synth_inv: Some(SynthInvariant::AccumEqCounter { s_idx: 4, i_idx: 3, n_idx: 1 }),
        ..loop_accum_function()
    };
    assert!(
        matches!(check_loop_refinement_instance(&lf), RefinementVerdict::KernelRejected(_)),
        "the relational `s == i` on an i+=2 (non-lockstep) body MUST be kernel-rejected"
    );
}

#[test]
fn wrong_synth_accum_eq_relation_postcondition_wrong_bound_fails_closed() {
    // FAIL-CLOSED: `ret ≤ m` for a bound `m` (env index 2) that is NOT the guard bound `n`
    // (env index 1) the relational invariant's upper conjunct uses. The discharge needs the
    // halt's `i ≤ n` projected at index 1; demanding `s ≤ (e 2)` cannot be built ⇒ None.
    let lf = loop_accum_eq_function();
    assert!(
        loop_postcondition_witness(&lf, LoopPostcondition::RetLeBound { bound_idx: 2 })
            .is_none(),
        "the relational invariant MUST NOT discharge `ret ≤ m` for a non-guard bound m"
    );
}

#[test]
fn new_shape_recognizers_are_disjoint() {
    // The three recognizers each match ONLY their own shape (no cross-talk).
    let le = loop_count_le_function();
    let cd = loop_countdown_function();
    let st = loop_stride_function(3);
    assert!(recognize_counter_le_loop(&le).is_some() && recognize_counter_loop(&le).is_none());
    assert!(recognize_countdown_loop(&cd).is_some() && recognize_counter_loop(&cd).is_none());
    assert!(recognize_stride_loop(&st).is_some());
    // The original `+1`/`Lt` counter loop is a stride loop with k=1 — recognize_stride
    // accepts it (k=1 ≥ 1), but recognize_counter_le rejects it (wrong guard op).
    assert!(recognize_counter_le_loop(&loop_keep_zero_function()).is_none());
    assert!(recognize_countdown_loop(&loop_keep_zero_function()).is_none());
}

