fn remap_result_error_discriminants(
    ty: &mut trust_types::Ty,
    result_discriminants: [i128; 2],
    error_discriminants: [i128; 4],
) {
    let trust_types::Ty::Adt { name, variants, .. } = ty else {
        panic!("expected Result enum type")
    };
    assert_eq!(name, "core::result::Result");
    assert_eq!(variants.len(), result_discriminants.len());
    for (variant, discriminant) in variants.iter_mut().zip(result_discriminants) {
        variant.discriminant = discriminant;
    }
    let (_, nested_ty) = variants[1].fields.get_mut(0).expect("Err payload type");
    let trust_types::Ty::Adt { name, variants, .. } = nested_ty else {
        panic!("expected Error enum type")
    };
    assert_eq!(name, "Error");
    assert_eq!(variants.len(), error_discriminants.len());
    for (variant, discriminant) in variants.iter_mut().zip(error_discriminants) {
        variant.discriminant = discriminant;
    }
}

fn remap_error_discriminants(ty: &mut trust_types::Ty, discriminants: [i128; 4]) {
    let trust_types::Ty::Adt { name, variants, .. } = ty else {
        panic!("expected Error enum type")
    };
    assert_eq!(name, "Error");
    assert_eq!(variants.len(), discriminants.len());
    for (variant, discriminant) in variants.iter_mut().zip(discriminants) {
        variant.discriminant = discriminant;
    }
}

// ---- Trust: W20 REFERENCE-RETURN test fixtures + adversarial probes (2026-07-21) ----
//
// TIER (stated verbatim, the direction of record): an immutable reference RETURN
// denotes its referent's ELEMENT VALUE at the idx_elem tier — `Some(&s[0])` certifies
// as "Some of the element-0 value-slot" (`idxElem(s, 0)`) deref-transparently,
// consistent with W-REF-FWD's ref/deref cancellation and &self-param transparency.
// NOT an address/aliasing claim.

/// `Option<&i32>` outer enum (None=0, Some=1 carrying `&i32`) — the return type of
/// `slice::first`/`SliceIndex::get`/`slice::last`. `Ty::adt_enum` defaults
/// `disc_index_safe:false` (the niche layout), so the Discriminant/Aggregate stay
/// ABSTRACT — no `__tag` field read anywhere in this lane.
fn option_ref_i32_ty() -> trust_types::Ty {
    use trust_types::{Ty, VariantDef};
    let ref_i32 =
        || Ty::Ref { mutable: false, inner: Box::new(Ty::Int { width: 32, signed: true }) };
    Ty::adt_enum(
        "std::option::Option",
        vec![
            VariantDef { name: "None".into(), discriminant: 0, fields: vec![] },
            VariantDef {
                name: "Some".into(),
                discriminant: 1,
                fields: vec![("0".into(), ref_i32())],
            },
        ],
    )
}

fn slice_i32_ref_ty() -> trust_types::Ty {
    use trust_types::Ty;
    Ty::Ref {
        mutable: false,
        inner: Box::new(Ty::Slice { elem: Box::new(Ty::Int { width: 32, signed: true }) }),
    }
}

fn ref_i32_ty() -> trust_types::Ty {
    trust_types::Ty::Ref { mutable: false, inner: Box::new(trust_types::Ty::Int { width: 32, signed: true }) }
}

fn usize_ty() -> trust_types::Ty {
    trust_types::Ty::Int { width: 64, signed: false }
}

/// Guard-false ELSE arm `_0 = None` block (shared by first/get/last).
