/// trust-mir-df5677ea377c3787 (guard `Ge(PtrMetadata(_1), 1)`,
/// `Ref [Deref, ConstantIndex{offset:1, min_length:1, from_end:true}]` — index `len-1`).
fn slice_last_func() -> trust_types::VerifiableFunction {
    use trust_types::{Projection, Rvalue, Statement};
    let mut func = slice_first_func();
    func.name = "last".into();
    func.def_path = "core::slice::<impl [i32]>::last".into();
    // Swap the ConstantIndex to the from_end (len - 1) projection.
    let Statement::Assign { rvalue: Rvalue::Ref { place, .. }, .. } =
        &mut func.body.blocks[1].stmts[0]
    else {
        unreachable!("bb1 stmt0 is the Ref")
    };
    place.projections = vec![
        Projection::Deref,
        Projection::ConstantIndex { offset: 1, min_length: 1, from_end: true },
    ];
    func
}

// ----------------------------------------------------------------------
// POSITIVE recognition — first + get flip; last declines honestly.
// ----------------------------------------------------------------------

#[test]
fn sem_adt_return_shape_of_recognizes_slice_first() {
    let shape = sem_adt_return_shape_of(&slice_first_func())
        .expect("slice::first's guarded reference-return shape must be recognized");
    assert_eq!(shape.enum_name, "std::option::Option");
    // THEN (guard `len >= 1` true) constructs `Some(idxElem(s, 0))` — the element-0
    // VALUE-SLOT, deref-transparently. Variant Some = discriminant 1.
    assert_eq!(shape.then_arm.variant, 1);
    assert_eq!(
        shape.then_arm.payload,
        Some(SemAdtPayload::Scalar(SemOperand::Index(
            Box::new(SemOperand::Var(0)),
            Box::new(SemOperand::Const(0)),
        )))
    );
    // ELSE (guard false) constructs `None` = discriminant 0, no payload.
    assert_eq!(shape.else_arm.variant, 0);
    assert_eq!(shape.else_arm.payload, None);
    // The guard is the slice-length comparison `Ge(sliceLen(s), 1)` over the SAME
    // slice handle the payload keys.
    assert_eq!(
        shape.cond,
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Ge,
            a: SemOperand::Len(Box::new(SemOperand::Var(0))),
            b: SemOperand::Const(1),
        })
    );
}

#[test]
fn sem_adt_return_shape_of_recognizes_slice_index_get() {
    let shape = sem_adt_return_shape_of(&slice_get_func())
        .expect("SliceIndex::get's guarded reference-return shape must be recognized");
    // THEN constructs `Some(idxElem(slice, i))` — base is the SLICE param (Var 1),
    // index is the usize param (Var 0).
    assert_eq!(shape.then_arm.variant, 1);
    assert_eq!(
        shape.then_arm.payload,
        Some(SemAdtPayload::Scalar(SemOperand::Index(
            Box::new(SemOperand::Var(1)),
            Box::new(SemOperand::Var(0)),
        )))
    );
    assert_eq!(shape.else_arm.payload, None);
    // Guard `Lt(i, sliceLen(slice))` keyed to the SAME slice handle + index operand.
    assert_eq!(
        shape.cond,
        SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Lt,
            a: SemOperand::Var(0),
            b: SemOperand::Len(Box::new(SemOperand::Var(1))),
        })
    );
}

#[test]
fn sem_adt_return_shape_of_declines_slice_last_no_carrier() {
    // slice::last's referent index is `sliceLen(s) - 1`, which no current SemOperand
    // composes (no Sub / Len-minus-const carrier; PreOp is Not/Neg only). The guard
    // coherence gate PASSES (from_end:true, 1 <= 1 <= K, m <= K), but the value
    // constructor declines HONESTLY for lack of the carrier — fail-closed `None`.
    assert!(
        sem_adt_return_shape_of(&slice_last_func()).is_none(),
        "slice::last must decline: the len-1 index term has no SemOperand carrier yet"
    );
    // The from_end:true clause of the coherence gate ITSELF admits the well-formed
    // last projection (so the decline is the missing carrier, not a false OOB reject).
    assert!(slice_ref_guard_coherent(
        &SemCondTree::Leaf(SemCond {
            op: SemCmpOp::Ge,
            a: SemOperand::Len(Box::new(SemOperand::Var(0))),
            b: SemOperand::Const(1),
        }),
        &SliceRefProj {
            base_param: 0,
            kind: SliceRefProjKind::ConstantIndex { offset: 1, min_length: 1, from_end: true },
        },
    ));
}

