// MANDATORY GATE 1 (dedicated): RAW-EXPOSURE alias-set discipline.
// ----------------------------------------------------------------------

#[test]
fn raw_exposure_exists_flags_addressof_of_base_and_shared_ref_aliases() {
    use trust_types::{Operand, Place, Projection, Rvalue, Statement};
    // No AddressOf → not exposed.
    assert!(!raw_exposure_exists(&slice_first_func().body, 1), "clean body: no raw exposure");
    // AddressOf of an UNRELATED local → not exposed for the base.
    {
        let mut func = slice_first_func();
        func.body.blocks[1].stmts.insert(
            0,
            Statement::Assign {
                place: Place::local(4),
                rvalue: Rvalue::AddressOf(false, Place::local(3)),
                span: Default::default(),
            },
        );
        assert!(!raw_exposure_exists(&func.body, 1), "AddressOf of an unrelated local is fine");
    }
    // AddressOf of a SHARED-REF ALIAS copy of the base → exposed (alias-set closure).
    {
        let mut func = slice_first_func();
        // `_5 := Copy(_1)` (whole-local shared-ref alias), then `&raw const _5`.
        func.body.locals.push(trust_types::LocalDecl {
            index: 5,
            ty: slice_i32_ref_ty(),
            name: None,
        });
        func.body.blocks[0].stmts.push(Statement::Assign {
            place: Place::local(5),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
            span: Default::default(),
        });
        func.body.blocks[0].stmts.push(Statement::Assign {
            place: Place::local(4),
            rvalue: Rvalue::AddressOf(
                false,
                Place { local: 5, projections: vec![Projection::Deref] },
            ),
            span: Default::default(),
        });
        assert!(
            raw_exposure_exists(&func.body, 1),
            "a raw address-of a shared-ref alias of the base must be flagged"
        );
    }
}

#[test]
fn sem_adt_return_shape_of_recognizes_half_promotion() {
    let func = half_promotion_func();
    let shape =
        sem_adt_return_shape_of(&func).expect("the half_promotion! shape must be recognized");
    assert_eq!(shape.enum_name, "core::result::Result");
    // THEN (guard `src < 0` true) constructs `Err(Error::Underflow)` — the
    // Aggregate indices 1 and 3 map through their declared enum metadata to
    // discriminants 1 and 3.
    assert_eq!(shape.then_arm.variant, 1);
    assert_eq!(
        shape.then_arm.payload,
        Some(SemAdtPayload::NullaryNested { enum_name: "Error".to_string(), variant: 3 })
    );
    // ELSE constructs `Ok(src as u16)` — variant 0, preserving the exact
    // same-width sign-changing cast rather than claiming it is unconditionally
    // identical to the source.
    assert_eq!(shape.else_arm.variant, 0);
    assert_eq!(
        shape.else_arm.payload,
        Some(SemAdtPayload::IntCast { source: SemOperand::Var(0), width: 16, signed: false })
    );
}

#[test]
fn sem_adt_return_shape_maps_variant_indices_to_declared_discriminants() {
    let mut func = half_promotion_func();
    let result_discriminants = [10, 20];
    let error_discriminants = [30, 31, 32, 33];
    remap_result_error_discriminants(
        &mut func.body.return_ty,
        result_discriminants,
        error_discriminants,
    );
    remap_result_error_discriminants(
        &mut func.body.locals[0].ty,
        result_discriminants,
        error_discriminants,
    );
    remap_error_discriminants(&mut func.body.locals[3].ty, error_discriminants);

    let shape = sem_adt_return_shape_of(&func)
        .expect("explicit-discriminant Result/Error shape must be recognized");
    assert_eq!(shape.then_arm.variant, 20);
    assert_eq!(
        shape.then_arm.payload,
        Some(SemAdtPayload::NullaryNested { enum_name: "Error".to_string(), variant: 33 })
    );
    assert_eq!(shape.else_arm.variant, 10);
}

