/// ADVERSARIAL PROBE (c): an EXTRA write to `_0` (the return local) beyond the two
/// recognized arms — even in an otherwise-dead block — must decline the WHOLE
/// shape (the complete exact-two rooted-write well-formedness gate).
#[test]
fn sem_adt_return_shape_of_declines_extra_write_to_return_local() {
    use trust_types::{
        AggregateKind, BasicBlock, BlockId, Operand, Place, Rvalue, Statement, Terminator,
    };
    let mut func = half_promotion_func();
    // A spurious THIRD `_0`-writing, Goto-terminated block (unreachable from the
    // guard, but the recognizer's write-count gate is NOT reachability-scoped —
    // by design, so it cannot be fooled by a write hidden off the modeled path).
    func.body.blocks.push(BasicBlock {
        id: BlockId(4),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Aggregate(
                AggregateKind::Adt {
                    name: "core::result::Result".into(),
                    variant: 0,
                    active_field: None,
                    args: None,
                },
                vec![Operand::Copy(Place::local(1))],
            ),
            span: Default::default(),
        }],
        terminator: Terminator::Goto(BlockId(3)),
    });
    assert!(
        sem_adt_return_shape_of(&func).is_none(),
        "an extra write to the return local must decline the WHOLE shape"
    );
}

/// ADVERSARIAL PROBE (d): a genuine 3-ARM guarded return (the `from_signed!`-class
/// shape: `Err(if a {Underflow} else if b {Overflow} else {return Ok(..)})`) must
/// decline — the recognizer's 2-arm assumption (`arms.len() != 2`) is not fooled
/// into picking an arbitrary two of the three arms. Modeled here by simply adding a
/// THIRD `_0`-writing Goto arm block (reachable or not — the arm-COUNT gate fires
/// regardless, the same defense-in-depth [`sem_adt_return_shape_of_declines_extra_write_to_return_local`]
/// exercises via the write-count gate; this probe specifically pins the `arms.len()
/// != 2` clause by using a DISTINCT convergence block so both gates are exercised
/// independently across the two tests).
#[test]
fn sem_adt_return_shape_of_declines_three_arm_shape() {
    use trust_types::{
        AggregateKind, BasicBlock, BlockId, Operand, Place, Rvalue, Statement, Terminator,
    };
    let mut func = half_promotion_func();
    func.body.blocks.push(BasicBlock {
        id: BlockId(4),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Aggregate(
                AggregateKind::Adt {
                    name: "core::result::Result".into(),
                    variant: 0,
                    active_field: None,
                    args: None,
                },
                vec![Operand::Copy(Place::local(1))],
            ),
            span: Default::default(),
        }],
        terminator: Terminator::Goto(BlockId(3)), // SAME join as the other two arms.
    });
    assert!(
        sem_adt_return_shape_of(&func).is_none(),
        "a genuine 3-arm guarded ADT return must decline (2-variant assumption)"
    );
}

