#[test]
fn sem_adt_return_opaque_declines_nonterminal_field_ref_call() {
    use trust_types::{BasicBlock, BlockId, LocalDecl, Operand, Place, Terminator};

    let mut func = fvarsubst_fold_fvar_opt_func();
    let next_local = func.body.locals.len();
    func.body.locals.push(LocalDecl { index: next_local, ty: expr_ty(), name: None });
    let Terminator::Call { target, .. } = &mut func.body.blocks[2].terminator else {
        panic!("bb2 must be the replacement clone call")
    };
    *target = Some(BlockId(6));
    func.body.blocks.push(BasicBlock {
        id: BlockId(6),
        stmts: vec![],
        terminator: Terminator::Call {
            func: "adversary::postprocess".into(),
            args: vec![Operand::Move(Place::local(6))],
            dest: Place::local(next_local),
            target: Some(BlockId(3)),
            unwind: trust_types::UnwindEdge::Unreachable,
            span: Default::default(),
            atomic: None,
            is_foreign: false,
            is_unsafe_sig: false,
        },
    });
    let trust_types::Statement::Assign { rvalue, .. } = &mut func.body.blocks[3].stmts[0]
    else {
        panic!("bb3 must construct Some")
    };
    let trust_types::Rvalue::Aggregate(_, operands) = rvalue else {
        panic!("bb3 must construct Some")
    };
    operands[0] = Operand::Move(Place::local(next_local));
    assert!(trust_vcgen::validate_function(&func).is_ok());
    assert!(crate::assignment_types::all_assignments_match(&func.body));
    assert!(
        sem_adt_return_opaque_shape_of(&func).is_none(),
        "a field-reference call must itself be the final direct opaque payload step"
    );
}

#[test]
fn sem_adt_return_opaque_declines_non_shared_field_snapshots() {
    use trust_types::Ty;

    for (case, field_ty) in [
        ("mutable reference", ref_of(expr_ty(), true)),
        ("raw pointer", Ty::RawPtr { mutable: true, pointee: Box::new(expr_ty()) }),
        ("non-reference ADT", fvar_id_ty()),
    ] {
        let mut func = fvarsubst_fold_fvar_opt_func();
        let Ty::Ref { inner: self_ty, .. } = &mut func.body.locals[1].ty else {
            panic!("self must be a reference")
        };
        let Ty::Adt { fields, .. } = self_ty.as_mut() else {
            panic!("self referent must be an ADT")
        };
        fields[1].1 = field_ty.clone();
        func.body.locals[7].ty = field_ty;
        assert!(trust_vcgen::validate_function(&func).is_ok(), "{case}");
        assert!(crate::assignment_types::all_assignments_match(&func.body), "{case}");
        assert!(
            sem_adt_return_opaque_shape_of(&func).is_none(),
            "{case} must not acquire FieldRefArg authority"
        );
    }
}

