// =====================================================================
// Trust: SCALAR SENTINEL-SELECT (cmp-mono-select, 2026-07-16) — recognizer
// tests over the REAL committed `<iN as Ord>::min`/`::max` dumps + the four
// REQUIRED forgery probes (each MUST stay declined / SHAPE_GAP).
// =====================================================================

/// Load the committed `cmp-mono-select` dump whose `def_path` matches exactly.
/// `None` if the fixture directory is absent in this checkout (the caller then
/// no-ops, mirroring the `bit_field` fixture tests).
fn load_cmp_select_fixture(def_path: &str) -> Option<trust_types::VerifiableFunction> {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("fixtures/cmp-mono-select-2026-07-16/dumps");
    for e in std::fs::read_dir(&dir).ok()?.filter_map(Result::ok) {
        let p = e.path();
        if p.extension().and_then(|x| x.to_str()) != Some("json") {
            continue;
        }
        let Ok(bytes) = std::fs::read(&p) else { continue };
        if let Ok(f) = serde_json::from_slice::<trust_types::VerifiableFunction>(&bytes) {
            if f.def_path == def_path {
                return Some(f);
            }
        }
    }
    None
}

/// Rewrite the FIRST `_0 := <rvalue>` arm assignment found (in block order) to
/// `new_rvalue` — the mutation the arm-value forgery probes use.
fn rewrite_first_ret_assign(
    func: &mut trust_types::VerifiableFunction,
    new_rvalue: trust_types::Rvalue,
) {
    for b in &mut func.body.blocks {
        for s in &mut b.stmts {
            if let trust_types::Statement::Assign { place, rvalue, .. } = s {
                if place.local == 0 && place.projections.is_empty() {
                    *rvalue = new_rvalue;
                    return;
                }
            }
        }
    }
    panic!("no `_0 := …` arm assignment found to rewrite");
}

/// POSITIVE (real fixtures): every monomorphized `<iN as Ord>::min`/`::max` in
/// the committed corpus recognizes as a SCALAR SENTINEL-SELECT, its two arms
/// select the two DISTINCT by-value params, and its kernel witness proves
/// modulo 3 (both `g=true→then` and `g=false→else`).
#[test]
fn scalar_sentinel_select_real_ord_min_max_fixtures_certify_modulo_3() {
    use crate::trustir_anchor::RefinementVerdict;
    let mut seen = 0usize;
    for def_path in [
        "<i32 as std::cmp::Ord>::min",
        "<i32 as std::cmp::Ord>::max",
        "<i64 as std::cmp::Ord>::min",
        "<i64 as std::cmp::Ord>::max",
        "<u8 as std::cmp::Ord>::min",
        "<u8 as std::cmp::Ord>::max",
    ] {
        let Some(func) = load_cmp_select_fixture(def_path) else { continue };
        seen += 1;
        let shape = sem_scalar_sentinel_select_shape_of(&func)
            .unwrap_or_else(|| panic!("{def_path}: must recognize the scalar sentinel-select"));
        assert_ne!(
            shape.then_var, shape.else_var,
            "{def_path}: the two arms must select DISTINCT params"
        );
        assert!(
            shape.then_var <= 1 && shape.else_var <= 1,
            "{def_path}: arm params must be the two by-value params {{0,1}}"
        );
        assert!(
            matches!(
                crate::trustir_adt::check_scalar_sentinel_select_refinement(&shape),
                RefinementVerdict::ProvenModulo3
            ),
            "{def_path}: the kernel witness must prove modulo 3"
        );
    }
    // If the corpus is present, ALL SIX must have recognized.
    if load_cmp_select_fixture("<u8 as std::cmp::Ord>::min").is_some() {
        assert_eq!(seen, 6, "all six Ord::min/max fixtures must recognize");
    }
}

