/// ADVERSARIAL PROBE: a genuine THIRD switch (a 4-outcome guard ladder) must
/// decline — the recognizer's `switches.len() != 2` gate is not fooled into
/// picking an arbitrary two of the three.
#[test]
fn sem_adt_return_shape_of_chain_declines_three_switch_shape() {
    use trust_types::{
        BasicBlock, BinOp, BlockId, ConstValue, Operand, Place, Rvalue, Statement, Terminator,
    };
    let mut func = from_signed_func();
    // Splice a THIRD switch into bb4's (the Ok arm's) own path: rename bb4 to
    // test a bogus extra condition before it does its real work, keeping the
    // shape otherwise intact but adding one more decision point.
    let extra_id = trust_types::BlockId(7);
    let mut bb4 = func.body.blocks[4].clone();
    func.body.blocks[4] = BasicBlock {
        id: BlockId(4),
        stmts: vec![Statement::Assign {
            place: Place::local(5), // reuse a Bool-typed local for the bogus test.
            rvalue: Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(1)),
                Operand::Constant(ConstValue::Int(0)),
            ),
            span: Default::default(),
        }],
        terminator: Terminator::SwitchInt {
            discr: Operand::Move(Place::local(5)),
            targets: vec![(0, extra_id)],
            otherwise: extra_id,
            exhaustive_enum_unreachable: false,
            span: Default::default(),
        },
    };
    bb4.id = extra_id;
    func.body.blocks.push(bb4);
    assert!(
        sem_adt_return_shape_of_chain(&func).is_none(),
        "a genuine third switch (4-outcome ladder) must decline (switches.len() != 2)"
    );
}

/// ADVERSARIAL PROBE: the shared payload temp `_2` MUTABLY ALIASED anywhere in
/// the function (a `&mut _2` taken, even off the modeled path) must decline —
/// `chain_local_not_aliased`'s whole-body defense, since a walk-local scan
/// alone cannot see a write through that alias.
#[test]
fn sem_adt_return_shape_of_chain_declines_mutably_aliased_payload() {
    use trust_types::{BasicBlock, BlockId, Place, Rvalue, Statement, Terminator};
    let mut func = from_signed_func();
    func.body.locals.push(trust_types::LocalDecl {
        index: 8,
        ty: trust_types::Ty::Ref {
            mutable: true,
            inner: Box::new(trust_types::Ty::adt(
                "Error",
                vec![("__tag".into(), trust_types::Ty::Int { width: 64, signed: true })],
            )),
        },
        name: None,
    });
    func.body.blocks.push(BasicBlock {
        id: BlockId(7),
        stmts: vec![Statement::Assign {
            place: Place::local(8),
            rvalue: Rvalue::Ref { mutable: true, place: Place::local(2) },
            span: Default::default(),
        }],
        terminator: Terminator::Unreachable,
    });
    assert!(
        sem_adt_return_shape_of_chain(&func).is_none(),
        "a mutably-aliased payload temp must decline, even off the modeled path"
    );
}

/// ADVERSARIAL PROBE, gap-queue #2 follow-up #2 investigation (module doc's
/// FLOAT-GUARD fail-closed gate): a comparison between two FLOAT-typed `Var`
/// operands (the real `from_float!`-class `src != src` NaN self-check shape) must
/// decline the WHOLE shape — never silently misdenote a float comparison as
/// an `Int` one over the same env slot.
#[test]
fn sem_adt_return_shape_of_chain_declines_float_typed_guard_operands() {
    use trust_types::{BinOp, Operand, Place, Rvalue, Statement, Ty};
    let mut func = from_signed_func();
    func.body.locals[1].ty = Ty::Float { width: 32 };
    let Statement::Assign { rvalue, .. } = &mut func.body.blocks[0].stmts[1] else {
        panic!("bb0's second stmt must be the `_3 := cmp(..)` guard assignment");
    };
    *rvalue = Rvalue::BinaryOp(
        BinOp::Ne,
        Operand::Copy(Place::local(1)),
        Operand::Copy(Place::local(1)),
    );
    assert!(
        sem_adt_return_shape_of_chain(&func).is_none(),
        "a float-typed Var-vs-Var comparison must decline, not misdenote as an Int comparison"
    );
}

// -------------------------------------------------------------------
// DISCRIMINANT-SWITCH ADT-RETURN, 3-ARM (M5 residue #1, 2026-07-08) — the
// `Ordering::reverse`-class shape. `reverse_switch3_func` mirrors the REAL
// `core` dump BYTE-FOR-BLOCK
// (`fixtures/census-core-m5-2026-07-07/cmp-ordering/cmp__Ordering__reverse.json`):
//
//   bb0: _2 := Discriminant(_1);
//        SwitchInt(_2) {255→bb4, 0→bb3, 1→bb2}, otherwise→bb1 (exhaustive)
//   bb1: Unreachable
//   bb2: _0 := Ordering::Arm0 (variant 0, "Less");   Goto bb5
//   bb3: _0 := Ordering::Arm1 (variant 1, "Equal");  Goto bb5
//   bb4: _0 := Ordering::Arm2 (variant 2, "Greater"); Goto bb5
//   bb5: Return
// -------------------------------------------------------------------

fn ordering_ty() -> trust_types::Ty {
    trust_types::Ty::adt_enum(
        "cmp::Ordering",
        vec![
            trust_types::VariantDef { name: "Less".into(), discriminant: -1, fields: vec![] },
            trust_types::VariantDef { name: "Equal".into(), discriminant: 0, fields: vec![] },
            trust_types::VariantDef { name: "Greater".into(), discriminant: 1, fields: vec![] },
        ],
    )
}

fn reverse_switch3_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        AggregateKind, BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let i8t = || Ty::Int { width: 8, signed: true };
    let variant_arm = |id: usize, variant: usize, goto: usize| BasicBlock {
        id: BlockId(id),
        stmts: vec![Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Aggregate(
                AggregateKind::Adt {
                    name: "cmp::Ordering".into(),
                    variant,
                    active_field: None,
                    args: None,
                },
                vec![],
            ),
            span: Default::default(),
        }],
        terminator: Terminator::Goto(BlockId(goto)),
    };
    VerifiableFunction {
        name: "reverse".into(),
        def_path: "cmp::Ordering::reverse".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: ordering_ty(), name: None },
                LocalDecl { index: 1, ty: ordering_ty(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: i8t(), name: None },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Discriminant(Place::local(1)),
                        span: Default::default(),
                    }],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Move(Place::local(2)),
                        targets: vec![(255, BlockId(4)), (0, BlockId(3)), (1, BlockId(2))],
                        otherwise: BlockId(1),
                        exhaustive_enum_unreachable: true,
                        span: Default::default(),
                    },
                },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![],
                    terminator: Terminator::Unreachable,
                },
                variant_arm(2, 0, 5),
                variant_arm(3, 1, 5),
                variant_arm(4, 2, 5),
                BasicBlock { id: BlockId(5), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 1,
            return_ty: ordering_ty(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn sem_adt_return_shape_of_discriminant_switch3_recognizes_reverse() {
    let func = reverse_switch3_func();
    let shape = sem_adt_return_shape_of_discriminant_switch3(&func)
        .expect("the reverse! 3-arm discriminant-switch shape must be recognized");
    assert_eq!(shape.enum_name, "cmp::Ordering");
    let SemCondTree::Leaf(c1) = &shape.cond1 else { panic!("cond1 must be a bare leaf") };
    assert_eq!(c1.op, SemCmpOp::Eq);
    assert_eq!(c1.a, SemOperand::Discriminant(Box::new(SemOperand::Var(0))));
    assert_eq!(c1.b, SemOperand::Const(255));
    let SemCondTree::Leaf(c2) = &shape.cond2 else { panic!("cond2 must be a bare leaf") };
    assert_eq!(c2.op, SemCmpOp::Eq);
    assert_eq!(c2.a, SemOperand::Discriminant(Box::new(SemOperand::Var(0))));
    assert_eq!(c2.b, SemOperand::Const(0));
    assert_eq!(shape.arm_a, SemAdtArm { variant: 1, payload: None }); // tag 255 → bb4 → Greater
    assert_eq!(shape.arm_b, SemAdtArm { variant: 0, payload: None }); // tag 0 → bb3 → Equal
    assert_eq!(shape.arm_c, SemAdtArm { variant: -1, payload: None }); // fallthrough bb2 → Less
    assert_eq!(
        crate::trustir_adt::check_adt_return3_refinement(&shape),
        crate::trustir_anchor::RefinementVerdict::ProvenModulo3
    );
}

