// -------------------------------------------------------------------
// `Ord::cmp` THREE-WAY COMPARE (M5 residue #2, 2026-07-08) — the primitive
// `Ord::cmp` impls' shape. `cmp_binop_func` mirrors the REAL `core` dump
// BYTE-FOR-BLOCK
// (`fixtures/census-core-m5-2026-07-07/cmp-ordering/cmp__impls__<impl cmp__Ord for i32>__cmp.json`):
//
//   bb0: _3 := Copy(*_1); _4 := Copy(*_2); _0 := BinaryOp(Cmp, Move(_3), Move(_4)); Return
// -------------------------------------------------------------------

fn cmp_binop_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BinOp, BlockId, LocalDecl, Operand, Place, Projection, Rvalue, Statement,
        Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let i32t = || Ty::Int { width: 32, signed: true };
    let ref_i32 = || Ty::Ref { mutable: false, inner: Box::new(i32t()) };
    VerifiableFunction {
        name: "cmp".into(),
        def_path: "cmp::impls::<impl cmp::Ord for i32>::cmp".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: ordering_ty(), name: None },
                LocalDecl { index: 1, ty: ref_i32(), name: Some("self".into()) },
                LocalDecl { index: 2, ty: ref_i32(), name: Some("other".into()) },
                LocalDecl { index: 3, ty: i32t(), name: None },
                LocalDecl { index: 4, ty: i32t(), name: None },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Use(Operand::Copy(Place {
                            local: 1,
                            projections: vec![Projection::Deref],
                        })),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(4),
                        rvalue: Rvalue::Use(Operand::Copy(Place {
                            local: 2,
                            projections: vec![Projection::Deref],
                        })),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Cmp,
                            Operand::Move(Place::local(3)),
                            Operand::Move(Place::local(4)),
                        ),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            arg_count: 2,
            return_ty: ordering_ty(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn sem_cmp_binop_adt_return3_shape_of_recognizes_ord_cmp() {
    let func = cmp_binop_func();
    let shape = sem_cmp_binop_adt_return3_shape_of(&func)
        .expect("the Ord::cmp BinOp::Cmp three-way-compare shape must be recognized");
    assert_eq!(shape.enum_name, "cmp::Ordering");
    let SemCondTree::Leaf(c1) = &shape.cond1 else { panic!("cond1 must be a bare leaf") };
    assert_eq!(c1.op, SemCmpOp::Lt);
    assert_eq!(c1.a, SemOperand::Var(0));
    assert_eq!(c1.b, SemOperand::Var(1));
    let SemCondTree::Leaf(c2) = &shape.cond2 else { panic!("cond2 must be a bare leaf") };
    assert_eq!(c2.op, SemCmpOp::Eq);
    assert_eq!(c2.a, SemOperand::Var(0));
    assert_eq!(c2.b, SemOperand::Var(1));
    assert_eq!(shape.arm_a, SemAdtArm { variant: -1, payload: None }); // Less
    assert_eq!(shape.arm_b, SemAdtArm { variant: 0, payload: None }); // Equal
    assert_eq!(shape.arm_c, SemAdtArm { variant: 1, payload: None }); // Greater
    assert_eq!(
        crate::trustir_adt::check_adt_return3_refinement(&shape),
        crate::trustir_anchor::RefinementVerdict::ProvenModulo3
    );
}

