// -------------------------------------------------------------------
// MULTI-VALUE SwitchInt disjunctive-equality guard (2026-07-08) — the
// `is_ascii_whitespace`-class shape. `is_ascii_whitespace_func` mirrors the
// REAL `core` dump BYTE-FOR-BLOCK
// (`crates/trust-clean/fixtures/multi-eq-corpus/num__<impl u8>__is_ascii_whitespace.json`):
//
//   bb0: SwitchInt((*_1)) {9→bb2, 10→bb2, 12→bb2, 13→bb2, 32→bb2, _→bb1}
//   bb1: _0 := false;  Goto bb3
//   bb2: _0 := true;   Goto bb3
//   bb3: Return
// -------------------------------------------------------------------

fn is_ascii_whitespace_func() -> trust_types::VerifiableFunction {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
        Statement, Terminator, Ty, VerifiableBody, VerifiableFunction,
    };
    let u8t = || Ty::Int { width: 8, signed: false };
    VerifiableFunction {
        name: "is_ascii_whitespace".into(),
        def_path: "num::<impl u8>::is_ascii_whitespace".into(),
        span: Default::default(),
        body: VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl {
                    index: 1,
                    ty: Ty::Ref { mutable: false, inner: Box::new(u8t()) },
                    name: Some("self".into()),
                },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Copy(Place {
                            local: 1,
                            projections: vec![Projection::Deref],
                        }),
                        targets: vec![
                            (9, BlockId(2)),
                            (10, BlockId(2)),
                            (12, BlockId(2)),
                            (13, BlockId(2)),
                            (32, BlockId(2)),
                        ],
                        otherwise: BlockId(1),
                        exhaustive_enum_unreachable: false,
                        span: Default::default(),
                    },
                },
                // bb1 (no match): _0 := false.
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(false))),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(3)),
                },
                // bb2 (matched one of the 5 values): _0 := true.
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Bool(true))),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Goto(BlockId(3)),
                },
                BasicBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 1,
            return_ty: Ty::Bool,
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
    }
}

#[test]
fn sem_cf_return_of_mir_multi_eq_recognizes_is_ascii_whitespace() {
    let func = is_ascii_whitespace_func();
    let shape = sem_cf_return_of_mir_multi_eq(&func)
        .expect("the multi-value SwitchInt shape must be recognized");
    assert_eq!(shape.discr, SemOperand::Var(0));
    assert_eq!(shape.values, vec![9, 10, 12, 13, 32]);
    assert_eq!(shape.then_op, SemOperand::Const(1)); // true, bool_as_int.
    assert_eq!(shape.else_op, SemOperand::Const(0)); // false.
}

