/// The cascade: once a saturating METHOD certifies (via the arity-2 intrinsic
/// lane) it registers as a certified callee, and a forwarder `w_i32_saturating_add`
/// = `_0 = saturating_add(_1, _2); return` flips FULLY_FAITHFUL through the
/// certified-callee CALL-return lane. Mirror the diagnose tool's callees-first
/// registration to prove the composition end-to-end.
#[test]
fn saturating_method_certifies_then_forwarder_flips_via_call_return() {
    let method = load_num_dump("dumps/num__<impl i32>__saturating_add.json");
    // (1) The method certifies with an EMPTY registry (the intrinsic lane needs no
    //     callee registry) — it is a certified leaf.
    let empty = std::collections::BTreeMap::new();
    assert!(
        function_fully_faithful_witness_with_callees(&method, &empty)
            .is_some_and(|c| c.is_modulo_3()),
        "saturating_add method must certify modulo 3 as a leaf"
    );
    // (2) Register it as a certified callee, then the REAL forwarder
    //     `w_i32_saturating_add` = `_0 = saturating_add(_1, _2); return` resolves
    //     through the registry CALL-return lane and certifies modulo 3.
    let mut certified = std::collections::BTreeMap::new();
    certified.insert(method.def_path.clone(), CalleeFact::of_certified(&method));
    let forwarder = load_num_dump("dumps/w_i32_saturating_add.json");
    let sem = sem_call_return_of_mir(&forwarder, &certified);
    assert!(sem.is_some(), "forwarder call to certified saturating_add must be recognized");
    assert_eq!(sem.unwrap().args.len(), 2, "forwarder passes both args");
    assert!(
        function_fully_faithful_witness_with_callees(&forwarder, &certified)
            .is_some_and(|c| c.is_modulo_3()),
        "forwarder must flip FULLY_FAITHFUL via the certified-callee cascade"
    );
}

/// FAIL-CLOSED: a PARTIAL arity-2 intrinsic (`unchecked_add`, UB on overflow) with
/// the SAME body shape as `saturating_add` must NOT admit — the arity gate alone is
/// not enough; the def-path classification is the load-bearing pin. Also: the wrong
/// arity (a saturating call with 1 or 3 args) declines.
#[test]
fn saturating_recognizer_fails_closed_on_partial_and_wrong_arity() {
    use trust_types::{Operand, Place, Terminator};
    let genuine = load_num_dump("dumps/num__<impl i32>__saturating_add.json");
    assert!(
        sem_intrinsic_call_return_of_mir(&genuine).is_some(),
        "sanity: genuine saturating_add recognized"
    );

    // P1 — a PARTIAL intrinsic (unchecked_add, UB on overflow) in the exact same
    //      arity-2 body shape. MUST decline (partiality is not modeled).
    let mut f = genuine.clone();
    if let Terminator::Call { func: callee, .. } = &mut f.body.blocks[0].terminator {
        *callee = "std::intrinsics::unchecked_add::<i32>".to_string();
    }
    assert!(
        sem_intrinsic_call_return_of_mir(&f).is_none(),
        "partial unchecked_add must decline even at arity 2"
    );

    // P2 — genuine saturating_add def-path but WRONG arity (a third argument).
    let mut f = genuine.clone();
    if let Terminator::Call { args, .. } = &mut f.body.blocks[0].terminator {
        args.push(Operand::Copy(Place::local(1)));
    }
    assert!(sem_intrinsic_call_return_of_mir(&f).is_none(), "arity 3 must decline");

    // P3 — genuine saturating_add def-path but only ONE argument.
    let mut f = genuine.clone();
    if let Terminator::Call { args, .. } = &mut f.body.blocks[0].terminator {
        args.truncate(1);
    }
    assert!(sem_intrinsic_call_return_of_mir(&f).is_none(), "arity 1 must decline");

    // P4 — a fake wrapper crate claiming the saturating def-path.
    let mut f = genuine.clone();
    if let Terminator::Call { func: callee, .. } = &mut f.body.blocks[0].terminator {
        *callee = "evil::intrinsics::saturating_add::<i32>".to_string();
    }
    assert!(sem_intrinsic_call_return_of_mir(&f).is_none(), "forged crate must decline");
}

