#[test]
fn payload_extract_recognizes_result_i32_u8_unwrap_or() {
    // Result has post-join DROP-ELABORATION switches (extra 2-target
    // `Discriminant` glue); the recognizer must pick the UNIQUE switch whose
    // targets are the two `_0`-writing arms (bb0), not the glue.
    let f = load_payload_dump("std::result::Result::<i32, u8>::unwrap_or");
    let s = sem_adt_payload_extract_of_discriminant_switch(&f)
        .expect("Result::<i32,u8>::unwrap_or must be recognized past the drop glue");
    assert_eq!(s.extract_variant, 0, "Ok is variant 0 (the payload arm)");
    assert_eq!(s.extract_field_idx, 0);
    assert_eq!(s.default_var, 1);
}

/// SOUNDNESS BOUNDARY: `unwrap_or_default`'s None arm is a `__trust_total_clone`
/// HAVOC sentinel Call writing `_0` — NOT a value-faithful `Use(<param>)`
/// default. The recognizer MUST decline (it never models the sentinel as 0).
#[test]
fn payload_extract_declines_unwrap_or_default_trust_total_clone() {
    let f = load_payload_dump("std::option::Option::<i32>::unwrap_or_default");
    assert!(
        sem_adt_payload_extract_of_discriminant_switch(&f).is_none(),
        "unwrap_or_default's __trust_total_clone None arm MUST decline (havoc sentinel, \
         not a concrete 0 — a certificate here would be FALSE)"
    );
}

/// ADVERSARIAL: a `_0 := Discriminant(_1)` payload arm (returns the raw tag)
/// has no `Downcast.Field` read ⇒ declines (the uninterpreted tag is never
/// mis-extracted as the value).
#[test]
fn payload_extract_declines_discriminant_as_payload() {
    use trust_types::{Place, Rvalue, Statement};
    let mut f = load_payload_dump("std::option::Option::<i32>::unwrap_or");
    // Rewrite the Some arm (bb3) `_0` write to read the raw discriminant.
    let bb3 = f.body.blocks.iter_mut().find(|b| b.id.0 == 3).expect("bb3");
    bb3.stmts = vec![Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Discriminant(Place::local(1)),
        span: Default::default(),
    }];
    assert!(
        sem_adt_payload_extract_of_discriminant_switch(&f).is_none(),
        "a Discriminant-as-payload Some arm must decline"
    );
}

/// ADVERSARIAL: a `Downcast(v)` index != the switch tag routing to that block
/// breaks the TAG↔DOWNCAST provenance triple ⇒ declines.
